SELECT 'moj-all-verified-judgments-review-002-chunk-146' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"b01eb5c5-75c9-5ec2-9d90-45292a6cf71a","document_type":"judgment","category":"judicial","subcategory":"general","title":"منع من السفر -مطالبة باملنع من السفر حلن الفصل يف قضية منظورة -قاضي األصل هو قاضي الفرع -ناظر الدعوى األصلية مختص بطلب املنع من السفر -مصادقة املدعى عليه على وجود دعوى منظورة ضده -االستعانة بأهل اخلبرة يف تقدير التأمن الازم للممنوع من السفر -إيداع التأمن يف بيت مال المحكمة - احلكم باملنع من السفر حتى انتهاء القضية املنظورة .","document_number":"34353441","case_number":"34474747","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بحائل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/6","year":"1434","subject":"منع من السفر -مطالبة باملنع من السفر حلن الفصل يف قضية منظورة -قاضي األصل هو قاضي الفرع -ناظر الدعوى األصلية مختص بطلب املنع من السفر -مصادقة املدعى عليه على وجود دعوى منظورة ضده -االستعانة بأهل اخلبرة يف تقدير التأمن الازم للممنوع من السفر -إيداع التأمن يف بيت مال المحكمة - احلكم باملنع من السفر حتى انتهاء القضية املنظورة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/11/6 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34353441 :‬‬\n                        ‫َر ْق ُم الدعوى‪34474747 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n               ‫‪ 34369155‬تاريخه‪1434/11/25:‬هـ‬\n\n\n     ‫منــع مــن الســفر‪ -‬مطالبــة باملنــع مــن الســفر حلــن الفصــل يف قضيــة‬\n     ‫منظــورة ‪ -‬قاضــي األصــل هــو قاضــي الفــرع ‪ -‬ناظــر الدعــوى األصليــة‬\n     ‫مختــص بطلــب املنــع مــن الســفر‪ -‬مصادقــة املدعــى عليــه علــى وجــود‬\n     ‫دعــوى منظــورة ضــده ‪ -‬االســتعانة بأهــل اخلبــرة يف تقديــر التأمــن‬\n     ‫الــازم للممنــوع مــن الســفر‪ -‬إيــداع التأمــن يف بيــت مــال احملكمــة ‪-‬‬\n                 ‫احلكــم باملنــع مــن الســفر حتــى انتهــاء القضيــة املنظــورة ‪.‬‬\n\n\n\n\n                ‫املادة ‪ 4/236‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي بأنــه تقــدم بدعــوى ضــد املدعــى عليــه يف مطالبــة ماليــة‬\n     ‫منظــورة لــدى ناظــر هــذه الدعــوى ويطلــب منــع املدعــى عليــه مــن الســفر‬\n     ‫حتــى انتهــاء القضيــة األصليــة هكــذا ادعــى ‪ -‬أجــاب املدعــى عليــه‬\n     ‫باملصادقــة علــى وجــود دعــوى ماليــة مازالــت منظــورة ويطلــب صــرف‬\n     ‫النظــر عــن الدعــوى ‪ -‬جــرت الكتابــة لهيئــة اخلبــراء لتقديــر التأمــن‬\n     ‫الــازم ملثــل ذلــك وفق ـ ًا للمــادة‪ 4/236‬مــن نظــام املرافعــات الشــرعية ‪-‬‬\n     ‫ورد قرارهــم بــأن مقــدار التأمــن خمســة آالف ريــال ‪ -‬قــدم املدعــي مبلــغ‬\n     ‫التأمــن مبوجــب الشــيك ألمــر رئيــس احملكمــة ‪ -‬وبنــاء علــى املــادة ‪236‬‬\n‫‪57‬‬\n\f‫مــن نظــام املرافعــات الشــرعية والئحتــه ‪ -‬احلكــم مبنــع املدعــى عليــه‬\n‫مــن الســفر حتــى انتهــاء القضيــة املنظــورة بينــه وبــن املدعــي ‪ -‬اعتــرض‬\n‫املدعــى عليــه بالئحــة ‪ -‬صــدق احلكــم مــن الدائــرة احلقوقيــة األولــى‬\n                                    ‫مبحكمــة االســتئناف مبنطقــة حائــل ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة العامــة‬\n‫بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بحائــل املســاعد برقــم ‪ 34474747‬وتاريــخ ‪ 1434/10/26‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 342422134‬وتاريــخ ‪ 1434/10/26‬ه ـ‬\n‫ففــي يــوم اخلميــس املوافــق‪ 1434/10/29‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪ 11 : 00‬وفيهــا حضــر ‪ ...... ......‬ســعودي اجلنســية مبوجــب الســجل‬\n‫ا عــن ‪ ......‬مبوجــب الوكالــة الصــادرة مــن‬           ‫املدنــي رقــم ‪ ......‬وكي ـ ً‬\n‫كتابــة العــدل الثانيــة بالدمــام رقــم ‪ 34627806‬وتاريــخ ‪1434/5/18‬ه ـ‬\n‫املخــول لــه فيهــا حــق املرافعــة واملدافعــة وســماع الدعــاوى والــرد‬\n‫عليهــا واإلنــكار وطلــب اليمــن ورده واالمتنــاع عنــه وإحضــار الشــهود‬\n‫والبينــات والطعــن فيهــا وطلــب املنــع مــن الســفر ورفعــه وقبــول االحــكام‬\n‫ونفيهــا واالعتــراض علــى األحــكام وطلــب االســتئناف ولــه حــق توكيــل‬\n‫غيــره فادعــى علــى احلاضــر معــه يف املجلــس الشــرعي ‪ ...... ......‬مصــري‬\n‫ا يف تقريــر دعــواه ضــده إنــه‬    ‫اجلنســية مبوجــب اإلقامــة رقــم ‪ ......‬قائ ـ ً‬\n‫يوجــد لــدى فضيلتكــم ملوكلــي دعــوى ضــد املدعــى عليــه مقيــدة برقــم‬\n‫‪ 1/4944‬يف ‪1431/7/22‬ه ـ بشــأن مطالبــة ماليــة ومــا زالــت قيــد النظــر‬\n‫لــذا أطلــب منــع املدعــى عليــه مــن الســفر حتــى انتهــاء القضيــة املذكــورة‬\n\n                                                                                         ‫‪58‬‬\n\f     ‫وتنفيذهــا هــذه دعــواي وبعرضهــا علــى املدعــى عليــه قــال مــا ذكــره‬\n     ‫املدعــي وكالــة صحيــح وأنــا مــن ســت ســنوات لــم أســافر وأطلــب صــرف‬\n     ‫النظــر عــن دعــوى املدعــي وكالــة ألنهــا كيديــة هكــذا أجــاب وعليــه‬\n     ‫قــررت الكتابــة لهيئــة اخلبــراء لتقديــر التأمــن الــازم ملثــل ذلــك حســب‬\n     ‫املــادة رقــم ‪ 4/236‬مــن نظــام املرافعــات ولوائحــه ورفعــت لذلــك اجللســة‬\n     ‫ويف جلســة أخــرى وفيهــا حضــر املدعــي وكالــة و املدعــى عليــه ‪ ،‬وقــد‬\n     ‫وردنــا كتــاب رئيــس هيئــة اخلبــراء باحملكمــة رقــم ‪ 342496266‬يف‬\n     ‫‪1434/11/6‬ه ـ مرفقـ ًا بــه قــرار الهيئــة املتضمــن تقديــر التأمــن الــازم‬\n     ‫ملنــع املدعــى عليــه مــن الســفر بخمســة آالف ريــال ‪ ،‬وبعرضــه علــى‬\n     ‫املدعــي قــال ‪ :‬المانــع لــدي مــن إيــداع التأمــن املذكــور ‪ ،‬وقــدم الشــيك‬\n     ‫املســحوب علــى مصــرف ‪ ......‬برقــم ‪ 275938‬وتاريــخ ‪1434/10/18‬ه ـ‬\n     ‫مببلــغ خمســة آالف ريــال ألمــر رئيــس محاكــم منطقــة حائــل فجــرى‬\n     ‫ـاء علــى‬\n            ‫ضمــه مللــف الدعــوى إليداعــه الحقـ ًا يف حســاب احملكمــة ‪ ،‬فبنـ ً‬\n     ‫ماتقــدم مــن الدعــوى واإلجابــة املتضمنــة مصادقــة املدعــى عليــه علــى‬\n     ‫وجــود دعــوى قائمــة ضــده وال زالــت قيــد النظــر ‪ ،‬وبنــاء علــى قــرار هيئــة‬\n     ‫اخلبــراء املشــار إليــه أعــاه وبنــاء علــى املــادة ‪ 236‬مــن نظــام املرافعــات‬\n     ‫ولوائحــه فقــد قــررت منــع الدعــى عليــه مــن الســفر حتــى انتهــاء القضيــة‬\n     ‫املنظــورة بينــه وبــن املدعــي املشــار إلــى رقمهــا ســلف ًا وبذلــك حكمــت ‪،‬‬\n     ‫وبعــرض احلكــم اعتــرض املدعــى عليــه ‪ ،‬وقــدم اســتدعائه املقيــد بهــذه‬\n     ‫احملكمــة برقــم ‪ 34/2534325‬بتاريــخ ‪1434/11/6‬ه ـ وطلــب رفعــه‬\n     ‫حملكمــة االســتئناف معتبــر ًا االســتدعاء الئحــة اعتراضيــة لــه وبــاهلل‬\n                                                 ‫التوفيــق حــرر يف ‪1434/11/6‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة‬\n\n\n‫‪59‬‬\n\f‫األولــى لتدقيــق القضايــا احلقوقيــة مبحكمــة االســتئناف مبنطقــة‬\n‫حائــل علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بحائــل املســاعد برقــم ‪342422134‬وتاريــخ ‪1434/11/18‬ه ـ واملقيــدة‬\n‫لدينــا بتاريــخ ‪1434/11/20‬ه ـ املرفــق بهــا الصــك رقــم ‪34353441‬يف‬\n‫‪1434/11/6‬ه ـ الصــادر مــن فضيلــة القاضــي‪ ....../‬اخلــاص بدعــوى ‪......‬‬\n‫وكالــة ضــد ‪ ......‬مصــري اجلنســية بشــأن دعــوى منــع مــن الســفر علــى‬\n‫الصفــة املوضحــة يف الصــك وقــد تضمــن الصــك حكــم فضيلتــه كمــا‬\n‫هــو مــدون ومفصــل فيــه وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة لــم يظهــر مــا يوجــب املالحظــة لــذا جــرت‬\n‫املصادقــة واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                         ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪60‬‬\n\f61\n\f62\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":57,"source_page_end":62,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2a9f7ccc443e7ea1831c7b02f827e00e1f689659d86e53fa5d9d35a163a49771","normalized_text_hash":"ebe0f17b1298e60b674481ad420948749512b1a44909d5eb608fadf8ac9192d2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p57-34353441"},{"id":"80d49d17-e42c-5fd3-956f-34921f5428c6","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة برد مسروق -سرقة مبالغ مالية من سيارة نقل األموال- تفريط يف حفظ املسروق -عجز عن إثبات الدفع -إدخال خصم جديد يف الدعوى -رد الدعوى عن اخلصم املدخل -ضمان األجير اخلاص -ثبوت الدعوى .","document_number":"33192872","case_number":"323066","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باخلبر املساعد احلمد هلل وحده","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/4/17","year":"1434","subject":"مطالبة برد مسروق -سرقة مبالغ مالية من سيارة نقل األموال- تفريط يف حفظ املسروق -عجز عن إثبات الدفع -إدخال خصم جديد يف الدعوى -رد الدعوى عن اخلصم املدخل -ضمان األجير اخلاص -ثبوت الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/4/17 :‬هـ‬\n                     ‫ُ‬                 ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪33192872 :‬‬\n                           ‫َر ْق ُم الدعوى‪323066:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3410902‬تاريخه‪1434/1/13:‬هـ‬\n\n\n     ‫مطالبــة بــرد مســروق ‪ -‬ســرقة مبالــغ ماليــة مــن ســيارة نقــل األمــوال‪-‬‬\n     ‫تفريــط يف حفــظ املســروق‪ -‬عجــز عــن إثبــات الدفــع ‪ -‬إدخــال خصــم‬\n     ‫جديــد يف الدعــوى ‪ -‬رد الدعــوى عــن اخلصــم املدخــل‪ -‬ضمــان األجيــر‬\n                                                 ‫اخلــاص‪ -‬ثبــوت الدعــوى ‪.‬‬\n\n\n\n\n     ‫‪ -1‬قــول النبــي صلــى اهلل عليــه وآلــه وســلم‪ ( :‬علــى اليــد مــا أخــذت حتــى‬\n                               ‫تؤديــه ) رواه أحمــد واألربعــة وصححــه احلاكم‪.‬‬\n     ‫‪ -2‬األجير اخلاص ال يضمن إال يف حال التعدي أو التفريط‪ .‬الروض‬\n                            ‫املربع للبهوتي مع حاشــية بن قاســم (ج‪ 5‬ص‪.)336‬‬\n                                    ‫‪ -3‬املادة (‪ )76‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n     ‫ادعــى وكيــل الشــركة املدعيــة بــأن املدعــى عليهمــا احلاضريــن اســتلما‬\n     ‫مــن موكلتــه َّإبــان عملهمــا لديهــا كمشــريف تغذيــة صرافــات آليــة‬\n     ‫مبالــغ ماليــة لكــي يقومــا بتغذيــة عــدد مــن الصرافــات اآلليــة بهــا إال‬\n     ‫أنهمــا ادعيــا أن تلــك املبالــغ ســرقت منهمــا‪ ،‬ولــذا فقــد طلــب إلزامهمــا‬\n     ‫بإعــادة املبالــغ املســروقة متضامنــن إلــى الشــركة موكلتــه ‪ -‬أقــر‬\n     ‫املدعــى عليهمــا باســتالم املبالــغ املاليــة محــل الدعــوى ودفــع كل واحــد‬\n\n‫‪63‬‬\n\f‫منهمــا بأنــه لــم يفــرط يف حفــظ األمــوال املســروقة ولذلــك فهــو غيــر‬\n‫مســتعد بتســليم املدعيــة أي شــيء مــن تلــك املبالــغ ‪ -‬املدعــى عليــه الثانــي‬\n‫دفــع أيض ـ ًا بــأن املدعــى عليــه األول وشــخص ثالــث كان معهمــا همــا‬\n‫مــن قامــا باالســتيالء علــى املبلــغ املدعــى بــه إال أنــه لــم يقــدم بينــة موصلــة‬\n‫علــى هــذا الدفــع ‪ -‬قــررت احملكمــة إدخــال الشــخص الثالــث املرافــق‬\n‫للمدعــى عليهمــا يف الدعــوى وعرضــت عليــه مــا اتهمــه بــه املدعــى عليــه‬\n‫الثانــي فأنكــر ذلــك وأدى اليمــن علــى نفــي تلــك الدعــوى ‪ -‬وملــا كان‬\n‫املدعــى عليهمــا أجيريــن خاصــن فيضمنــان بالتعــدي أو التفريــط‬\n‫واحلكــم الصــادر يف احلــق العــام يدينهمــا بالتفريــط ‪ -‬قضــت احملكمــة‬\n‫بإلــزام املدعــى عليهمــا بتســليم الشــركة املدعيــة املبلــغ املدعــى بــه‬\n‫متضامنــن فيتحمــل كل واحــد منهمــا نصــف املبلــغ وللمدعيــة مطالبــة‬\n‫أحدهمــا بكامــل املبلــغ احملكــوم بــه ولــه الرجــوع علــى صاحبــه بســداد‬\n‫مــا دفعــه للشــركة‪ ،‬وصرفــت النظــر عــن دعــوى املدعــى عليــه الثانــي‬\n‫ضــد املدخــل لعــدم ثبوتهــا‪ -‬عــارض املدعــى عليهمــا علــى احلكــم‪-‬‬\n                     ‫قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫لدي أنا ‪ ...‬رئيس احملكمة العامة باخلبر املساعد‬   ‫احلمد هلل وحده وبعد ّ‬\n‫ـاء علــى املعاملــة احملالــة لــي برقــم ‪ 323066‬وتأريــخ ‪1432/01/05‬ه ـ‬‫وبنـ ً‬\n‫املقيــدة باحملكمــة برقــم ‪ 328408‬وتاريــخ ‪1432/1/5‬ه ففــي يــوم‬\n‫االثنــن املوافق‪1432/04/23‬ه ـ حضــر ‪ ...‬ســعودي بالســجل املدنــي‬\n‫رقــم ‪ ...‬بالوكالــة عــن ‪ ...‬ســعودي بالســجل املدنــي رقــم ‪ ...‬أصالــة عــن‬\n‫نفســه ومبوجــب وكالتــه عــن ‪ ...‬وهمــا أصحــاب شــركة ‪ ....‬ملعــدات‬\n\n                                                                                             ‫‪64‬‬\n\f     ‫األمــن والســامة والتجــارة احملــدودة وذلــك كلــه مبوجــب الوكالــة‬\n     ‫الصــادرة مــن مســاعد رئيــس كتابــة عــدل اخلبــر الثانيــة برقــم ‪1187‬‬\n     ‫يف ‪1429/1/11‬ه ـ جلــد ‪ 1670‬وهــذه الوكالــة تخــول الوكيــل حــق‬\n                                              ‫املرافعــة وحضــر حلضــوره كل مــن‪:‬‬\n     ‫‪ / -1‬ســعودي بالســجل املدنــي رقــم ‪ / -2‬ســعودي بالســجل املدنــي رقــم‬\n     ‫بالوكالــة عــن ‪ /‬ســعودي بالســجل املدنــي رقــم وذلــك مبوجــب الوكالــة‬\n     ‫الصــادرة مــن كتابــة عــدل القطيف برقم ‪ 3278227‬يف ‪1432/4/22‬هـ‬\n     ‫وهــذه الوكالــة تخــول الوكيــل حــق املدافعــة ثــم ادعــى ‪ ....‬بقولــه‪ :‬إن‬\n     ‫كل‬‫لشــركة ‪ ....‬ملعــدات األمــن والســامة والتجــارة احملــدودة بذمــة ٍ‬\n     ‫مــن‪ :‬مبلغـ ًا قــدره مليــون وســبعة وســبعون ألفـ ًا وســتون ريــا ًال ( ‪1077060‬‬\n     ‫ريــال ) حيــث يتحمــل املدعــى عليهمــا كامــل هــذا املبلــغ متضامنــن‬\n     ‫وســبب ذلــك أن املدعــى عليهمــا يعمــان لــدى الشــركة املدعيــة‬\n     ‫ومســمى وظيفتهمــا مشــريف تغذيــة صرافــات آليــة للبنــك ‪ ....‬حيــث إن‬\n     ‫بــن الشــركة املدعيــة والبنــك ‪ ....‬عقــد ًا يف ذلــك وقــد اســتلم املدعــى‬\n     ‫عليهمــا املبلــغ املدعــى بــه علــى النحــو التالــي‪ -1 :‬مبلغـ ًا قــدره خمســمائة‬\n     ‫وخمســون ألــف ريــال مت اســتالمه مــن البنــك ‪ ....‬لتغذيــة الصــراف اآللــي‬\n                                                                          ‫مبحطــة ‪.....‬‬\n     ‫‪ -2‬مبلغ ـ ًا قــدره ثالثمائــة وواحــد وخمســون ألف ـ ًا وثمامنائــة ريــال مت‬\n     ‫اســتالمه كرجيــع مــن الصــراف اآللــي رقــم ( ‪ ) 3111‬بالثقبــة ‪ -3‬مبلغـ ًا‬\n     ‫قــدره مئــة وخمســة وســبعون ألفـ ًا ومئتــان وســتون ريــا ًال مت اســتالمه مــن‬\n     ‫جهــاز إيــداع مــن الصــراف اآللــي رقــم ( ‪ ) 311‬بالثقبــة وأثنــاء توقــف‬\n     ‫الســيارة التــي حتمــل جميــع هــذه املبالــغ عنــد مجمــع ‪ ....‬التجــاري حســب‬\n     ‫زعــم املدعــى عليهمــا ســرقت مــن الســيارة جميــع هــذه املبالــغ وكان‬\n\n\n‫‪65‬‬\n\f‫ذلــك بتاريــخ ‪2008/8/13‬م لــذا فإنــي أطلــب ســؤال املدعــى عليهمــا‬\n‫هذيــن احلاضريــن وإلــزام ‪ ......‬و‪ ......‬بإعــادة هــذه املبالــغ للشــركة‬\n‫موكلتــي علم ـ ًا أن البنــك ‪ ....‬قــد خصــم هــذه املبالــغ مــن اســتحقاقات‬\n‫الشــركة املدعيــة لديــه هكــذا ادعــى ‪ ،‬ويف جلســة أخــرى حضر املدعي‬\n‫وكالــة وحضــر حلضــوره املدعــى عليــه أصالــة ‪ /‬ولــم يحضـ ــر املدعـ ــى‬\n‫عليـ ــه ‪ /‬وال أي وكيــل عنــه ثــم طلبــت مــن املدعــى عليــه ‪ /‬اجلــواب علــى‬\n‫الدعــوى فقــال‪ :‬إننــي غيــر مســتعد بدفــع أي شــيء مــن املبلــغ املدعــى بــه‬\n‫ألننــي واملدعــى عليــه الثانــي ‪ /‬لــم نفــرط ولــم نهمــل يف عملنــا بــل نزلنــا‬\n‫ســوي ًا لتغذيــة صــراف مبجمــع الراشــد بعدمــا أغلقنــا الســيارة التــي‬\n‫يوجــد بداخلهــا مفتــاح الصنــدوق اخللفــي للســيارة واملوجــود بــه املبالــغ‬\n‫املاليــة ولــم تكــن ترافقنــا وقــت نزولنــا للصــراف أي دوريــة تابعــة‬\n‫للشــرطة حيــث لــم نطلــب ذلــك ولــم ترافقنــا أي ســيارة أمــن مدنيــة حيــث‬\n‫لــم تؤمــن لنــا الشــركة ذلــك وأثنــاء نزولنــا حصــل االعتــداء على الســيارة‬\n‫وســرقة املبالــغ املشــار إليهــا بالدعــوى مــن الســيارة علم ـ ًا أننــي أصــادق‬\n‫على است ــام املبال ــغ املشـ ــار إليهـ ــا بدع ــوى املدعي ويشاركني يف ذلك‬\n‫زميلــي املدعــى عليــه ‪ /‬ولســماع جــواب املدعــى عليــه اآلخــر فقــد رفعــت‬\n‫اجللســة ‪ ،‬ويف جلســة أخــرى حضــر ‪ /‬ســعودي بالســجل املدنــي رقــم‬\n‫بالوكالــة عــن ‪ /‬ســعودي بالســجل املدنــي رقــم أصالــة عــن نفســه‬\n‫ومبوجــب وكالتــه عــن ‪ /‬وهمــا أصحــاب شــركة ‪ ....‬ملعــدات األمــن‬\n‫والســامة والتجــارة احملــدودة وذلــك كلــه مبوجــب الوكالــة الصــادرة‬\n‫مــن مســاعد رئيــس كتابــة عــدل اخلبــر الثانيــة برقــم ‪ 1187‬يف‬\n‫‪1429/1/11‬ه ـ جلــد ‪ 1670‬وهــذه الوكالــة تخــول الوكيــل حــق‬\n‫املرافعــة وحضــر حلضــوره املدعــى عليــه ‪ /‬و املدعــى عليــه وكالــة ‪ /‬ثــم‬\n\n\n                                                                                       ‫‪66‬‬\n\f     ‫طلبــت مــن املدعــى عليــه وكالــة اجلــواب على الدعوى فقــال‪ :‬إن موكلي‬\n     ‫‪ ....‬غيــر مســتعد بدفــع أي شــيء مــن املبلــغ املدعــى بــه حيــث لــم يصــدر‬\n     ‫مــن موكلــي أي فعــل يوجــب ذلــك ومهمــة موكلــي مــع املدعــى عليــه‬\n     ‫اآلخــر ‪ /‬وشــخص آخــر حيــث أن مهمــة موكلــي تنحصــر يف فتــح اخلزنــة‬\n     ‫املوجــودة بالصرافــات وإغالقهــا وإعــادة اخلدمــة مــرة أخرهــا إليهــا‬\n     ‫وإصــاح الصرافــات إذا وجــد بهــا أي خلــل حيــث إنــه فنــي يف ذلــك علمـ ًا‬\n     ‫أن موكلــي وقــع عنــد البنــك باســتالم مبلــغ مــن البنــك قــدره ثالثــة‬\n     ‫ماليــن وســبعمائة ألــف ريــال هكــذا أجــاب ثــم قــدم لــي جواب ـ ًا خطي ـ ًا‬\n     ‫من ســبع صفحات ومرفق به تســع وعشــرون لفة مت إرفاق ذلك باملعاملة‬\n     ‫األساســية وبعــرض جــواب املدعــى عليهمــا علــى املدعــي وكالــة قــال‪:‬‬\n     ‫إننــي أطلــب مهلــة إلعــداد جــواب علــى ذلــك فأجيــب لطلبــه ‪ ،‬ويف جلســة‬\n     ‫أخــرى حضــر املدعــي وكالــة واملدعــى عليــه أصالــة واملدعــى عليــه‬\n     ‫وكالــة هــذا وقــد عرضــت علــى املدعــي وكالــة جــواب املدعــى عليهمــا‬\n     ‫وطلبــت منــه اجلــواب فقــدم لــي املدعــي وكالــة مذكــرة مــن أربــع‬\n     ‫صفحــات مرفــق بهــا ثــاث لفــات وقــد تضمنــت املذكــرة تأكيــد مــا‬\n     ‫ورد بالدعــوى ومت إرفاقهــا باملعاملــة األساســية ثــم طلـ ــبت مـ ــن املدع ــي‬\n     ‫وكال ــة البينــة علــى دعــواه فقــال‪ :‬إقــرار املدعــى عليهمــا باســتالم املبلــغ‬\n     ‫املدعــى بــه وإقرارهمـ ــا بفقـ ــده وهــذا يوجــب حتملهمــا هــذا املبلــغ بنــاء‬\n     ‫علــى إقــرار املدعــى عليهمــا أمــام الشــركة موكلتــي خطيـ ًا لتحملهمــا‬\n     ‫اختــاس أو ســرقة أو ضيــاع أي مبلــغ مــن املبالــغ املســلمة لهمــا حيــث‬\n     ‫جــاء بإقــرار كل واحــد منهمــا اخلطــي لــدى الشــركة املدعيــة مــا‬\n     ‫نصه(أقــر مبوافقتــي علــى حتمــل أي اختــاس أو ســرقة أو ضيــاع أي‬\n     ‫مبلــغ مــن املبالــغ املســلمة لــي وذلــك بســداد للشــركة أو البنــك مــن‬\n\n\n‫‪67‬‬\n\f‫حســابي اخلــاص دون اعتــراض يف مــدة ال تتجــاوز رقمــا (‪ 24‬ســاعه) وأن‬\n‫مســؤوليتي هــذه ال تنتهــي بتــرك العمــل لديهــا أو إقالتــي بــل تضــل ســارية‬\n‫املفعــول لــكل املهــام والعمليــات التــي كلفتنــي الشــركة بهــا أثنــاء‬\n‫عملــي لديهــا) انتهــى نــص احلاجــة مــن اإلقــرار كمــا قــدم لــي املدعــي‬\n‫وكالــة صــورة خطــاب صــادر مــن مســاعد مدير عام مجموعــة العمليات‬\n‫املركزيــة بالبنــك ‪ ....‬الوطنــي موجــه ملجموعــة ‪ ....‬برقــم ع م‪08/067/‬‬\n‫يف ‪2010/11/10‬م وقــد جــاء يف اخلطــاب مــا نصــه نعلمكــم أنــه حصلت‬\n‫عمليــة اختــاس مــن صرافاتنــا يف املنطقــة الشــرقية يف تاريــخ‬\n‫‪ 2008/8/13‬م والتــي بعهــدة كل مــن والســيد وبإجمالــي رقمــا‬\n‫‪ 1077060‬كتابــة مليــون وســبعة وســبعني ألفــا وســتني ريــا ًال حســب‬\n‫التالــي‪ /1:‬صــراف رقــم ‪ 3272‬مببلــغ ‪ 550.000‬ريــال ‪/2‬صــراف رقــم‬\n‫‪ 3111‬مببلــغ ‪ 351.800‬ريــال ‪ /3‬صــراف رقــم ‪ 311a‬مببلــغ‬\n‫‪175.260‬ريــال لــذا فأنــه وعلــى حســب االتفاقيــة املوقعــة بيننــا فإنــه قــد‬\n‫مت تغطيــة مبلــغ الفروقــات وخصمهــا مــن مســتحقاتكم الشــهرية‪ .‬انتهــى‬\n‫كمــا أنــه كان مــع املدعــى عليهمــا شــخص ثالــث متــدرب واملتعــن‬\n‫علــى الشــخص الثالــث بقــاءه بالســيارة أثنــاء نــزول املدعــى عليهمــا‬\n‫لتغذيــة الصرافــات إال أنــه نــزل مــن الســيارة وهــذا يعــد تفريط ـ ًا مــن‬\n‫املدعى عليهما علم ًا أن الشــخص الثالث ‪ /‬املتدرب ال يتحمل مســؤولية‬\n‫أي شــيء يتعلــق باملبالــغ املوجــودة يف الســيارة هكــذا أجــاب ولعــرض‬\n‫ذلــك علــى املدعــى عليهمــا فقــد رفعــت اجللســة ‪ ،‬ويف جلســة أخرى حضر‬\n‫املدعــي وكالــة واملدعــى عليهمــا أصالــة ووكالــة ثــم قــال املدعــى عليــه‬\n‫وكالــة‪ :‬إننــي أطلــب بــأن يضــاف إلــى جوابــي عــن موكلــي بــأن ضمــان‬\n‫املــال املدعــى بــه علــى مــن يتحمــل مســؤولية حيــازة املــال ومفتــاح اخلزنــة‬\n\n\n                                                                                       ‫‪68‬‬\n\f     ‫وهــو املدعــى عليــه هكــذا أضــاف وبعــرض اإلقــرار املــدون نصــه يف‬\n     ‫اجللســة املاضيــة علــى املدعــى عليهمــا أجــاب املدعــى عليــه بقولــه‪ :‬إن‬\n     ‫هــذا اإلقــرار صــادر منــي إال أن مــا ورد بالدعــوى غيــر صحيــح كمــا‬\n     ‫ذكــرت يف جوابــي وأن هــذا االختــاس تتحملــه الشــركة لتفريطهــا يف‬\n     ‫حمايــة املــال حيــث لــم توفــر الشــركة لنــا أي دوريــة حلراســة املــال وقــد‬\n     ‫تبــن للمحقــق يف القضيــة أنــه ميكــن نســخ مفاتيــح أخــرى للخزنــة‬\n     ‫والســيارة التــي أخــذ منهــا املــال قــد عمــل بهــا مجموعــة كبيــرة مــن‬\n     ‫املوظفــن كمــا أن الشــركة تســاهلت يف توفيــر قائــد للســيارة فقــد‬\n     ‫كان القائــد غائب ـ ًا وتولــى القيــادة ‪ ....‬الــذي هــو املشــرف األول وكان‬\n     ‫يقــود الســيارة التــي بداخلهــا مفتــاح اخلزنــة والتعليمــات املوجهــة إلــي مــن‬\n     ‫الشــركة أن أقــوم بتنفيــذ جميــع تعليمــات املشــرف األول لــذا كلــه‬\n     ‫فإنــي ال أحتمــل ضمــان ســرقة هــذا املبلــغ لعدم تســببي يف ذلك ولتســاهل‬\n     ‫الشــركة كمــا ذكــرت وممــا يؤكــد ذلــك تكــرر هــذه احلادثــة خمــس‬\n     ‫مــرات تقريب ـ ًا خــال ســنتني أو ثــاث ســنوات هكــذا أجــاب كمــا‬\n     ‫أجــاب املدعــى عليــه وكالــة بقولــه‪ :‬هــذا اإلقــرار قــد صــدر مــن موكلــي‬\n     ‫إال أنــه ال يوجــب حتمــل موكلــي للمبلــغ املدعــى بــه ألن املــال ليــس بيــده‬\n     ‫ومــا ذكــره املدعــى عليــه م ــن أن موكل ــي ‪ ....‬قـ ــام بقي ــادة الســيارة وقــد‬\n     ‫ـاء علــى‬\n            ‫مت ذلــك بطلــب ومــا ذكــره املدعــى عليــه مــن أنــه يتصــرف بنـ ً‬\n     ‫توجيــه موكلــي كونــه املشــرف األول فهــذا غيــر صحيــح فلــكل واحــد‬\n     ‫مســؤوليات يتحملهــا هكــذا أجــاب ‪ ،‬ثــم ســألت املدعــى عليــه وكالــة‬\n     ‫‪ /‬هــل اشــترك موكلــك يف اســتالم املبلــغ املدعــى بــه مــع املدعــى عليــه‬\n     ‫اآلخــر فقــال‪ :‬نعــم إال أن موكلــي يتهــم املدعــى عليــه يف االســتيالء علــى‬\n     ‫املبلــغ املدعــى بــه حيــث مت جمــع كامــل هــذا املبلــغ يف كيــس واحــد ومت‬\n\n\n‫‪69‬‬\n\f‫تصريفــه مــن الســيارة وال يعلــم موكلــي كيــف مت تصريــف أو اختفــاء‬\n‫هــذا املبلــغ ويؤكــد هــذا الــكالم وقائــع عــدة وبيانهــا علــى النحــو‬\n‫التالــي‪ -1 :‬أن املدعــى عليــه واملتــدرب ‪ ....‬أخــذا قــراءة الصرافــات التــي‬\n‫ســيقومون بتغذيتهــا أو يأخــذون منهــا الرجيــع أو إيداعــات الزبائــن أخــذا‬\n‫قــراءة تلــك الصرافــات عــن طريــق هاتــف الشــقة التــي يســكنها‬\n‫واملتــدرب وهــذا يخالــف العمــل املعتــاد حيــث إن املعتــاد أن يتــم قــراءة‬\n‫الصرافــات عــن طريــق البنــك بحضــور موكلــي ‪ -2‬اســتلم موكلــي‬\n‫واملدعــى عليــه األمــوال التــي ســيغذى بهــا الصرافــات وعددهــا ســت ثــم‬\n‫أنــزل األكيــاس مــن البنــك وقامــا بتخزينهــا بالســيارة بــدون حضــور‬\n‫موكلــي حيــث تأخــر لتوقيــع أوراق االســتالم لــدى وشــخص ثانــي اســمه‬\n‫‪ -3‬بعــد اســتالم مبلـ ٍـغ مالي ـ ًا مــن صــراف البنــك ‪ .....‬فــرع الثقبــة شــارع‬\n‫مكــة ومقــدار املبلــغ خمســمائة وســبعة وعشــرون ألف ـ ًا وســتون ريــا ًال‬\n‫خــرج كل مــن‪ :‬فجــأة مــن غرفــة الصــراف املكيفــة إلــى الشــارع وكان‬\n‫اجلــو حــار ًا جــد ًا ممــا أثــار الريبــة لــدى موكلــي وعندمــا ركــب الســيارة‬\n‫لــم يجــد بالســيارة وبعــد نصــف دقيقــة تقريب ـ ًا حضــر فســأله نــادر عــن‬\n‫ســبب التأخــر فقــال‪ :‬كنــت أرتــب األكيــاس حتــى يســهل تنزيلهــا عنــد‬\n‫كل جهــاز ‪ -4‬عنــد تغذيــة صرافــن مبجمــع الراشــد للبنــك ‪ ....‬األول‬\n‫رقمــه ‪ 5‬والثانــي ‪ 3‬اختفــى عــن موكلــي مــدة عشــرين دقيقــة حيــث‬\n‫كان موكلــي يقــوم بإصــاح عطــل فنــي بالصــراف رقــم ‪ 3‬وعندمــا‬\n‫ســئل عــن تغيبــه خــال هــذه الفتــرة أفــاد بأنــه كان يتجــول يف مطاعــم‬\n‫املجمــع ‪ -5‬أن الــذي قــام بإخبــار بالســرقة هــو املدعــى عليــه لــذا فــإن‬\n‫موكلــي ال يتحمــل أي تفريــط وأن الــذي تســبب يف اختفــاء هــذا املبلــغ‬\n‫هكــذا أجــاب وبعــرض ذلــك علــى ‪ /‬قــال‪ :‬مــا ذكــره املدعــى عليــه‬\n\n\n                                                                                       ‫‪70‬‬\n\f     ‫ا فأنــا لــم أتســبب ولــم أشــارك يف‬    ‫وكالــة غيــر صحيــح جملــة وتفصي ـ ً‬\n     ‫اختفــاء أي شــيء ممــا ورد بالدعــوى وأجيــب علــى مــا ذكــره املدعــى‬\n     ‫عليــه وكالــة بشــأن أخــذ قــراءة الصرافــات مــن الشــقة فهــذا صحيــح إال‬\n     ‫أنــه أمــر متكــرر وبعلــم وأمــر املدعــى عليــه وذلــك لكثــرة مــن يقــوم‬\n     ‫بقــراءة الصرافــات بالبنــك مــن موظفــي الشــركة كمــا أن القــراءة‬\n     ‫تكــون جلميــع الصرافــات بــدون حتديــد صــراف معــن والبنــك يوجهنــا‬\n     ‫للصرافــات املطلــوب تغذيتهــا أو الســحب منهــا بــدون أي علــم ســابق منــا‬\n     ‫ومــا ذكــره املدعــى عليــه وكالــة يف الفقــرة رقــم ‪ 2‬غيــر صحيــح جملــة‬\n     ‫ا فقــد اســتلمنا أنــا و‪ .....‬األكيــاس مــن البنــك وقمنــا بإنزالهــا‬   ‫وتفصي ـ ً‬\n     ‫باالشــتراك مــع ‪ /‬ثــم قمنــا بتنزيلهــا مــن الســيارة وممــا يكــذب مــا‬\n     ‫ذكــره املدعــى عليــه أن مفتــاح الســيارة كان مــع موكلــه ‪ ....‬ومــا‬\n     ‫ذكــره املدعــى عليــه يف الفقــرة رقــم ‪ 3‬غيــر صحيــح أيض ـ ًا فقــد كان‬\n     ‫خروجــي مــن الصــراف أنــا و‪ .....‬سوي ـ ًا ث ــم ركـ ــب السيـ ــارة لقيادتها وأنا‬\n     ‫قمــت بوضــع صنــدوق الرجيــع وكيــس بــه مبلــغ مالــي ومــا ذكــره‬\n     ‫املدعــى عليــه وكالــة يف الفقــرة رقــم ‪ 5‬فغيــر صحيــح والصحيــح أننــي‬\n     ‫فتحــت اخلزنــة واســتنكرت عــدم وجــود صنــدوق رجيــع اإليــداع فســألت‬\n     ‫‪ ....‬عــن ذلــك وحتقــق مــن ذلــك كمــا اســتنكر ‪ ....‬فقــدان عــدد مــن‬\n     ‫األكيــاس فتــم إبــاغ الشــركة عــن طريــق‪ /‬لــذا فإنــي أنكــر اتهــام‬\n     ‫ـاء علــى مــا‬\n                 ‫املدعــى عليــه لــي بأخــذ أي شــيء مــن املبلــغ املدعــى بــه وبنـ ً‬\n     ‫ـاء علــى مــا نصــت عليــه املــادة ‪ 76‬مــن نظــام‬   ‫ذكــره املدعــى عليــه وبنـ ً‬\n     ‫املرافعــات الشــرعية فقــد قــررت إدخــال املدعــى عليــه‪ /‬ويف جلســة‬\n     ‫أخــرى حضــر املدعــي وكالــة ‪ /‬ســعودي بالســجل املدنــي رقــم بالوكالة‬\n     ‫عــن ‪ /‬ســعودي بالســجل املدنــي رقــم بصفتــه شــريك يف شــركة ‪....‬‬\n\n\n‫‪71‬‬\n\f‫ملعــدات األمــن والســامة والتجــارة احملــدودة حســب الوكالــة املشــار‬\n‫إلــى مصدرهــا ورقمهــا وتاريخهــا يف اجللســة املاضيــة وحضــر حلضــوره‬\n‫املدعــى عليهمــا أصالــة و‪ /‬ســعودي بالســجل املدنــي رقــم كمــا حضــر‬\n‫املدخــل ‪ /‬ســعودي بالســجل املدنــي رقــم ثــم عرضــت علــى املدعــى عليــه‬\n‫أصالـ ــة جميــع اإلجابــات التــي أدلــى بهــا وكيلــه يف اجللســات املاضيــة‬\n‫جميعهــا فقــال‪ :‬إننــي أصــادق علــى كل مــا أجــاب بــه وكيلــي املذكــور‬\n‫هكــذا أجــاب ثــم عرضــت علــى املدخــل ‪ ....‬مــا ذكــره وكيــل املدعــى‬\n‫عليــه يف اجللســة املاضيــة فقــال‪ :‬مــا ذكــره وكيــل املدعــى عليــه غيــر‬\n‫صحيــح فأنــا لــم أســتولي علــى املبلــغ املدعــى بــه ولــم أشــارك يف إخفائــه‬\n‫ـدي أي علــم بذلــك وأنــا كنــت متدربـ ًا أعمــل مــع املدعــى عليهمــا‬  ‫وليــس لـ ّ‬\n‫واســتمر عملــي مــع الشــركة املدعيــة مــدة ال تزيــد عــن شــهر ومــا ذكــره‬\n‫وكيــل املدعــى عليــه مــن وقائــع اســتند علــى دعــواه فيهــا فــكل مــا جــاء‬\n‫يف هــذه الوقائــع غيــر صحيــح هكــذا أجــاب ثــم ســألت املدعــى عليــه ‪:...‬‬\n‫هــل لديــه زيــادة بينــة علــى مــا ذكــره وكيلــه مــن مشــاركة املدخــل ‪....‬‬\n‫مــع املدعــى عليــه يف إخفــاء املبلــغ املدعــى بــه واالســتيالء عليــه فقــال‪ :‬ال‬\n‫ثــم أفهمــت املدعــى عليــه نــادر النزغــة بــأن لــه ميــن املدخــل اآلتــي نصهــا‪:‬‬\n‫( واهلل الــذي ال إلــه إال هــو احلــي القيــوم بأننــي لــم أســتولي علــى املبلــغ‬\n‫املدعــى بــه مــن قبــل شــركة ‪ ....‬ملعــدات األمــن والســامة والتجــارة‬\n‫احملــدودة وقــدره مليــون وســبعة وســبعون ألفـ ًا وســتون ريــا ًال ولــم أشــارك‬\n‫ـدي أي علــم بذلــك واهلل العظيــم ) انتهــى‬   ‫يف إخفــاء هــذا املبلــغ وليــس لـ ّ‬\n‫نــص اليمــن ‪ ،‬وبعــرض هــذا اليمــن وهــذا النــص علــى املدعــى عليــه‬\n‫فقــال‪ :‬إننــي أطلــب مــن املدخــل أن يــؤدي هــذه اليمــن ثــم حلــف ‪ ....‬بنــص‬\n‫اليمــن املــدون بعاليــه ثــم جــرى منــي االطــاع علــى القــرار الشــرعي‬\n\n\n                                                                                         ‫‪72‬‬\n\f     ‫الصــادر مــن فضيلــة القاضــي باحملكمــة اجلزئيــة باخلبــر الشــيخ ‪ /‬برقــم‬\n     ‫‪ 4/74‬وتاريــخ ‪1430/3/17‬ه ـ وهــو يتضمــن إقامــة دعــوى مــن املدعــي‬\n     ‫العــام ضــد كل مــن‪ .... :‬و‪ ....‬التهامهمــا بخيانــة األمانــة واالســتيالء علــى‬\n     ‫مبلــغ قــدره مليــون وســبعون ألــف ريــال ســعودي تعــود للبنــك ‪ ....‬بعــد‬\n     ‫اســتالمها مــن البنــك لغــرض تغذيــة الصرافــات ومــا جــاء يف احلكــم مــا‬\n     ‫ـاء عليــه فــإن املدعــى عليهمــا يدانــان بالتفريــط لألســباب‬      ‫نصــه‪ ( :‬وبنـ ً‬\n     ‫املذكــورة آنف ـ ًا وتتوجــه عليهمــا التهمــة باالختــاس وقــررت تعزيرهمــا‬\n     ‫لقــاء ذلــك بجلــد كل واحــد منهمــا مائتــي جلــدة موزعــة علــى خمــس‬\n     ‫دفعــات كل دفعــة أربعــن جلــدة بــن كل دفعــة وأخــرى عشــرة أيــام‬\n     ‫وســجن كل واحــد منهمــا ســنة كاملــة مــن تأريــخ دخولــه الســجن‬\n     ‫وبذلــك حكمــت) وهــذا احلكــم قــد اكتســب القطعية بقــرار محكمة‬\n     ‫ـاء‬\n     ‫االســتئناف بالريــاض رقــم ‪/551‬ج‪/5‬أ وتأريــخ ‪1431/3/28‬ه ـ فبنـ ً‬\n     ‫علــى مــا تقــدم مــن الدعــوى وإجابــة املدعــى عليهمــا باســتالم املبلــغ‬\n     ‫املدعــى بــه وإنكارهمــا أخــذ أي شــيء منــه وأنهمــا لــم يفرطــا يف حفظــه‬\n     ‫ومبــا أن املدعــى عليــه ‪ ...‬اتهــم املدعــى عليــه ‪ ....‬باالســتيالء علــى املبلــغ‬\n     ‫املدعــى بــه وإخفائــه وقــد أنكــر املذكــوران ذلــك بعــد إدخــال ‪ ....‬يف‬\n     ‫هــذه الدعــوى ومــا قدمــه املدعــى عليــه ال يرتقــي إلثبــات هــذا الدفــع وقــد‬\n     ‫ـاء علــى‬\n             ‫أدى املدخــل اليمــن الشــرعية الالزمــة علــى نفــي هــذا الدفــع بنـ ً‬\n     ‫طلــب املدعــى عليــه ‪ ....‬ومبــا أن املدعــى عليهمــا يعتبــران أجــراء خاصــن‬\n     ‫واألجيــر اخلــاص ال يضمــن إال يف حــال التعــدي أو التفريــط تنظــر هــذه‬\n     ‫املســألة يف الــروض املربــع لإلمــام البهوتــي مــع حاشــية بــن قاســم رحمهــم‬\n     ‫اهلل ج‪ 5‬صــ‪ 336‬ومــا بعدهــا ومبــا أن املدعــى عليهمــا قــد أدينــا بالتفريــط‬\n     ‫مبوجــب القــرار الشــرعي املشــار إليــه بعاليــه ومبــا أن البنــك ‪ ....‬قــد‬\n\n\n‫‪73‬‬\n\f‫اســتوفى املبلــغ املدعــى بــه مــن الشــركة املدعيــة لــذا كلــه فقــد صرفــت‬\n‫ـدي أن بذمــة كل‬  ‫النظــر عــن الدعــوى ضــد املدخــل لعــدم ثبوتهــا وثبــت لـ ّ‬\n‫مــن‪ .... :‬لشــركة ‪ ....‬ملعــدات األمــن والســامة والتجــارة احملــدودة مبلغـ ًا‬\n‫قــدره مليــون وســبعة وســبعون ألفـ ًا وســتون ريــا ًال وألزمــت املدعــى عليهمــا‬\n‫بدفــع كامــل هــذا املبلــغ للشــركة املدعيــة متضامنــن فيــه وبذلــك‬\n‫كلــه حكمــت وبعــرض احلكــم علــى املدعــى عليهمــا واملدخــل قــرر‬\n‫املدخــل القناعــة بــه أمــا املدعــى عليهمــا فقــررا عــدم القناعــة وطلبــا رفعه‬\n‫حملكمــة االســتئناف بالئحــة اعتراضيــة فجــرى إفهامهمــا بتعليمــات‬\n‫االســتئناف حســبما دون بالضبــط ففهمــا ذلــك وعليــه جــرى التوقيــع‬\n‫حــرر يف ‪1433/4/14‬ه ـ وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                             ‫وسلم‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫باملنطقــة الشــرقية بخطــاب معالــي رئيســها رقــم ‪ 33/1112283‬وتأريــخ‬\n‫‪1433/7/2‬ه ـ وبرفقــه قــرار أصحــاب الفضيلــة قضــاة الدائــرة احلقوقيــة‬\n‫الثانيــة رقــم ‪ 33317225‬وتأريــخ ‪1433/6/28‬ه ـ والــذي جــاء فيــه مــا‬\n‫نصــه‪( :‬وبدراســة الصــك وصــورة ضبطــه وثــاث لوائــح اعتراضيــة‬\n‫وأوراق املعاملــة لوحــظ أن املدعــي بالوكالــة لــم يحــرر دعــواه بإيضــاح‬\n‫مــا علــى كل واحــد مــن املدعــى عليهمــا مــن املبلــغ املدعــى بــه كمــا‬\n‫أن فضيلــة القاضــي لــم يوضــح يف حكمــه مــا علــى كل واحــد مــن‬\n‫املدعــى عليهمــا مــن املبلــغ احملكــوم بــه وال بــد مــن ذلــك فعلــى فضيلــة‬\n‫القاضــي مالحظــة مــا ذكــر وإكمــال مــا يلــزم نحــوه بحضــور الطرفــن‬\n‫) انتهــى بنصــه ‪ ،‬عليــه فقــد مت حتديــد هــذا اليــوم األربعــاء املوافــق‬\n‫‪1433/11/3‬ه ـ الســاعة الثامنــة والنصــف موعــد ًا إلكمــال مــا ورد‬\n\n\n                                                                                       ‫‪74‬‬\n\f     ‫بقــرار أصحــاب الفضيلــة وحضــر يف هــذه اجللســة املدعــي وكالــة ‪/‬‬\n     ‫واملدعــى عليــه أصالــة ‪ /‬واملدعــى عليــه وكالــة ‪ /‬ثــم ســألت املدعــي‬\n     ‫وكالــة عمــا أشــار إليــه أصحــاب الفضيلــة بشــأن حتريــر الدعــوى‬\n     ‫فقــال‪ :‬إن الشــركة موكلتــي تطالــب كل واحــد مــن املدعــى عليهمــا‬\n     ‫بالتضامــن يف حتمــل املبلــغ املدعــى بــه وقــدره مليــون وســبعة وســبعون‬\n     ‫ألفـ ًا وســتون ريــا ًال كمــا ذكــر املدعــي وكالــة الســابق واملقصــد بذلــك‬\n     ‫أن يتحمــل كل واحــد مــن املدعــى عليهمــا نصــف املبلــغ املدعــى بــه‬\n     ‫ومقــدار النصــف خمســمائة وثمانيــة وثالثــون ألفـ ًا وخمســمائة وثالثــون‬\n     ‫ريــا ًال هكــذا أجــاب أمــا جوابــي علــى مــا ذكــره أصحــاب الفضيلــة‬\n     ‫مــن أننــي لــم أوضــح مــا علــى كل واحــد مــن املدعــى عليهمــا مــن املبلــغ‬\n     ‫احملكــوم بــه فأجيــب علــى ذلــك أننــي ذكــرت يف حكمــي مــا نصــه‪:‬‬\n     ‫( وألزمــت املدعــى عليهمــا بدفــع كامــل هــذا املبلــغ للشــركة املدعيــة‬\n     ‫متضامنــن ) أي أن كل واحــد منهمــا يتحمــل نصــف هــذا املبلــغ‬\n     ‫ومقــداره خمســمائة وثمانيــة وثالثــون ألف ـ ًا وخمســمائة وثالثــون ريــا ًال‬\n     ‫وللشــركة املدعيــة مطالبــة أحدهمــا بكامــل املبلــغ احملكــوم بــه ولــه‬\n     ‫الرجــوع علــى صاحبــه بســداد مــا دفعــه للشــركة ومســتندي يف ذلــك مــا‬\n     ‫ذكرتــه يف أســباب احلكــم مــن أن املدعــى عليهمــا أجــراء خاصــن وقــد‬\n     ‫ثبــت تفريطهمــا مبوجــب القــرار الشــرعي املــدون نــص احلاجــة منــه فيمــا‬\n     ‫مضــى ولقــول النبــي صلــى اهلل عليــه وآلــه وســلم‪ ( :‬علــى اليــد مــا أخــذت‬\n     ‫حتــى تؤديــه ) رواه أحمــد واألربعــة وصححــه احلاكــم لــذا فإنــي ال أزال‬\n     ‫علــى حكمــي الســابق كمــا ســيجري تصحيــح األخطــاء اإلمالئيــة‬\n     ‫التــي أشــار إليهــا أصحــاب الفضيلــة بصكــي الســابق وســيجري إحلــاق‬\n     ‫ذلــك بالصــك وســجله ثــم إعــادة املعاملــة حملكمــة االســتئناف باملنطقــة‬\n\n\n‫‪75‬‬\n\f‫الشــرقية لتدقيــق مــا مت إحلاقــه وأســأل اهلل تعالــى أن يجــزي أصحــاب‬\n‫الفضيلــة خيــر ًا علــى مــا بذلــوه مــن جهــد يف تدقيــق هــذه القضيــة وبــاهلل‬\n‫التوفيــق حــرر يف ‪1433/11/3‬ه ـ وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                               ‫وصحبــه وســلم ‪.‬‬\n\n\n‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 3410902‬وتاريــخ‬\n                                               ‫‪1434/1/13‬هــ‪.‬‬\n\n\n\n\n                                                                                      ‫‪76‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":63,"source_page_end":76,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d4ee9508264de3bbe16e42a023a172d78e215a17e99ee33dfe04c0c9fa96cb46","normalized_text_hash":"98dffcfa36f0ef5d8481c2aef6c976cd1da9a6e1cb6ebe3e92452997794c8696","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p63-33192872"},{"id":"645f6f02-6d8f-59b7-8779-e5cdd0bfc39e","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة مبلغ مالي عن طريق تزوير شيك -إقرار املدعى عليه بحيازته أدوات تزوير -العثور على صورة الشيك املدعى به املزور عند املدعى عليه -إثبات بالقرائن -إلزام املدعى عليه بدفع قيمة الشيك املدعى به .","document_number":"33324572","case_number":"3267874","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/2","year":"1434","subject":"رد مسروق -سرقة مبلغ مالي عن طريق تزوير شيك -إقرار املدعى عليه بحيازته أدوات تزوير -العثور على صورة الشيك املدعى به املزور عند املدعى عليه -إثبات بالقرائن -إلزام املدعى عليه بدفع قيمة الشيك املدعى به .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/7/2 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪33324572 :‬‬\n                          ‫َر ْق ُم الدعوى‪3267874:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34240282‬تاريخه‪1434/6/13:‬هـ‬\n\n\n     ‫رد مســروق ‪ -‬ســرقة مبلــغ مالــي عــن طريــق تزويــر شــيك ‪ -‬إقرار املدعى‬\n     ‫عليــه بحيازتــه أدوات تزويــر‪ -‬العثــور علــى صــورة الشــيك املدعــى بــه‬\n     ‫املــزور عنــد املدعــى عليــه‪ -‬إثبــات بالقرائــن ‪ -‬إلــزام املدعــى عليــه بدفــع‬\n                                                       ‫قيمــة الشــيك املدعــى بــه ‪.‬‬\n\n\n\n\n     ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                              ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n     ‫ادعــى وكيــل الشــركة املدعيــة بــأن املدعــى عليــه قــام بتزويــر شــيك‬\n     ‫باســم موكلتــه ثــم قــام بصرفــه مــن حســابها املصــريف لصالــح نفســه‬\n     ‫بــدون وجــه حــق ؛ وطلــب إلزامــه بســداد قيمــة الشــيك املذكــور ملوكلتــه‬\n     ‫‪ -‬أنكــر املدعــى عليــه الدعــوى ســوى مــا جــاء فيهــا مــن إدانتــه للحــق‬\n     ‫العــام بالتزويــر‪ -‬املدعيــة قدمــت قرائــن قويــة متعاضــدة جتــاه املدعــى‬\n     ‫عليــه ترقــى لدرجــة اإلثبــات وهــي إدانتــه بتزويــر الشــيك املذكــور‬\n     ‫للحــق العــام وثبــوت حصــول التزويــر علــى الشــيك ووجــود صــورة الشــيك‬\n     ‫مــع وجــود معمــل كامــل للتزويــر يف منزلــه وشــهادة الشــاهد‪ -‬قضــت‬\n     ‫احملكمــة بإلــزام املدعــى عليــه بتســليم املدعيــة قيمــة الشــيك املــزور‬\n\n‫‪77‬‬\n\f‫الــذي قــام بصرفــه لصالــح نفســه ‪ -‬قنعــت املدعيــة باحلكــم وعــارض‬\n‫عليــه املدعــى عليــه ‪ -‬قــررت محكمــة االســتئناف باألكثريــة املصادقــة‬\n                                                         ‫علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪ 3267874‬وتاريــخ ‪ 1432/03/05‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 32150559‬وتاريــخ ‪ 1432/02/20‬ه ـ ففــي يــوم‬\n‫الســبت املوافــق‪ 1433/01/22‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 41‬‬\n‫وفيهــا حضــر ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم بصفتــه‬\n‫ا عــن ‪ ...‬كنــدي اجلنســية مبوجــب رخصــة إقامــة رقــم بصفتــه‬          ‫وكي ـ ً‬\n‫مديــر شــركة ‪ ....‬ألنظمــة احلاســب اآللــي مبوجــب الســجل التجــاري رقــم‬\n‫مبوجــب الوكالــة الصــادرة مــن كاتــب العــدل املكلــف بالهيئــة العامــة‬\n‫لالســتثمار برقــم ‪ 573‬يف ‪1431/5/12‬ه ـ واملخــول لــه فيها بحق املرافعة‬\n‫واملدافعــة واملخاصمــة والصلــح والتنــازل وادعــى علــى احلاضــر معــه‬\n‫ا يف دعــواه‪ :‬إن‬   ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم قائ ـ ً‬\n‫املدعــى عليــه ســبق وأن زور علــى الشــركة موكلتــي الشــيك رقــم ‪......‬‬\n‫يف ‪2009/3/18‬م مســحوب علــى البنــك ‪ ...‬مببلــغ أربعمائــة وخمســة‬\n‫وثمانــن ألــف ريــال لصالــح ‪......‬إذ قــام بتزويــر توقيــع رئيــس الشــركة‬\n‫موكلتــي ورئيــس احملاســبة وقــام املذكــور بصــرف الشــيك بــدون وجــه‬\n‫حــق كمــا أن الشــيك املذكــور مــزور إذ نفــس الرقــم موجــود لــدى‬\n‫الشــركة لــم يتــم حتريــره حتــى تاريخــه وقــد أديــن املدعــى عليــه بديــوان‬\n\n                                                                                    ‫‪78‬‬\n\f     ‫املظالــم بتزويــر الشــيك املذكــور وحكــم عليــه يف احلــق العــام وإننــي‬\n     ‫أطلــب يف دعــواي هــذه ســؤال املدعــى عليــه وإلزامــه بســداد قيمة الشــيك‬\n     ‫املذكــور هــذه دعــواي وبســؤال املدعــى عليــه قــال‪ :‬مــا ذكــره املدعــي‬\n     ‫وكالــة مــن أننــي أدنــت مــن ديــوان املظالــم بتزويــر الشــيك املذكــور‬\n     ‫صحيــح وأمــا بقيــة مــا جــاء يف دعــوى املدعــي وكالــة فغيــر صحيــح فلــم‬\n     ‫أقــم بتزويــر الشــيك املذكــور وال توقيــع املذكوريــن عليــه وال عالقــة‬\n     ‫لــي بذلــك هــذا مــا لــدي وبعــرض ذلــك علــى املدعــي وكالــة قــال‪:‬‬\n     ‫الصحيــح مــا ذكــرت يف دعــواي وبســؤاله هــل لديــه بينــة قــال‪ :‬نعــم‬\n     ‫ومســتعد بإحضارهــا يف اجللســة القادمــة وبنــاء عليــه فقــد مت رفــع اجللســة‬\n     ‫ويف جلســة أخــرى حضــر وكيــل املدعــي املدونــة هويتــه ووكالته ســابقا‬\n     ‫وحضــر املدعــى عليــه املدونــة هويتــه ســابقا وأحضــر املدعــي وكالــة‬\n     ‫معــه للشــهادة وأدائهــا ‪ ...‬ســوري اجلنســية رخصــة إقامــة رقــم وطلــب‬\n     ‫ســماع مــا لديــه وبســؤاله عمــا لديــه قــال أشــهد هلل بــأن املدعــى عليــه‬\n     ‫كان لــي بــه عالقــة صداقــة ويف يــوم مــن األيــام ال أذكــره كان املدعــى‬\n     ‫عليــه يركــب معــي يف ســيارتي وكان الوقــت مســاء ولــم يكــن معنــا‬\n     ‫أحد وقال لي املدعى عليه أنه يرغب يف تزوير شيك إحدى الشركات‬\n     ‫وكان يقنعنــي أن أقــوم بجلــب صــور للشــيكات وهــو يقــوم بعمليــة‬\n     ‫التزويــر فســألته هــل ســبق أن قمــت بتزويــر شــيكات فقــال نعــم وأنــا‬\n     ‫دائمــا أعمــل ذلــك وضــرب لــي مثــا تزويــر شــيك علــى شــركة ‪ ...‬هــذا‬\n     ‫مــا لــدي مــن شــهادة وأشــهد هلل بهــا وبعــرض الشــاهد ومــا جــاء يف‬\n     ‫شــهادته علــى املدعــى عليــه قــال إن الشــاهد كان مدعــى عليــه معــي يف‬\n     ‫نفــس قضيــة التزويــر لــدى ديــوان املظالــم وكل مــا ذكــره غيــر صحيــح‬\n     ‫وأنــا أقــدح يف عدالــة الشــاهد فهــو يســب اهلل أمامــي كثيــرا وليــس لــدي‬\n\n\n‫‪79‬‬\n\f‫بينــة علــى قدحــي هــذا يف عدالتــه والشــاهد يعــرف وعصابتــه الذيــن‬\n‫قامــوا بتزويــر شــيك شــركة ‪ ....‬هــذا مــا لــدي وبعــرض ذلــك علــى‬\n‫الشــاهد قــال مــا ذكــره املدعــى عليــه غيــر صحيــح فأنــا رجــل مســلم‬\n‫وبســؤال املدعــي وكالــة هــل لديــه مزيــد بينــة قــال نعــم وقــد أرســلت‬\n‫لكــم األدلــة مــن شــعبة مكافحــة التزييــف والتزويــر هــذا وقــد وردنــا‬\n‫خطابهــم رقــم ‪/380/19‬ج ‪ 6‬يف ‪1433/2/9‬ه ـ وفــد أرفــق بــه الشــيك‬\n‫األساســي املســحوب علــى البنــك ‪ ....‬رقــم ‪ ......‬كمــا وجــدت أســاس‬\n‫الشــيك املدعــى بتزويــره رقــم ‪ ....‬املســحوب علــى البنــك ‪ ....‬بتاريــخ‬\n‫‪2009/3/18‬م املصــروف مببلــغ أربعمائــة وخمســة وثمانــن ألــف ريــال‬\n‫كمــا وجــدت بــن طياتهــا التقريــر الفنــي رقــم ‪ 32793‬الصــادر مــن إدارة‬\n‫الفحــوص الفنيــة للتزييــف والتزويــر املتضمــن أوال بفحــص الشــيك‬\n‫موضــوع الفحــص باســتخدام األجهــزة املكبــرة وجدنــا أنــه يحمــل‬\n‫العالمــات األمنيــة واخلصائــص الطباعيــة للشــيكات الصحيحــة‬\n‫وتعــرض للتزويــر باحملــو وإعــادة طباعــه للبيانــات احلاليــة عليــه وهــي‬\n‫الرقــم التسلســلي ورقــم احلســاب ورقــم الترميــز الطباعــي لدفتــر‬\n‫الشــيكات واســم الشــركة ثانيــا ملضاهــاة التواقيــع املنســوبة لــكل‬\n‫مــن املدعــو ‪ ......‬واملدعــو ‪ .....‬يلــزم حتقيــق اآلتــي‪ -1 :‬إرســال منــوذج‬\n‫التوقيــع لــدى البنــك ‪ ...‬لنفــس احلســاب املســحوب عليــه الشــيك موضــوع‬\n‫الفحــص ومنــاذج الشــيكات مماثلــة ســبق صرفهــا حتمــل تواقيــع‬\n‫املذكوريــن‪ -2 .‬تكليــف املذكوريــن مبراجعتنــا يف وقــت يتزامــن مــع‬\n‫إرســال أوراق القضيــة ‪.‬أ‪.‬ه ـ وبعرضهــا علــى املدعــى عليــه قــال إننــي لــم‬\n‫أقــم بالتزويــر هــذا مــا لــدي وبســؤال املدعــي وكالــة هــل لديــه زيــادة‬\n‫بينــة قــال نعــم ومســتعد بإحضارهــا يف اجللســة القادمــة وبنــاء عليــه فقــد‬\n\n\n                                                                                    ‫‪80‬‬\n\f     ‫جــرى رفــع اجللســة ويف جلســة أخــرى حضــر املدعــي وكالــة املدونــة‬\n     ‫هويتــه ووكالتــه ســابق ًا واملدعــى عليــه وقــد وردنــا خطــاب مديــر شــعبة‬\n     ‫إصالحيــة احلائــر برقــم ‪ 0044009/11‬تاريــخ ‪1433/3/13‬ه ـ واملرفــق‬\n     ‫بــه املعاملــة املتعلقــة بالتحقيــق يف دعــوى الشــركة املدعيــة واملدعــى‬\n     ‫عليــه وبتصفــح أوراق املعاملــة وجــد بــن طياتهــا علــى لفــة ‪ 52‬محضــر‬\n     ‫انتقــال وتفتيــش يف تاريــخ ‪1431/1/5‬ه ـ والــذي جــاء فيــه بنــاء العتــراف‬\n     ‫املوقــوف هويــة رقــم عــن وجــود ســبائك الذهــب ومبلــغ مالــي بشــقته وأنــه‬\n     ‫قــام بإخفائهــا بطريقــة فنيــة فقــد مت االنتقــال برفقــه بحضورنــا نحــن‬\n     ‫املوقعــن أدنــاه وبالوصــول إلــى شــقته والدخــول اجتــه إلــى املطبــخ وأفــاد‬\n     ‫بــأن الســبائك أخفاهــا بإحــدى الدواليــب بطريقــة فنيــة ممــا اســتلزم‬\n     ‫فتحهــا مبفــك خــاص وبفتــح بقيــة الدواليــب عثــر علــى مجموعــة أختــام‬\n     ‫إلدارات حكوميــة وأختــام ألشــخاص وصــور بطاقــات وصــور شــيكات‬\n     ‫ودفاتر شيكات وأوراق مطبوعات لشركة‪ ...‬وأوراق خالية ملطبوعات‬\n     ‫وزارة العــدل وبلــغ عــدد املضبوطــات خمســة وســتني وليــس مــن ضمنهــا‬\n     ‫مــا يــدل علــى الشــيك محــل الدعــوى كمــا وجدنــا اعترافــه بتاريــخ‬\n     ‫‪1431/1/7‬ه ـ املصــدق مــن هــذه احملكمــة ووجــد يتضمــن إقــراره‬\n     ‫بحيــازة مــا ضبــط معــه يف محضــر القبــض املذكــور وذكــر فيــه أنــه لــم‬\n     ‫يقــم باســتخدام األوراق الفارغــة وإمنــا الــذي قــام بتزويرهــا زميلــه‪ ...‬كما‬\n     ‫ذكــر يف اعترافــه أنــه يوجــد مــن ضمــن املضبوطات مجموعة شــيكات‬\n     ‫مببالــغ ماليــة محــررة ألشــخاص عددهــا خمســة عشــر شــيكا ومنــاذج‬\n     ‫لتواقيــع شــيكات مــزورة كمــا وجــدت علــى محضــر التحقيــق لفــة ‪101‬‬\n     ‫صحيفــة ‪ 18‬جــواب املدعــى عليــه علــى ســؤال احملقــق للمدعــى عليــه عــن‬\n     ‫الشــيك ‪ ......‬يف ‪2009/3/18‬م املنســوب لشــركة ‪ ...‬ألنظمــة احلاســب‬\n\n\n‫‪81‬‬\n\f‫اآللــي فأجــاب قائــا غيــر صحيــح ســلم لــي هــذا مــن قبــل ‪ ...‬وأمــا الشــيك‬\n‫اآلخــر لشــركة ‪ ...‬فأطعــن فيــه ألنــه ضبــط يف منزلــي وان هــذا الــكالم‬\n‫عــاري مــن الصحــة ألنــه لــم يســبق أن أتعامــل معهم وال أعلم عن نشــاطهم‬\n‫فهــي تلفيــق التهمــة ملــن لــه مصلحــة يف إلصــاق التهمــة بــي وبعــرض جميــع‬\n‫مــا تقــدم علــى املدعــى عليــه قــال إن الشــيك املدعــى بــه ال عالقــة لــي بــه‬\n‫ولــم يضبــط بحوزتــي هــذا مــا لــدي فجــرى ســؤال املدعــي هــل لديــه زيادة‬\n‫بينــة فقــال نعــم ومســتعد بإحضارهــا يف اجللســة القادمــة وبنــاء عليــه فقــد‬\n‫قــررت رفــع اجللســة ويف جلســة أخــرى حضــر املدعــي وكالــة واملدعــى‬\n‫عليــه ‪ ...‬وبســؤال املدعــي هــل لديــه زيــادة بينــة قــال نعــم أننــي راجعــت‬\n‫قســم التزييــف والتزويــر وأفادنــي الضابــط املســئول أنــه يوجــد لديهــم‬\n‫محضــر يثبــت قيــام املدعــى عليــه بتزويــر الشــيك محــل الدعــوى وأطلــب‬\n‫الكتابــة لهــم لبيــان ذلــك هــذا مــا لــدي وبنــاء عليــه فقــد قــررت الكتابــة‬\n‫إلــى قســم التزويــر والتزييــف باألدلــة اجلنائيــة لإلفــادة عمــا ذكــره‬\n‫املدعــي وكالــة وبــه رفعــت اجللســة ويف جلســة أخــرى حضــر املــدون‬\n‫هويتــه ووكالتــه ســابقا وحضــر حلضــوره ‪ ...‬واملــدون هويتــه ســابقا‬\n‫وباالطــاع علــى املعاملــة وجــد بــن طياتهــا علــى لفــة ‪ 66‬محضــر انتقــال‬\n‫وتفتيــش إحلاقــي بتاريــخ ‪1431/1/5‬ه ـ جــاء فيــه بنــاء العتــراف املوقــوف‬\n‫‪ 40‬ســنة بهويــة رقــم عــن وجــود ســبائك الذهــب ومبلــغ مالــي بشــقته وأنــه‬\n‫قــام بإخفائهــا بطريقــة فنيــه فقــد مت االنتقــال رفــق الســجني وبحضورنــا‬\n‫نحــن املوقعــن أدنــاه وبالوصــول إلــى شــقته الواقعــة بحــي ‪ ...‬شــمال ‪...‬‬\n‫بشــارع ‪ ...‬والدخول اجته الســجني ومت إرشــادنا إلى مطبخ الشــقة وأفاد‬\n‫بــأن الســبائك أخفاهــا بإحــدى الدواليــب الســفلية للمطبــخ بطريقــة فنيــه‬\n‫مــن مــا اســتلزم فتحهــا مبفــك خــاص وبفتــح الدواليــب عثــر علــى مــا دون‬\n\n\n                                                                                        ‫‪82‬‬\n\f     ‫مبحضــر االنتقــال والتفتيــش وعددهــا ‪ 56‬ضبطيــه كمــا عثــر علــى‬\n     ‫شــيك مببلــغ أربعمائــة وخمســة وثمانــون ألــف ريــال مجيــر باســم املدعــو‬\n     ‫علــى البنــك ‪ ...‬فــرع ‪ ...‬علمــا أن جميــع مــا ضبــط داخــل الشــقة عثــر عليهــا‬\n     ‫يف األدراج الســفلية ملطبــخ الشــقة وضعــت داخــل أوعيــة بالســتيكية‬\n     ‫مفتوحــة ومت إخفائهــا يف أســفل الديكــور للمطبــخ هــذا وقــد مت‬\n     ‫اســتدعاء املصــور اجلنائــي باألدلــة اجلنائيــة وتصويــر املوقــع وحفظــا‬\n     ‫للواقــع جــرى حتريــر هــذا احملضــر نقيــب توقيــع نقيــب رئيــس رقبــاء‬\n     ‫توقيــع نقيــب توقيــع رئيــس مكافحــة جرائــم األمــوال مقــدم توقيــع‬\n     ‫وبعرضــه علــى املدعــى عليــه قــال إن هــذا احملضــر غيــر صحيــح ولــم‬\n     ‫توجــد الصــورة يف منزلــي هــذا مــا لــدي كمــا وجدنــا يف ملفــات القضيــة‬\n     ‫تفريــغ امللــف املضغــوط للفــاش امليمــوري وقــد تضمــن عــدة منــاذج‬\n     ‫للكتابــة علــى شــيكات وســجالت وإيداعــات وهامــش خطــاب رســمي‬\n     ‫وشــعار شــركة ‪.....‬وختــوم وبعرضــه علــى املدعــى عليــه فقــال ال عالقــة‬\n     ‫لــي بذلــك وإن كانــت موجــودة فهــي ال تخصني وتخــص العامل البنغالي‬\n     ‫صاحــب الشــنطة التــي عثــرت عليهــا يف ســيارتي كمــا وجدنــا علــى‬\n     ‫لفــات املعاملــة الصــك الصــادر مــن هــذه احملكمــة برقــم ‪ ....‬يف‬\n     ‫‪1432/2/14‬ه ـ املتضمــن دعــوى شــركة ‪ ...‬ضــد املدعى عليه يف ســرقة‬\n     ‫مبلــغ انتهــت بالصلــح علــى تســليمه وقــال املدعــى عليــه ســبق وأن ركــب‬\n     ‫معــي شــخص بنغالــي اجلنســية ونســي شــنطته معــي وقمــت بفتحهــا‬\n     ‫ووجــدت بهــا احملــررات املــزورة وقمــت بإحــراق بعضهــا وإخفــاء البقيــة‬\n     ‫داخــل الشــنطة حتــت دالــوب املطبــخ قاصــدا إتالفهــا مســتقبال هــذا مــا‬\n     ‫لــدي وجــرى ســؤال املدعــي وكالــة عــن بينتــه التــي وعــد بإحضارهــا‬\n     ‫فقــال أطلــب إمهالــي وذلــك لوجودهــا لــدى شــعبة التزييــف والتزويــر هــذا‬\n\n\n‫‪83‬‬\n\f‫مــا لــدي وبنــاء عليــه فقــد مت رفــع اجللســة ويف جلســة أخــرى حضر املدعي‬\n‫وكالــة واملدعــى عليــه أصالــة وبســؤال املدعــي وكالــة عــن بينتــه التــي‬\n‫وعــد بإحضارهــا فقــال أن مكافحــة التزويــر وعدونــي بالــرد عليكــم‬\n‫فيمــا يخــص إقــراره بتزويــره الشــيك املدعــى بــه هــذا مــا لــدي هــذا‬\n‫وبالرجــوع إلــى املعاملــة وجــدت بــن طياتهــا احلكــم الصــادر مــن ديــوان‬\n‫املظالــم رقــم ‪/67‬د‪/‬ج‪ 2/‬لعــام ‪1431‬ه ـ واملدعــى فيهــا مــن قبــل هيئــة‬\n‫الرقابــة والتحقيــق ضــد املدعــى عليــه وآخريــن معــه أتهــم فيهــا هــو‬\n‫وشــخص آخــر اســمه بتزويــر محــرر عــريف هــو الشــيك رقــم ‪ ......‬يف‬\n‫‪2009/3/18‬م املنســوب لشــركة ‪ ...‬ألنظمــة احلاســب اآللــي وتقدميهمــا‬\n‫للشــيك مــزور محتجــن بصحتــه مــع علمهمــا بتزويــره ومت قبــض قيمــة‬\n‫الشــيك أجهــزة هواتــف واتهامــه والبقيــة بتزويــر شــيك آخــر وتقليــد‬\n‫أختــام حكوميــة وانتهــى احلكــم لــدى ديــوان املظالــم بإدانــة مبــا نســب‬\n‫إليــه مــن التزويــر واالســتعمال ومعاقبتــه علــى ذلك بســجنه ثالث ســنوات‬\n‫وتغرميــه عشــرة آالف ريــال وبعــرض ذلــك علــى املدعــى عليــه قــال إن هــذا‬\n‫احلكــم صــدر ضــدي واعترضــت عليــه ولــم ينــص يف احلكــم علــى‬\n‫الشــيك املــزور هــذا مــا لــدي هــذا وقــدم املدعــى عليــه جوابــا محــررا علــى‬\n‫صفحتــن تضمــن أقوالــه يف اجللســات الســابقة ونــص فيــه أنــه ال يوجــد‬\n‫اعتــراف منــه بوجــود صــورة الشــيك املزعــوم وبنــاء عليــه فقــد قــررت رفــع‬\n‫اجللســة للتأمــل ويف جلســة أخــرى حضــر املدعــي وكالــة واملدعــى عليــه‬\n‫وقــد جــرى منــا تأمــل مــا جــرى ضبطــه ســابقا ومبــا أن املدعــى عليــه قــد‬\n‫أديــن بتزويــر الشــيك املذكــور مــن قبــل ديــوان املظالــم بالقــرار املذكور‬\n‫كمــا أن الفرقــة القابضــة يف محضرهــا املذكــور قــد أثبتــت وجــود‬\n‫صــورة الشــيك املدعــى بقيمتــه يف منــزل املدعــى عليــه مــع وجــود معمــل‬\n\n\n                                                                                       ‫‪84‬‬\n\f     ‫كامــل للتزويــر كمــا أثبتــت األدلــة اجلنائيــة يف تقريرهــا املــدون ســابقا‬\n     ‫حصــول التزويــر علــى الشــيك يف بياناتــه ورقمــه وتاريخــه وقــد شــهد‬\n     ‫الشــاهد ‪ ...‬بإقــرار املدعــى عليــه أمامــه بتزويــر أحد شــيكات الشــركة‬\n     ‫املدعيــة كل هــذا يعــد قرائــن قويــة تعضــد مــا صــدر ضــد املدعــى عليــه‬\n     ‫مــن حكــم بإدانتــه بتزويــر الشــيك املذكــور مــن قبــل ديــوان املظالــم‬\n     ‫وفعلــه هــذا جنايــة يف حــق الشــركة املدعيــة يوجــب عليــه ضمــان قيمتــه‬\n     ‫لذلــك كلــه فقــد حكمــت علــى املدعــى عليــه بــأن يســلم للشــركة‬\n     ‫املدعيــة املبلــغ املدعــى بــه والــذي قــدره أربعمائــة وخمســة وثمانــون ألــف‬\n     ‫ريــال وبعــرض احلكــم علــى املدعــى عليــه قــرر عــدم القناعــة وطلــب رفــع‬\n     ‫معاملتــه إلــى محكمــة االســتئناف فأجبتــه إلــى طلبــه وأفهمتــه انــه‬\n     ‫ســوف يســلم صــورة مــن نســخة احلكــم يــوم االثنــن ‪1433/7/7‬ه ـ وان‬\n     ‫لــه مهلــة ثالثــن يومــا مــن تاريــخ اســتالم نســخة احلكــم لتقــدمي الئحتــه‬\n     ‫االعتراضيــة فــإذا مضــت املهلــة ولــم يتقــدم بالئحتــه االعتراضيــة ســقط‬\n     ‫حقــه يف االعتــراض وأصبــح احلكــم نافــذا وبــه ختمــت اجللســة ‪11.30‬‬\n     ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                  ‫وسلم ‪ .‬حرر يف ‪ 1433/07/01‬هـ‬\n     ‫احلمــد هلل وحــده وبعــد‪ :‬ففــي يــوم الثالثــاء املوافــق‪ 1434/01/20‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ 11 : 15‬وفيهــا حضــر‪ /‬املدعــي وكالــة‬\n     ‫واملدعــى عليــه ‪ ،‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف باخلطاب‬\n     ‫رقــم‪ )331538468(:‬يف ‪1433/11/20‬ه ـ ـ وبرفقهــا قــرار الدائــرة‬\n     ‫اجلزائيــة الثانيــة برقــم‪ )33444259(:‬يف ‪1433/11/2‬هـ ـ املتضمــن مــا‬\n     ‫نصــه‪« :‬قررنــا باإلجمــاع ‪ :‬أوال‪ /‬اســتند فضيلتــه يف حكمــه على التقرير‬\n     ‫الفنــي رقــم‪ )32793( :‬الصــادر مــن إدارة الفحــوص الفنيــة للتزييــف‬\n\n\n‫‪85‬‬\n\f‫والتزويــر‪ ،‬وهــذا محــل نظــر إذ لــم يكتمــل التقريــر ليعتمــد عليــه كمــا‬\n‫هــو موضــح يف الفقــرة الثانيــة منــه كمــا اســتند فضيلتــه علــى شــهادة‬\n‫وقــد ذكــر املدعــى عليــه أن الشــاهد معــه يف نفــس قضيــة التزويــر لــدى‬\n‫ديــوان املظالــم ولــم يناقــش فضيلتــه الطرفــن يف ذلــك‪ .‬ثانيــا‪ /‬ذكــر‬\n‫وكيــل املدعــى عليــه يف الئحتــه االعتراضيــة أن الشــركة قــد أقامــت‬\n‫دعــوى ضــد البنــك ‪ ...‬بلجنــة تســوية املنازعــات املصرفيــة إللزامــه بــرد‬\n‫مبلــغ الشــيك علــى أســاس خطــأ البنــك يف صــرف شــيك مــزور وذكــر‬\n‫أن موكلــه دفــع بهــذا الدفــع مبذكــرة افتتاحيــة يف أول الدعوى الطالع‬\n‫فضيلتــه ومناقشــة املدعــى عليــه يف ذلــك‪ .‬كمــا ذكــر يف الئحتــه أن‬\n‫الشــركة لــم تقــدم مــا يثبــت أن الشــيك مت صرفــه للمدعــو ‪ ...‬وخصــم‬\n‫مــن حســاب الشــركة‪ ،‬فعلــى فضيلتــه التحقــق مــن ذلــك ومناقشــة‬\n‫الطرفني فيه ال ســيما وقد أرفق أصل الشــيك بخطاب شــعبة مكافحة‬\n‫التزييــف والتزوير»ا‪.‬ه ـ ـ وبعــرض ذلــك علــى املدعــي وكالــة قــال‪ :‬أمــا‬\n‫التقريــر الفنــي فــا أعلــم عنــه‪ ،‬وأمــا الشــاهد فــكان معــه يف قضيــة‬\n‫التزويــر يف ديــوان املظالــم ولكــن ليــس يف موضــوع الشــيك اخلــاص‬\n‫مبوكلتــي وإمنــا يف موضــوع شــيك شــركة ‪ ...‬فقــط‪ ،‬وشــهادته تنصــب‬\n‫علــى أن املدعــى عليــه أبــرز لــه صــورة شــيك عائــد ملوكلتــي ألجــل تزويره‬\n‫وأمــا الدعــوى التــي ســبق وأن أقامتهــا موكلتــي علــى البنــك ‪ ...‬يف جلنــة‬\n‫تســوية املنازعــات املصرفيــة فصحيــح وقــد أوقفــت النظــر فيهــا اللجنــة‬\n‫املذكــورة ألجــل نظــر الدعــوى ضــد املــزور املدعــى عليــه فأقمنــا هــذه‬\n‫الدعــوى بعــد توقــف اللجنــة عــن نظرهــا‪ ،‬وأمــا يتعلــق بصــرف الشــيك‬\n‫لصالــح ‪ ...‬فقــد صــرف الشــيك املــزور لصالــح ‪ ...‬وخصــم مــن حســاب‬\n‫موكلتــي وأســتعد بإحضــار مــا يثبــت ذلــك‪ .‬وقــد أرفقنــا أصــل الشــيك‬\n\n\n                                                                                   ‫‪86‬‬\n\f     ‫املدعــى بتزويــره يف أصــل املعاملــة بعدمــا مت صــرف قيمتــه باالعتمــاد‬\n     ‫علــى الشــيك املــزور مــن قبــل املدعــى عليــه‪ ،‬هــذا مــا لــدي وبعــرض ذلــك‬\n     ‫علــى املدعــى عليــه‪ ،‬قــال‪ :‬أمــا التقريــر الفنــي فــا أعلــم هــل أعتمــد أم ال‪.‬‬\n     ‫وأمــا الشــاهد فهــو متهــم معــي يف الشــيك العائــد للشــركة املدعيــة‬\n     ‫وشــهادته محــل تهمــة وليــس لــي عالقــة بذلــك‪ ،‬والدعــوى املقامــة مــن‬\n     ‫الشــركة املدعيــة ضــد البنــك ال زالــت حتــت النظــر فيمــا أعلــم‪،‬‬\n     ‫والشــركة املدعيــة لــم تقــدم بينــة علــى صــرف الشــيك املذكــور أو أنــه‬\n     ‫خصــم مــن حســاب الشــركة‪ ،‬وأطلــب إمهالــي إلحضــار جــواب مفصــل‬\n     ‫يف ذلــك‪ ،‬هــذا مــا لــدي‪ .‬وبنــاء عليــه فقــد قــررت الكتابــة إلــى جلنــة‬\n     ‫تســوية املنازعــات املصرفيــة لإلفــادة عــن القضيــة املنظــورة لديهــم‬\n     ‫وإحضــار املدعــي وكالــة بينتــه التــي ذكــر‪ .‬وبــه رفعــت اجللســة ‪ ،‬ويف‬\n     ‫جلســة اخــرى حضــر املدعــي وكالــة‪ ،...... /‬كمــا حضــر املدعــى عليــه‬\n     ‫أصالــة‪ /‬املدونــة هويتــه ســابقا‪ ،‬وقــال املدعــى عليــه‪ :‬إن جوابــي علــى مــا‬\n     ‫ذكــره املدعــي وكالــة يف اجللســة قبــل املاضيــة هــو‪ :‬أن الشــركة‬\n     ‫املدعيــة أقامــت دعواهــا ضــد البنــك الرتكابــه خطــأ يف صــرف املبلــغ‬\n     ‫بنــاء علــى شــيك يذكــرون أنــه مــزور‪ ،‬وهــو قــد أفــاد أن أصــل الشــيك‬\n     ‫موجــود عندهــم والقضيــة منظــورة لــدى اللجنــة‪ ،‬ولــم يتــم الفصــل يف‬\n     ‫حينــه حتــى تاريخــه‪ .‬والشــاهد ‪ ...‬متهــم يف نفــس القضيــة بالتزويــر‪،‬‬\n     ‫وهــذا يقــدح يف شــهادته ألنــه صاحــب مصلحــة‪ ،‬هــذا مــا لــدي‪ .‬هــذا وقــد‬\n     ‫أحضــر املدعــي وكالــة معــه‪ :‬مينــي اجلنســية مبوجــب رخصــة اإلقامــة‬\n     ‫رقــم‪ ).....( :‬وطلــب ســماع مــا لديــه‪ ،‬وبســؤاله عمــا لديــه‪ ،‬قــال‪ :‬إننــي مــن‬\n     ‫مواليــد عــام ‪1971‬م وأعمــل مســئول مشــتريات‪ ،‬وأســكن يف مدينــة ‪،...‬‬\n     ‫وأشــهد هلل وبصفتــي مديــر املشــتريات يف مؤسســة ‪ ...‬للتجــارة لصاحبهــا‬\n\n\n‫‪87‬‬\n\f‫اتصــل بــي شــخص ســعودي وطلــب شــراء جــواالت ‪ ..‬باجلملــة‪ ،‬فتــم‬\n‫التفــاوض بيننــا علــى تلبيــة رغبتــه بشــراء كميــة مــن اجلــواالت مــن نــوع‬\n‫‪ ....‬فتــم االتفــاق علــى بيــع الكميــة وطلبنــا منــه إحضــار شــيك باســم‬\n‫املؤسســة وأفهمتــه بأنــه لــن يســلم لــه املبيــع إال بعــد صــرف الشــيك مــن‬\n‫البنــك‪ ،‬فقــال‪ :‬ال يوجــد لــدي حســاب يف البنــك ‪ ...‬وال يف ‪ ...‬وأخبرتــه أن‬\n‫الشــيك ســيحتاج إلــى مقاصــة‪ ،‬وهــذا ســيتأخر‪ ،‬وقلــت لــه اجعــل الشــيك‬\n‫باســمي‪ ،‬حتــى أمتكــن مــن صرفــه؛ لكــون املذكــور مســتعجل يف‬\n‫اســتالم الكميــة فكتــب الشــيك باســمي‪ ،‬وقمــت بصرفــه مــن البنــك‬\n‫‪ ،...‬ثــم أودعتــه يف حســاب املؤسســة‪ ،‬وكان املبلــغ أربعمائــة وخمســة‬\n‫وثمانــن ألــف ريــال‪ ،‬ثــم أبــرز الشــاهد ســند إيــداع نقــد بتاريــخ‬\n‫‪2009/3/18‬م باملبلــغ املذكــور تضمــن إيداع املبلغ يف حســاب املؤسســة‬\n‫املذكــورة‪ ،‬وقــال أنــا لــم أشــاهد املشــتري‪ ،‬هــذا مــا لــدي‪ .‬هــذا وقــد‬\n‫وردنــا خطــاب نائــب محافــظ مؤسســة النقــد رقــم‪ ).......( .:‬يف‬\n‫‪1434/2/24‬هـ ـ املتضمــن‪ « :‬نــود إفــادة فضيلتكــم بــأن املؤسســة قامت‬\n‫مبخاطبــة جلنــة تســوية املنازعــات املصرفيــة بشــأن املوضــوع أعــاه‪،‬‬\n‫والــذي مبوجبــه تلقــت خطــاب ســعادة األمــن العــام للجنــة تســوية‬\n‫املنازعــات املصرفيــة اجلوابــي املتضمــن بــأن شــركة (‪ )...‬اقامــت دعــوى‬\n‫ضــد البنــك ‪ ...‬قيــدت بســجالت اللجنــة برقــم‪ )1431/275( :‬مرفــق‬\n‫صــورة منهــا تطالــب فيهــا مببلــغ مقــداره ‪ 485000‬ريــال قيمــة شــيك‬\n‫تدعــي بأنــه لــم يصــدر مــن الشــركة‪ ،‬ونظــرت الدعــوى بجلســة يــوم‬\n‫االثنــن ‪1432/4/16‬ه ـ ـ وقــد قــررت اللجنــة الكتابــة ملؤسســة النقــد‬\n‫العربــي الســعودي لتزويدهــا مبــا مت حــول هــذا النــزاع‪ ،‬وموافاتهــا بأصل‬\n‫الشــيك محــل الدعــوى أو مخاطبــة شــرطة الريــاض لإلفــادة عمــا إذا مت‬\n\n\n                                                                                    ‫‪88‬‬\n\f     ‫إجــراء املضاهــاة علــى الشــيك موضــوع النــزاع‪ ،‬ومــن ثم تزويدها بنســخة‬\n     ‫مــن التقريــر الفنــي بواقعــة التزويــر‪ .‬والــذي مبوجبــه تلقــت األمانــة العامــة‬\n     ‫للجنــة خطــاب املؤسســة املتضمــن بــأن املؤسســة قامــت بتزويــد إمــارة‬\n     ‫منطقــة الريــاض بأصــل الشــيك رفــق خطابهــا رقــم‪3448( :‬م ظ ‪/‬أ ق)‬\n     ‫وتاريــخ ‪1430/9/5‬هـ ـ بنــاء علــى طلبهــم وأن أصل الشــيك ال يزال بحوزة‬\n     ‫اإلمــارة ‪ ،‬كمــا تضمــن خطــاب ســعادة األمــن العــام للجنــة تســوية‬\n     ‫املنازعــات املصرفيــة املشــار إليــه أعــاه‪ ،‬بــأن هــذه الدعــوى ال تــزال‬\n     ‫موقوفــة إلــى حــن ورود إمــا أصــل الشــيك محــل الدعــوى‪ ،‬أو التقريــر‬\n     ‫الفنــي املعـ ّـد بواقعــة التزوير»ا‪.‬ه ـ ـ ـ وبســؤال املدعــي وكالــة عــن مــا يثبــت‬\n     ‫صــرف الشــيك‪ ،‬فقــال‪ :‬أطلــب إمهالــي إلحضــاره‪ ،‬وبــه رفعــت اجللســة‪،‬‬\n     ‫ويف جلســة اخــرى حضــر املدعــى عليــه اصالــه املدونــة هويتــه ســابقا ولــم‬\n     ‫يحضــر مــن ميثــل الشــركة املدعيــة وقــال املدعــى عليــه اننــي اطلــب عــدم‬\n     ‫شــطب القضيــة واالســتمرار يف نظرهــا وقــدم ورقــه جــاء فيهــا أود ان‬\n     ‫ابــن لفضيلتكــم التالــي ‪ :‬اوال‪ :‬بخصــوص امللحوظــة األولــى مــن‬\n     ‫محكمــة االســتئناف بشــان الدعــوى املرفوعــة مــن الشــركة املدعيــة‬\n     ‫ضــد البنــك ‪ ...‬امــام جلنــه تســوية املنازعــات املصرفيــة فقــد ثبــت‬\n     ‫لفضيلتكــم مبخاطبــة اللجنــة املذكــورة ان الدعــوى ال تــزال متداولــة‬\n     ‫لديهــا وهــو مــا يوكــد صحــة مــا دفعــت بــه مــن ان املدعيــة قــد ســلكت‬\n     ‫طريقــن للمطالبــة بــذات املوضــوع ‪،‬ثانيــا‪ :‬بخصــوص امللحوظــة الثانيــة‬\n     ‫مــن محكمــة االســتئناف وهــي بشــان اعتمــاد شــهادة الشــاهد ‪......./‬‬\n     ‫كقرينــة علــى احلكــم علــى ‪ ،‬فأننــي مصمــم علــى القــدح يف شــهادة‬\n     ‫هــذا الشــاهد وذلــك ألنــه كان متهمــا معــي يف قضيــة التزويــر وهــو‬\n     ‫صاحــب مصلحــة يف الدعــوى كونــه مــن املمكــن ان يتخــوف مــن‬\n\n\n‫‪89‬‬\n\f‫اختصــام املدعيــة لــه ‪ ،‬ثالثــا‪ /‬وبعــد تــداول القضيــة للمــرة الثانيــة‬\n‫باجللســات لــم تقــدم املدعيــة البينــة الصحيحــة علــى ثبــوت جنايتــي يف‬\n‫حقهــا ‪ ،‬بنــاء عليــه فأننــي اطلــب فضيلتكــم احلكــم بصــرف النظــر عــن‬\n‫الدعــوى ‪ ،‬حيــث اننــي قضيــت مــدة العقوبــة املقضــي بهــا علــي منــذ‬\n‫تاريــخ ‪1430/12/29‬ه ـ وال يعطــل اإلفــراج عنــي ســوى هــذه القضيــة‬\n‫التــي ال ذنــب لــي فيهــا أه ـ ‪ ،‬وبنــاء عليــه فقــد قــررت رفــع اجللســة ‪ ،‬ويف‬\n‫جلســة أخــرى حضــر املدعــي وكالــة‪ ، /‬كمــا حضــر املدعــى عليــه‬\n‫أصالة‪ ، /‬وأبرز املدعي وكالة كشــف حســاب صادر من ‪ ...‬للحســاب‬\n‫رقــم‪ )......(:‬اخلــاص بــ‪...‬املترجــم مــن مكتــب ‪ ...‬للترجمــة املتضمــن أنــه‬\n‫بتاريــخ ‪2009/3/18‬م مت ســحب شــيك رقــم‪ )......(:‬مببلــغ أربعمائــة‬\n‫وخمســة وثمانــن ألــف ريــال هــذا وقــد جــرى منــي االطــاع علــى التقريــر‬\n‫الفنــي املرفــق باملعاملــة والصــادر مــن إدارة الفحــوص الفنيــة للتزييــف‬\n‫والتزويــر والــذي تضمــن يف نتيجتــه أوال بفحــص الشــيك موضــوع‬\n‫الفحــص باســتخدام األجهــزة املكبــرة وجدنــا أنــه يحمــل العالمــات‬\n‫األمنيــة واخلصائــص الطباعيــة للشــيكات الصحيحــة وتعــرض للتزويــر‬\n‫باحملــو وإعــادة طباعــة للبيانــات احلاليــة عليــه وهــي الرقــم التسلســلي‬\n‫ورقــم احلســاب ورقــم الترميــز الطباعــي لدفتــر الشــيكات واســم‬\n‫الشــركة(…‪ ).‬ثانيــا ملضاهــاة التواقيــع املنســوبة لــكل مــن املدعــو‬\n‫واملدعــو يلــزم حتقيــق اآلتــي‪ /1 :‬إرســال منــوذج التوقيــع لــدى البنــك ‪...‬‬\n‫لنفس احلســاب املســحوب عليه الشــيك موضع الفحص ومناذج شــيكات‬\n‫مماثلــة ســبق صرفهــا حتمــل التواقيــع املذكوريــن ‪/2‬تكليــف‬\n‫للمذكوريــن مبراجعتنــا يف وقــت يتزامــن مــع إرســال أوراق القضيــة‬\n‫الفاحــص رقيــب‪ ./‬اخلبيــر رائــد‪ . /‬مديــر شــعبة اخلطــوط والتواقيــع مقدم‪.‬‬\n\n\n                                                                                      ‫‪90‬‬\n\f     ‫مديــر إدارة الفحــوص الفنيــة للتزييــف والتزويــر عقيــد ‪ ،‬وبنــاء عليــه‬\n     ‫فقــد جــرى رفــع اجللســة ‪ ،‬ويف جلســة أخــرى حضــر املدعــي وكالــة‪/‬‬\n     ‫كمــا حضــر املدعــى عليــه‪ ، /‬وبنــاء علــى مــا ســبق فإننــي أجيــب علــى‬\n     ‫مــا الحظــه أصحــاب الفضيلــة بأننــي اعتمــدت يف مــا حكمــت بــه علــى‬\n     ‫احلكــم الســابق مــن ديــوان املظالــم املثبــت إلدانــة املدعــى عليــه بتزويــر‬\n     ‫الشــيك املذكــور‪ ،‬وقــد اعتضــد ذلــك لــدي بقرائــن هــي أن املدعــى‬\n     ‫عليــه قــد أقــر يف إقــراره املصــدق شــرعا بحيازتــه ألدوات التزويــر‬\n     ‫واملطبوعــات واألختــام املــزورة‪ ،‬وقيامــه بإخفائهــا يف منزلــه‪ ،‬وكــذا مــا‬\n     ‫جــاء يف محضــر االنتقــال والتفتيــش أنهــم عثــروا بداللــة املدعــى عليــه يف‬\n     ‫مــكان مخفــي يف منزلــه علــى أدوات التزويــر واملطبوعــات واألختــام‬\n     ‫املــزورة كمــا عثــروا علــى صــورة الشــيك املدعــى بــه املــزور‪ ،‬وكــذا‬\n     ‫محضــر تفريــغ الفــاش امليمــوري والــذي احتــوى علــى منــاذج التزويــر‬\n     ‫وهــذا يــدل علــى امتهانــه للتزويــر ومترســه فيــه ال ســيما مــع وجــود صورتــه‬\n     ‫لديــه وقــد قــدم املدعــي وكالــة مــا يثبــت صــرف الشــيك املذكــور وأقــر‬\n     ‫بذلــك احلاضــر أمــا مــا ذكــره أصحــاب الفضيلــة مــن أن أصــل الشــيك‬\n     ‫موجــود فصحيــح‪ ،‬إذ الدعــوى بتزويــره ولــو صــرف أصــل الشــيك ملــا‬\n     ‫اعتبــر هــذا تزويــرا وأمــا مــا يتعلــق بالدعــوى املقامــة لــدى جلنــة تســوية‬\n     ‫املنازعــات املصرفيــة‪ ،‬فالــذي يظهــر لــي أنهــا ال تؤثر على هــذه الدعوى‪،‬‬\n     ‫وهــي دعــوى مســتقلة و الدعــوى يف املطالبــة بقيمــة الشــيك إمنــا تتوجــه‬\n     ‫علــى املتســبب بصــرف قيمتــه وبهــذا لــم يظهــر لــي مــا يؤثــر علــى مــا‬\n     ‫حكمــت بــه‪ ،‬وقــررت بعــث املعاملــة إلــى محكمــة االســتئناف‪ ،‬وبــه‬\n     ‫ختمــت اجللســة الســاعة ‪ 10 : 00‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                    ‫محمد وعلى آله وصحبه وسلم ‪ .‬حرر يف ‪ 1434/05/07‬هـ‬\n\n\n‫‪91‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق‪ 1434/07/02‬ه ـ‬\n‫افتتحت اجللســة الســاعة ‪ 09 : 45‬وقد عادت املعاملة إلينا من محكمة‬\n‫االســتئناف برقــم ‪ 341213075‬وتاريــخ ‪1434/6/21‬ه ـ وبرفقهــا القرار‬\n‫الصــادر مــن الدائــرة الثانيــة لتمييــز القضايــا اجلزائيــة رقــم ‪34240282‬‬\n‫وتاريــخ ‪1434/6/13‬ه ـ املتضمــن‪ :‬وباالطــاع علــى مــا أجاب بــه فضيلته‬\n‫وأحلقــه بالصــك وصــورة ضبطــه بنــاء علــى قرارنــا رقــم ‪33444259‬‬\n‫وتاريــخ ‪1433/11/2‬ه ـ تقــرر لألكثريــة املصادقــة علــى احلكــم بعــد‬\n‫اإلجــراء األخيــر ‪ ،‬وجــرى التهميــش عليــه مبوجبــه وبــه ختمــت اجللســة‬\n‫الســاعة ‪ 09 : 50‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                             ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/2‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                 ‫‪92‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":77,"source_page_end":92,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5b6b05b8936bc08552e1413fa71ae0d976473f6e3a9892b4f2989b08a6cedcc7","normalized_text_hash":"3a30d2e746e3c97fb9a5b161dc1fdf14402fbdd60a8be3e5bad3866b36f33f1e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p77-33324572"},{"id":"7d8bf8a4-db28-53f9-a5c5-49277034c4ae","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة مبالغ مالية عن طريق النصب واالحتيال - اإلقرار حجه على املقر -ورود املبالغ يف حساب املدعى عليه -تصرف اإلنسان محمول على الصحة و النفاذ -احلكم بإلزام املدعى عليها تسليم املبلغ املدعى به.","document_number":"34265447","case_number":"3451857","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/11","year":"1434","subject":"رد مسروق -سرقة مبالغ مالية عن طريق النصب واالحتيال - اإلقرار حجه على املقر -ورود املبالغ يف حساب املدعى عليه -تصرف اإلنسان محمول على الصحة و النفاذ -احلكم بإلزام املدعى عليها تسليم املبلغ املدعى به.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/7/11 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34265447 :‬‬\n                          ‫َر ْق ُم الدعوى‪3451857:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34358464‬تاريخه‪1434/11/12:‬هـ‬\n\n\n     ‫رد مســروق‪ -‬ســرقة مبالــغ ماليــة عــن طريــق النصــب واالحتيــال ‪-‬‬\n     ‫اإلقــرار حجــه علــى املقــر ‪ -‬ورود املبالــغ يف حســاب املدعى عليه ‪ -‬تصرف‬\n     ‫اإلنســان محمــول علــى الصحــة و النفــاذ ‪ -‬احلكــم بإلــزام املدعــى عليهــا‬\n                                                         ‫تســليم املبلــغ املدعــى بــه‪.‬‬\n\n\n\n\n                               ‫‪ -1‬اإلقرار حجة على املقر واملرء مؤاخذ بإقراره‪.‬‬\n                         ‫‪ -2‬األصل يف التصرفات حملها على الصحة والنفاذ ‪.‬‬\n\n\n\n\n     ‫ادعــى وكيــل املدعيــة بــأن املدعــى عليهــا عاونــت ابنهــا علــى مــا قــام‬\n     ‫بــه مــن نصــب واحتيــال جتــاه موكلتــه؛ وذلــك بــأن مكنــت ابنهــا مــن‬\n     ‫اســتقبال مبالــغ ماليــة حولتهــا املدعيــة بنــاء علــى طلبــه إلــى احلســاب‬\n     ‫املصــريف اخلــاص بوالدتــه املدعــى عليهــا بعــد أن أوهــم املدعيــة برغبتــه‬\n     ‫يف الــزواج منهــا ثــم غــادر اململكــة نهائي ـ ًا إلــى بــاده دون أن يفــي‬\n     ‫بوعــده‪ ،‬ولــذا فقــد طلــب إلزامهــا بإعــادة املبالــغ التــي حولتهــا موكلتــه‬\n     ‫علــى حســابها‪ -‬أقــر وكيــل املدعــى عليهــا بدخــول املبالــغ املدعــى بهــا‬\n     ‫إلــى حســاب موكلتــه ودفــع بــأن احلســاب كان حتــت يــد ابنهــا وأنــه‬\n     ‫املســتخدم الوحيــد لــه آنــذاك وهــو املســتفيد مــن تلــك املبالــغ وال عالقــة‬\n\n‫‪93‬‬\n\f‫للمدعــى عليهــا بذلــك‪ ،‬وأضــاف بــأن املدعــى عليهــا كبيــرة يف الســن‬\n‫وال جتيــد القــراءة والكتابــة‪ -‬وكيــل املدعــى عليهــا أقــر بدخــول‬\n‫املبالــغ املذكــورة يف الدعــوى إلــى حســاب موكلتــه ومــا دفــع بــه ال‬\n‫يخلــي مســؤوليتها مــن إعــادة مــا دخــل بحســابها إلــى املدعيــة‪ -‬قضــت‬\n‫احملكمــة حضوريـ ًا بإلــزام املدعــى عليهــا بتســليم املدعيــة أصالــة املبلــغ‬\n‫املدعــى بــه‪ -‬قنــع وكيــل املدعيــة باحلكــم وعارضــت عليــه املدعــى‬\n             ‫عليهــا‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد‪ :‬فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 3451857‬وتاريــخ‬\n‫‪1434/02/02‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34165043‬وتاريــخ‬\n‫‪1434/01/19‬ه ـ حضــر املدعــي وكالــة ســعودي بالســجل رقــم بصفتــه‬\n‫وكيــا عــن الفركــز بالوكالــة الصــادرة مــن كتابــة عــدل الريــاض‬\n‫الثانيــة برقــم ‪ 61031‬يف ‪1432/8/15‬ه ـ جلــد ‪ 19759‬وحضــر حلضــوره‬\n‫املدعــى عليــه وكالــة ســعودي بالســجل رقــم بصفتــه وكيــا عــن ‪...‬‬\n‫بالوكالــة الصــادرة مــن كتابــة عــدل شــمال جــدة الثانيــة برقــم‬\n‫‪ 33451058‬يف ‪1433/12/19‬ه ـ وألن الدعــوى غيــر محــررة لذا أفهمت‬\n‫املدعــي وكالــة بتحريــر دعــواه ففهــم ذلــك وعليــه جــرى تأجيــل اجللســة‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n‫‪ .‬حــرر يف ‪1434/03/14‬ه ـ ثــم يف جلســة أخــرى حضــر املدعــي وكالــة‬\n‫املدونــة هويتــه ووكالتــه ســابقا وحضــر حلضــوره املدعــى عليــه وكالــة‬\n\n                                                                                    ‫‪94‬‬\n\f     ‫ســعودي بالســجل رقــم بصفتــه وكيــا عــن بالوكالــة الصــادرة مــن‬\n     ‫كتابة العدل الثانية بشــمال جدة برقم ‪ 34479385‬يف ‪1434/4/17‬هـ‬\n     ‫بصفتــه وكيــل ‪ ...‬بالوكالــة رقــم ‪ 33451058‬وتاريــخ ‪1433/12/19‬ه ـ‬\n     ‫الصــادرة مــن كتابــة العــدل الثانيــة بشــمال جــدة وبســؤال املدعــي‬\n     ‫وكالــة عــن حتريــر دعــواه أفــاد قائــا ‪ :‬بعــد قيــام ابــن املدعــى عليهــا‪/‬‬\n     ‫‪.......‬ســعودي اجلنســية وبعــد تعرفــه علــى موكلتــي مــن موقــع ‪...‬‬\n     ‫اإللكترونــي قــام بالنصــب واالحتيــال علــى موكلتــي واســتغاللها‬\n     ‫واســتدراجها بنيــة الــزواج منهــا كمــا ادعــى وقــد تأملــت فيــه حســن‬\n     ‫النيــة وطلبــت منــه موكلتــي التعــرف علــى أهلــه وقــال لهــا إن والــدي قــد‬\n     ‫تــويف منــذ فتــرة قريبــه وأنــا اآلن أعولهــم جميعــا ونحــن مــن أســرة ثريــة‬\n     ‫وقــد توقفــت ثــروات والــدي وأنــا اآلن يف ضائقــة ماليــه كبيــره وســوف‬\n     ‫أعرفــك علــى أمــي وعلــى أختــي ولكــن أنــا محتــاج ملبلــغ مــن املــال اقضي‬\n     ‫احتيــاج أهلــي واطلــب منــك املســاعدة ومبجــرد انتهــاء أمــي مــن العــدة‬\n     ‫ســوف نقــوم بزيارتكــم وطلــب يــدك مــن اهلــك وقامــت موكلتــي بتلبيــة‬\n     ‫متطلباتــه وبعــد عــدة شــهور مــن االتصــاالت لــم يعــد يــرد علــى اتصــاالت‬\n     ‫موكلتــي واكتشــفت بعــد أن توصلــت ألرقــام أمــه ‪ ...‬عــن طريــق‬\n     ‫حســاباتها البنكيــة التــي أودعــت عليهــا املبالــغ اكتشــفت أنهــا وقعــت‬\n     ‫يف فــخ النصــب واالحتيــال مــن هــذا الرجــل الــذي تالعــب مبشــاعرها‬\n     ‫ومالهــا وســحب منهــا مبالــغ ماليــه تقــدر بـ ـ ‪160‬الــف ريــال مت إيداعها من‬\n     ‫حســاب موكلتــي حســابها اجلــاري ببنــك ‪ .....‬رقــم (‪ )....‬علــى حســابني‬\n     ‫مختلفــن للمدعــى عليهــا وهــي حســاب رقــم‪ .....‬ببنــك (‪ )....‬حيــث وصــل‬\n     ‫املبلــغ احملــول علــى هــذا احلســاب (‪ 93000‬ثالثــة وتســعون ألفــا ) يف‬\n     ‫(‪14‬اربعــة عشــر عمليــة مصرفيــه مــن تاريــخ ‪ 2010/10/05‬إلــى تاريــخ‬\n\n\n‫‪95‬‬\n\f‫آخــر عمليــه ‪ )2011/02/22‬وإيــداع مــن حســاب موكلتــي مبصــرف ‪...‬‬\n‫رقــم‪ .......‬علــى حســاب املدعــى عليهــا بنفــس البنــك حســاب مبصــرف‬\n‫‪ ......‬رقــم (‪ ).....‬مببلــغ (‪ 36000‬ســتة وثالثــون ألــف ريــال ) يف (‪ 7‬ســبع‬\n‫عمليــات مصرفيــه مــن تاريــخ ‪ 2011/10/29‬إلــى تاريــخ ‪2011/03/30‬‬\n‫ميــادي أي مــن تاريــخ ‪ 1431/10/20‬إلــى ‪ 1431/4/25‬هجريــة)‪ .‬ومت‬\n‫إيــداع املبالــغ بتواريــخ ميالديــة وكان إيــداع املبالــغ مــن شــهر ذو القعــدة‬\n‫مــن عــام ‪1431‬ه ـ وكل إيــداع موضــح تاريخ إيداعه مبوجب كشــوفات‬\n‫احلســابني وهــي مفصلــه كاملــة بكشــوفات مرفقــه صورهــا بهــذه‬\n‫الدعــوى وحيــث مــا قــام بــه مبعاونــه واضحــة مــن صاحبــة احلســابات‬\n‫املغربيــة اجلنســية مبوجــب اإلقامــة والســجل رقــم (‪ ).....‬تكــون طــرف‬\n‫أول وخصمهــا إمــام القضــاء حيــث مت االتصــال عليهــا مــن قبــل موكلتي‬\n‫ولــم حتذرهــا أو تنصحهــا بالبعــد عــن ابنهــا خصوصــا وأنهــا تعلــم إن‬\n‫ابنهــا يتالعــب بأعــراض النــاس وســحبهم واســتنزافهم ماديــا فضيلــة‬\n‫القاضــي يعلــم فضيلتكــم إن مــن شــارك يف جــرم ســواء باملســاعدة او‬\n‫بتســهيل أي وســيله للنصــب علــى النــاس فهــو شــريك ذلــك املجــرم بجرمه‬\n‫لــذا أطلــب إلــزام املدعــى عليهــا بدفــع مبلــغ وقــدره مائــة وثالثــون ألــف‬\n‫ريــال هــذه دعــواي وبعرضهــا علــى املدعــى عليــه وكالــة قــال أطلــب‬\n‫املهلــة للــرد يف اجللســة القادمــة هكــذا قــال وعليــه جــرى تأجيــل اجللســة‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n‫‪ .‬حــرر يف ‪1434/04/20‬ه ـ ثــم يف جلســة أخــرى حضــر املدعــي وكالــة‬\n‫املدونــة هويتــه ووكالتــه ســابقا وحضــر حلضــوره املدعــى عليــه وكالــة‬\n‫املدونــة هويتــه ووكالتــه ســابقا واملخولــة له حق اإلقرار وبســؤال املدعى‬\n‫عليــه وكالــة عمــا اســتمهل مــن أجلــه قــدم مذكــرة جوابيــة هــذا نصهــا‬\n\n\n                                                                                      ‫‪96‬‬\n\f     ‫‪ :‬بــأن مــا ذكرتــه املدعيــة يف دعواهــا غيــر صحيــح فاملدعــى عليهــا ليــس‬\n     ‫لديهــا أبــن يدعــى ‪ ...‬وهــذا االســم هــو أبــن زوجهــا مــن زوجــة أخــرى وإمنــا‬\n     ‫قــد تكــون املدعيــة تقصــد الســيد ‪ .......... /‬وهــو أبــن املدعــى عليهــا مــن‬\n     ‫زوج ســابق ‪ ،‬فــإن كانــت تقصــد هــذا فهــو مــن كان يســتخدم حســاب‬\n     ‫والدتــه البنكــي ونذكــر هنــا بــأن هــذا الشــخص قــد ارتبــط بعالقــة مــع‬\n     ‫املدعيــة كمــا ذكــرت يف دعواهــا وال نعــرف كيــف كانــت وال علــى‬\n     ‫أي أســاس بنيــت وإلــى أي حــد وصلــت بينهمــا فلــم نعلــم عــن هــذه العالقة‬\n     ‫إال بعــد ســفره ومغادرتــه اململكــة ‪.‬كمــا أن املذكــور ليــس ســعودي‬\n     ‫اجلنســية وإمنــا هــو مغربــي اجلنســية كان هنــا بوظيفــة عامــل وقــد حــدث‬\n     ‫بينــه وبــن كفيلــه خــاف أســتمر لفتــرة وكانــت والدتــه ( املدعــى‬\n     ‫عليهــا ) خــارج اململكــة وعــادت بتاريــخ ‪1431/10/23‬ه ـ أي قبــل بدايــة‬\n     ‫التحويــات حلســابها بثالثــة أيــام فقــط كمــا يتضــح مــن خــال تواريــخ‬\n     ‫التحويــات ( مرفــق ‪ ) 1‬وحــال وصولهــا جلــأ إليهــا ابنهــا وأخبرهــا أنــه قــد‬\n     ‫ا جديــد ًا وأنــه يقــوم اآلن بتنفيــذ أعمــال اجلبــس والديكــور‬     ‫وجــد عم ـ ً‬\n     ‫وهــو بحاجــة ماســة الســتخدام حســابها البنكــي إلمتــام هــذه األعمــال‬\n     ‫مــع عمالئــه وأخبرهــا بــأن التعامــات والتحويــات مببالــغ كبيــرة وال‬\n     ‫يســتطيع أن يســحب ســوى خمســة أالف ريــال يف اليــوم بحســب نظــام‬\n     ‫بطاقــات الصــراف وهــي ال تكفــي ويحتــاج ألكثــر مــن حســاب حلــن‬\n     ‫انتهــاء خالفــه مــع كفيلــه حتــى يتســنى لــه بعــد ذلــك فتح حســاب باســمه‬\n     ‫‪.‬وهنــا غلبــت عاطفــة األم وفرحتهــا بعمــل ابنهــا وانتهــاء مشــاكله‬\n     ‫وحتســن وضعــه فاســتجابت لطلبــه وقدمــت لــه بطاقــات الصــراف‬\n     ‫اخلاصــة بهــا مــع العلــم بــأن املدعــى عليهــا كبيــرة يف العمــر وغيــر متعلمــة‬\n     ‫وجتهــل مغبــة مــا أقدمــت عليــه وعاطفتهــا كأم غلبــت عليهــا يف حينهــا‬\n\n\n‫‪97‬‬\n\f‫ولــم تفكــر يف أي أمــر أخــر ‪.‬وبعــد فتــرة مــن الزمــن مت القبــض علــى‬\n‫الســيد ‪......... /‬ألن كفيلــه كان قــد أبلــغ الســلطات املختصــة بتغيــب‬\n‫مكفولــه وســافر إلــى بــاده مملكــة املغــرب ‪.‬وبعــد ســفره بعشــرة أيــام‬\n‫اتصلــت املدعيــة مبوكلتــي وســألتها عــن ابنهــا وأنــه لــم يعــد يــرد علــى‬\n‫اتصاالتهــا فأخبرتهــا موكلتــي بأنــه ســافر وســألتها مــن أنــت ومــا‬\n‫عالقتــك بابنــي فقالــت لهــا أنــا ‪...‬وكنــت علــى عالقــة بابنــك وأنهمــا‬\n‫كانــا ســيتزوجان فتعجبــت موكلتــي ممــا ســمعت منهــا وأخبرتهــا بأنــه‬\n‫متــزوج ولديــه أبنــاء فقالــت املدعيــة نعــم إنهــا تعــرف ذلــك وليــس كمــا‬\n‫ذكــرت املدعيــة يف دعواهــا بأنهــا اتصلــت باملدعــى عليهــا ولــم حتذرهــا‬\n‫واســتمرت تتصــل مبوكلتــي وتبعــث لهــا بالرســائل العامــة العاديــة عبــر‬\n‫اجلــوال ولــم تتحــدث معهــا وال تبلغهــا عــن هــذه املبالــغ ولــم تذكرهــا أو‬\n‫حتــى تعــرض بذكرهــا مطلقــا ‪.‬ولكــن كانــت تتصــل يف أوقــات‬\n‫متأخــرة بالليــل وتبعــث بالرســائل أيض ـ ًا يف أوقــات متأخــرة جــد ًا‬\n‫وموكلتــي امــرأة كبيــرة يف الســن ال تســهر كثيــر ًا وال جتيــد القــراءة‬\n‫والكتابــة فأخبرتهــا بذلــك بــكل لطــف وقالــت لهــا ممكــن ان‬\n‫تتواصلــي مــع بناتــي فهــم يف مثــل عمــرك تقريب ـ ًا وانتهــت اتصاالتهــا‬\n‫مبوكلتــي مــن تلــك اللحظــة ولــم تعــرف عنهــا شــيء مــن حينهــا إال أن‬\n‫موكلتــي أصبحــت تتعــرض ملضايقــات عبــر اجلــوال وإزعاجــات وال‬\n‫تعــرف مصدرهــا فغيــرت رقــم جوالهــا تفادي ـ ًا ملــا يحــدث معهــا مــن‬\n‫إزعاجــات ‪.‬وهنــا نتســاءل ملــاذا تقــوم املدعيــة بتحويــل كل هــذه األمــوال‬\n‫لشــخص ال تعــرف حتــى اســمه وتدعــي اآلن إنهمــا كانــا متفقــان علــى‬\n‫الــزواج وملــاذا لــم حتــاول االتصــال بأمــه خــال تواجــده هنــا وعالقتهــا‬\n‫معــه كمــا ادعــت خصوصــا أنهــا ذكــرت يف دعواهــا أنــه قــد وعدهــا‬\n\n\n                                                                                    ‫‪98‬‬\n\f     ‫بــأن يقومــون بزيارتهــم هــو وأمــه بعــد انتهــاء عــدة أمــه كمــا جــاء يف‬\n     ‫صحيفــة الدعــوى بينمــا التحويــات اســتمرت قرابــة الســتة أشــهر فــأي‬\n     ‫عــدة هــذه التــي تســتمر لســتة أشــهر ومبراجعــة بســيطة لتواريــخ تلــك‬\n     ‫التحويــات التــي قامــت بهــا املدعيــة ( مرفــق ‪ ) 1‬جنــد أن التحويــات‬\n     ‫كانــت متتاليــة ومتواليــة إلــى درجــة أن بعضهــا كانــت يف نفــس اليــوم‬\n     ‫وهــذا يرجــح كالم الســيد ‪ /‬بــأن اســتخدامه للحســابات للعمــل وليــس‬\n     ‫كمــا ادعــت املدعيــة بأنهــا عالقــة بقصــد الــزواج ولكــن هــل جــرى‬\n     ‫العــرف بــأن تدفــع العــروس لعريســها املــال قبــل زواجهمــا ‪.‬ممــا هو واضح‬    ‫ُ‬\n     ‫يــا فضيلــة القاضــي بــأن املدعيــة ال تخــرج عــن أحــد أمريــن إمــا أن‬\n     ‫عالقتهــا كانــت مــع الســيد ‪ /‬عالقــة جتاريــة وهــو األرجــح أو أنهــا‬\n     ‫صادقــة فيمــا ادعــت بــه مــن أنهــا عالقــة بقصــد الــزواج ‪ ،‬واألمــر يف‬\n     ‫كال احلالتــن ال يعنــي موكلتــي فليــس هنــاك صفــة تعاقديــة بينهــا وبــن‬\n     ‫املدعيــة واملدعيــة مفرطــة واملفــرط أولــى باخلســارة ‪.‬لــكل مــا تقــدم يــا‬\n     ‫فضيلــة الشــيخ فأننــي اطلــب رد الدعــوى وصــرف النظــر عنهــا وأن صــح‬\n     ‫مــا ادعــت بــه املدعيــة يف دعواهــا فعليهــا إقامــة الدعــوى علــى الســيد ‪/‬‬\n     ‫وليــس علــى والدتــه ‪ ،‬وقــد ذكــرت هــي ذلــك يف دعواهــا صراحة فقالت‬\n     ‫( أنهــا وقعــت يف فــخ النصــب واالحتيــال مــن هــذا الرجــل الــذي تالعــب‬\n     ‫مبشــاعرها ) ‪ ...‬وهــذا إقــرار منهــا مبــن نصــب عليهــا فعليهــا مقاضاتــه‬\n     ‫هــو بعينــه ‪.‬وختامـ ًا يــا فضيلــة الشــيخ فــأن موكلتــي بالرغــم مــن كل مــا‬\n     ‫ذكرنــا مســتعدة للمثــول أمــام فضيلتكــم وأداء اليمــن الشــرعي علــى‬\n     ‫أنــه ليــس لهــا أي عالقــة باملدعيــة ولــم تعلــم عنهــا وعــن عالقتهــا بابنها إال‬\n     ‫بعــد ســفره مــن خــال املدعيــة نفســها وأنهــا لــم تســتلم أو تســتفد مــن أي‬\n     ‫شــيء مــن تلــك املبالــغ وبســؤال وكيــل املدعــى عليهــا هــل دخلــت املبالــغ‬\n\n\n‫‪99‬‬\n\f‫يف حســاب املدعــى عليهــا أجــاب قائــا ‪ :‬نعــم لقــد دخلــت املبالــغ التــي‬\n‫ذكرهــا وكيــل املدعيــة يف حســاب موكلتــي وقــد ذكــرت يف‬\n‫مذكرتــي ســبب دخولهــا ومــن تصــرف فيهــا هكــذا أجــاب وبســؤال‬\n‫وكيــل املدعيــة عــن املبلــغ الــذي يطالــب بــه حتديــدا حيــث ورد يف دعــواه‬\n‫أن موكلتــه حولــت ثالثــة وتســعون ألــف ريــال علــى دفعــات ثــم حولــت‬\n‫ثالثــة وســتون ألــف ريــال علــى دفعــات واملجمــوع مائــة وتســعة وعشــرون‬\n‫ألــف ريــال وليــس كمــا ذكــر يف دعــواه بــأن مــا تطالــب بــه موكلتــه‬\n‫مبلــغ وقــدره مائــة وثالثــون ألــف ريــال أجــاب قائــا ‪ :‬أطلــب املهلــة للرجوع‬\n‫ملوكلتــي لتحديــد املبلــغ بالتفصيــل هكــذا أجــاب وعليــه جــرى تأجيــل‬\n‫اجللســة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n‫وســلم ‪ .‬حــرر يف ‪ 1434/05/26‬ه ـ ثــم يف جلســة أخــرى حضــر املدعــي‬\n‫وكالــة خميــس واملدونــة هويتــه ووكالتــه ســابقا ولــم حتضــر املدعــى‬\n‫عليهــا وال وكيــا عنهــا رغــم تبلــغ وكيلهــا باملوعــد يف اجللســة املاضيــة‬\n‫وبنــاء علــى الفقــرة األولــى مــن املــادة اخلامســة واخلمســن مــن نظــام‬\n‫املرافعات الشــرعية قررت الســير يف الدعوى حضوريا وبســؤال املدعي‬\n‫وكالــة عمــا اســتمهل مــن أجلــه أجــاب قائــا ‪ :‬أوال ‪ /‬مــا مت إيداعــه مــن‬\n‫حســاب املدعيــة حلســاب املدعــى عليهــا ببنــك ‪ ...‬هــو مبلــغ (‪)108000‬‬\n‫مائــة وثمانيــة آالف ريــال كمــا هــو املوضــح بالكشــفني املرفقــة مــن‬\n‫نفــس البنــك يف أربعــة عشــر عمليــه مصرفيــة مفصلــة ثاني ـ ًا ‪ /‬مــا مت‬\n‫إيداعــه مــن حســاب املدعيــة حلســاب املدعــى عليهــا بالبنــك ‪ ...‬هــو‬\n‫(‪ )33000‬ثالثــة وثالثــون ألــف ريــال حســب مــا هــو مبــن يف كشــف‬\n‫احلســاب املرفــق والتــي متــت بســبع عمليــات مصرفيــه ثالث ـ ًا ‪ /‬مجمــوع‬\n‫املبالــغ احملولــة مــن املدعيــة علــى حســاب املدعــى عليهــا هــو(‪)141000‬‬\n\n\n                                                                                      ‫‪100‬‬\n\f      ‫مائــة وواحــد وأربعــون ألــف ريــال وهــو املبلــغ املطالــب بــه مــن املدعــى‬\n      ‫عليهــا مبوجــب كشــوفات احلســاب املرفقــة ومــا أقــروه بردهــم علــى هــذه‬\n      ‫الدعــوى باجلــدول املرفــق بالــرد وباالطــاع علــى املذكــرة التــي قدمهــا‬\n      ‫وكيــل املدعــى عليهــا وجدتهــا تتضمــن إقــرارا باملبالــغ التــي ذكرهــا‬\n      ‫املدعــي وكالــة كمــا جــرى االطــاع علــى كشــوفات احلســابات‬\n      ‫فوجدتهــا كمــا ذكــر املدعــي وكالــة فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واإلجابــة ومبــا أن وكيــل املدعــى عليهــا والتــي تخولــه وكالتــه عنهــا‬\n      ‫حــق اإلقــرار أقــر بدخــول املبالــغ املذكــورة يف الدعــوى ومجموعهــا مبلــغ‬\n      ‫وقــدره مائــة وواحــد وأربعــون ألــف ريــال يف حســاب املدعــى عليهــا ومبــا‬\n      ‫أن وكيــل املدعــى عليهــا دفــع بــأن موكلتــه كبيــرة يف الســن وغيــر‬\n      ‫متعلمــة وجتهــل مغبــة مــا أقدمــت عليــه وهــذا الدفــع ال يرفــع املســؤولية‬\n      ‫عــن املدعــى عليهــا ومبــا أن وكيــل املدعــى عليهــا دفــع بأنــه ليــس هنــاك‬\n      ‫صفــة تعاقديــة ملوكلتــه بينهــا وبــن املدعيــة وهــذا ال يخلــي مســؤوليتها‬\n      ‫مــن إعــادة مــا دخــل بحســابها ومبــا أن اإلقــرار حجــة علــى املقــر ومبــا أن‬\n      ‫املــرء مؤاخــذ بإقــراره ومبــا األصــل أن مــا يصــدر من اإلنســان من تصرف‬\n      ‫أنــه محمــول علــى الصحــة والنفــوذ وأنــه غيــر محجــور عليــه وال ســفيه‬\n      ‫وجلميــع مــا تقــدم فقــد حكمــت علــى املدعــى عليهــا حضوريــا بــأن تدفــع‬\n      ‫للمدعيــة مبلغــا وقــدره مائــة وواحــد وأربعــون ألــف ريــال حالــة بــدون‬\n      ‫مماطلــة وال تأخيــر وبعرضــه علــى املدعــي وكالــة قــرر القناعــة وألن‬\n      ‫املدعــى عليهــا لــم حتضــر قــررت إرســال نســخة مــن احلكــم للمدعــى‬\n      ‫عليهــا لالعتــراض عليهــا خــال ثالثــن يومــا مــن تاريــخ اســتالمها‬\n      ‫للحكــم وأنهــا إذا لــم تقــدم اعتراضــا بعــد تبلغهــا باحلكــم فيعــد احلكم‬\n      ‫مكتســبا للقطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n\n\n‫‪101‬‬\n\f                       ‫وعلى آله وصحبه وسلم ‪ .‬حرر يف ‪1434/07/11‬هـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬نحــن‬\n‫رئيــس وقضــاة الدائــرة اجلزائيــة الرابعة يف محكمة االســتئناف مبنطقة‬\n‫مكــة املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى محكمــة‬\n‫االســتئناف واملقيــدة برقــم ‪ 342858277‬وتاريــخ ‪1434/12/23‬هـ ـ‬\n‫املتعلقــة بطلــب االلتمــاس املقــدم مــن ‪ ......... /‬وكالــة إعــادة النظــر‬\n‫يف احلكــم الصــادر مــن فضيلــة الشــيخ ‪ ........... /‬القاضــي باحملكمــة‬\n‫العامــة بجــدة رقــم ‪ 34265447‬وتاريــخ ‪1434/7/10‬هـ ـ واملصــدق مــن‬\n‫محكمــة االســتئناف مبكــة املكرمــة بالقــرار رقــم ‪34358464‬‬\n‫وتاريــخ ‪1434/11/12‬ه ـ ـ وبدارســة املعاملــة تقــرر باألكثريــة إحالتهــا‬\n‫حلاكمهــا حيــث إن القضيــة جزائيــة لقبــول دعــوى االلتمــاس مــن عدمــة‬\n‫واهلل املوفــق‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34358464‬وتاريــخ‬\n                                              ‫‪1434/11/12‬هـ‪.‬‬\n\n\n\n\n                                                                                   ‫‪102‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":93,"source_page_end":102,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e8f4a9bb0125bd4f03e20e92fbb37a519cf0095ab7f73f6e83f97daf8d3e151a","normalized_text_hash":"78a8c60be708a85c6a1288d37abe3db77db25b3c2989c1d71e537a4cf1e5857e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p93-34265447"},{"id":"16fcde72-bdaf-5981-a90b-67cb31151173","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -نشل محفظة من اجليب -استعمال بطاقة فيزا - إثبات بالقرائن مع مين املدعي -احلكم بإلزام املدعى عليه بدفع املبلغ املدعى به.","document_number":"34262302","case_number":"3478135","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/8","year":"1434","subject":"رد مسروق -نشل محفظة من اجليب -استعمال بطاقة فيزا - إثبات بالقرائن مع مين املدعي -احلكم بإلزام املدعى عليه بدفع املبلغ املدعى به.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/7/8 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34262302 :‬‬\n                           ‫َر ْق ُم الدعوى‪3478135:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34305142‬تاريخه‪1434/8/24:‬هـ‬\n\n\n      ‫رد مســروق ‪ -‬نشــل محفظــة مــن اجليــب ‪ -‬اســتعمال بطاقــة فيــزا ‪-‬‬\n      ‫إثبــات بالقرائــن مــع ميــن املدعــي ‪ -‬احلكــم بإلــزام املدعــى عليــه بدفــع‬\n                                                                  ‫املبلــغ املدعــى بــه‪.‬‬\n\n\n\n\n      ‫‪ -1‬قــول ابــن فرحــون رحمــه اهلل يف التبصــرة (ص ‪« :)98‬فيمــن دخــل‬\n      ‫عليــه الســراق فســرقوا متاعــه وانتهبــوا مالــه وارادوا قتلــه فنازعهــم‬\n      ‫وحاربهــم ثــم ادعــى انــه عرفهــم أو لــم يعرفهــم هــو مصــدق عليهــم اذا‬\n      ‫كانــوا معروفــن بالســرقة مســتحلني لهــا او تــرى يكلــف البينــة قــال‬\n      ‫هــو مصــدق وقــد نزلــت قبــل هــذه باملدينــة يف زمــن عمــر بــن اخلطــاب‬\n                          ‫رضــي اهلل عنــه فغرمهــم عمــر ولــم يكلفــه البينــة» ‪.‬‬\n                                    ‫‪ -2‬اليمني تشرع يف جانب أقوى املتداعيني ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي علــى احلاضــر معــه أنــه قــام بنشــل محفظتــه مــن جيبــه‬\n      ‫واســتخرج منهــا بطاقــة االئتمــان اخلاصــة بــه واســتعملها بســحب مبلــغ‬\n      ‫نقــدي وبشــراء أجهــزة جــوال عــن طريقهــا‪ ،‬ولــذا فقــد طلــب إلزامــه‬\n      ‫بإعــادة املبالــغ التــي خصمــت منهــا إليــه ‪ -‬أنكــر املدعــى عليــه نشــل‬\n      ‫احملفظــة وأقــر باســتعمال البطاقــة يف شــراء أجهــزة جــوال بقيمــة أقــل‬\n\n‫‪103‬‬\n\f‫ممــا جــاء يف الدعــوى بعــد حصولــه عليهــا بطريــق مشــروع ‪ -‬قــدم املدعي‬\n‫كشــف حســاب بنكــي يبــن مجمــوع املبالــغ املســحوبة ‪ -‬املدعــي لــم‬\n‫يقــدم بينــة موصلــة تثبــت دعــواه إال أن جانبــه يتقــوى بالقرائــن املذكــورة‬\n‫يف أســباب احلكــم فتشــرع بحقــه اليمــن املكملــة‪ -‬قضــت احملكمــة‬\n‫بنــاء علــى القرائــن وميــن املدعــي املكملــة بإلــزام املدعــى عليــه بإعــادة‬\n‫جميــع املبالــغ التــي خصمــت مــن بطاقــة االئتمــان ‪ -‬قنــع املدعــي باحلكــم‬\n‫وعــارض املدعــى عليــه ‪ -‬قــررت محكمــة االســتئناف املصادقــة علــى‬\n                                                                      ‫احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالدمــام برقــم ‪ 3478135‬وتاريــخ ‪ 1434/02/17‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34393322‬وتاريــخ ‪ 1434/02/17‬ه ـ حضــر‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وادعــى علــى الســجني‬\n‫ا إن هــذا‬ ‫احلاضــر معــه ســعودي اجلنســية مبوجــب ســجله املدنــي رقــم قائـ ً‬\n‫احلاضــر معــي وأشــار إلــى املدعــى عليــه قــام بتاريــخ ‪1432/12/21‬ه ـ‬\n‫بنشــل محفظتــي حيــث كنــت يومهــا يف ســوق احلــراج بالدمــام وكان‬\n‫مــن ضمــن احملفظــة بطاقــة فيــزا عائــدة لــي ورقمهــا والتابعــة ملصــرف ‪...‬‬\n‫وســحب منهــا مبلــغ نقــدي قــدره خمســة آالف ريــال وكذلك ســحب منها‬\n‫مبلــغ وقــدره تســعة عشــر ألــف ومائتــان وتســعون ريـ‪ 19290‬ــاال بواســطة‬\n‫شــراءه مــن متجــر ‪ ...‬بالدمــام جــواالت عددهــا خمســة مــن نــوع ‪ ...‬لــذا‬\n‫فأطلــب احلكــم عليــه بدفــع املبلــغ املســتحق لــي يف ذمتــه والبالــغ قــدره‬\n\n                                                                                     ‫‪104‬‬\n\f      ‫أربعــة وعشــرون ألــف ومائتــان وتســعون ريــ‪ 24290‬ــاال حــا ًال هــذه دعــواي‬\n      ‫وبســؤال املدعــى عليــه عــن الدعــوى أجــاب بقولــه‪ :‬مــا ذكــره املدعــي‬\n      ‫يف دعــواه مــن قيامــي بنشــل محفظتــه فهــذا غيــر صحيــح وأنكــره متــام‬\n      ‫اإلنــكار وأمــا مــا ذكــره مــن أننــي قــد اســتخدمت بطاقتــه املذكــورة‬\n      ‫يف شــراء اجلــواالت املوصوفــة مــن ‪ ...‬بالتاريــخ املذكــور فهــذا صحيــح‬\n      ‫وأنــا لــم أكــن أعلــم بأنهــا عائــدة لــه وذلــك أننــي أطلــب زميلــي مبلــغ‬\n      ‫مالــي وقــدره خمســة آالف ريــال فســلم لــي البطاقــة وكنــت أعتقــد أنهــا‬\n      ‫لــه فقمــت بشــراء أربعــة جــواالت تقريبــا وال تتجــاوز قيمتهــا اخلمســة‬\n      ‫آالف ريــال ولــم أقــم بســحب أي مبلــغ آخــر ســوى مــا ذكــرت ولــذا فأنــا‬\n      ‫غيــر مســتعد بســداد املبلــغ املدعــى بــه هــذه إجابتــي ثــم أبــرز لــي املدعــي‬\n      ‫نســخة مــن كشــف حســاب بنكــي فوجدتــه يتضمــن شــراء جــواالت‬\n      ‫بلــغ قيمتهــا تســعة عشــر ألــف ومائتــان وتســعون ريــ‪19290‬ـ ــال مــن‬\n      ‫املتجــر املذكــور ومبلــغ خمســة آالف ريــال ومجمــوع املبلــغ املســحوب‬\n      ‫أربعــة وعشــرون ألفــا ومائتــان وتســعون ريــ‪ 24290‬ــاال ثــم أضــاف املدعــي‬\n      ‫بقولــه‪ :‬وأمــا املبلــغ املســحوب نقــدا فليــس لــدي بينــة عليــه إال أن ســحب‬\n      ‫املبلــغ مت يف نفــس اليــوم الــذي مت فيــه شــراء اجلــواالت واملدعــى عليــه قــد‬\n      ‫أقــر بأنــه اســتخدام البطاقــة ممــا يــدل علــى أنــه هــو مــن قــام بســحبه‬\n      ‫لكــون البطاقــة يف حوزتــه هكــذا أجــاب وعنــد وصــول القضيــة لهــذا‬\n      ‫احلــد جــرى رفــع اجللســة النتهــاء وقتهــا ويف جلســة أخــرى افتتحــت‬\n      ‫اجللســة بحضــور الطرفــن املرصــودة بياناتهــم آنفــا وقــد جــرى منــي تأمــل‬\n      ‫القضيــة ودراســتها فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث‬\n      ‫أنكــر املدعــى عليــه قيامــه بنشــل محفظــة املدعــي وأقــر باســتخدامه‬\n      ‫لبطاقــة الفيــزا العائــدة للمدعــي وشــرائه بواســطتها اجلــواالت املوصوفــة‬\n\n\n‫‪105‬‬\n\f‫مــن معــرض ‪ ...‬وحيــث ظهــر لــي قــوة جانــب املدعــي يف هــذه الدعــوى‬\n‫لألمــور التاليــة أوالً‪ :‬إلقــرار املدعــى عليــه باســتخدام بطاقــة املدعــي يف‬\n‫شــراء اجلــواالت األربعــة املوصوفــة مــن املعــرض املذكــور وقــد تبــن بــأن‬\n‫عددهــا أربعــة جــواالت وقيمتهــا طبــق مــا ذكــره املدعــي يف دعــواه بنــاء‬\n‫علــى كشــف احلســاب البنكــي ثاني ـاً‪ :‬أن املبلــغ النقــدي البالــغ قــدره‬\n‫خمســة آالف ريــال قــد ســحب يف نفــس تاريــخ اليــوم الــذي مت فيــه شــراء‬\n‫اجلــواالت األربعــة مــن املعــرض املذكــور بواســطة البطاقــة التــي أقــر‬\n‫املدعــي باســتخدامها يف الشــراء ثالث ـاً‪ :‬مــا ذكــره ابــن فرحــون رحمــه‬\n‫اهلل يف كتابــه التبصــرة يف البــاب اخلامــس والســتني يف القضــاء باللــوث‬\n‫يف األمــوال صفحــة رقــم ‪ 98‬مــن قولــه ‪ »:‬فيمــن دخــل عليــه الســراق‬\n‫فســرقوا متاعــه وانتهبــوا مالــه وأرادوا قتلــه فنازعهــم وحاربهــم ثــم ادعــى‬\n‫أنــه عرفهــم أو لــم يعرفهــم أهــو مصــدق عليهــم إذا كانــوا معروفــن‬\n‫بالســرقة مســتحلني لهــا أو تــرى أن يكلــف البينــة قــال‪ :‬هــو مصــدق‬\n‫وقــد نزلــت مثــل هــذه باملدينــة يف زمــن عمــر بــن اخلطــاب رضــي اهلل عنــه‬\n‫فغرمهــم عمــر ولــم يكلفــه البينــة « ومبــا أن اليمــن تشــرع يف جانــب‬\n‫أقــوى املتداعيــن كمــا ذكــر ذلــك احملققــون مــن أهــل العلــم كابــن‬\n‫تيميــة وابــن القيــم رحمهمــا اهلل لــذا فقــد جــرى ســؤال املدعــي هــل يحلف‬\n‫اليمــن علــى أن املدعــى عليــه هــو مــن قــام بنشــل محفظتــه وكان مــن‬\n‫ضمنهــا بطاقــة فيــزا وأنــه ســحب منهــا مبلــغ نقــدي قــدره خمســة آالف‬\n‫ريــال مــن حســابه وكذلــك ســحب منهــا مبلــغ وقــدره تســعة عشــر ألــف‬\n‫ومائتــان وتســعون ريــ‪19290‬ـ ــاال بواســطة شــراءه مــن متجــر ‪ ...‬اجلــواالت‬\n‫وال يعلــم أحــد ًا غيــره قــد ســحبه مــن احلســاب فأجــاب بقولــه نعــم مســتعد‬\n‫بتأديتهــا بعــد أن جــرى تخويفــه مــن عاقبــة اليمــن الكاذبــة ثــم أذنــت لــه‬\n\n\n                                                                                     ‫‪106‬‬\n\f      ‫ا واهلل العظيــم أن املدعــى عليــه هــو مــن قــام بنشــل‬  ‫باحللــف فحلــف قائـ ً‬\n      ‫محفظتــي وكان مــن ضمنهــا بطاقــة الفيــزا العائــدة لــي وأنــه ســحب‬\n      ‫منهــا مبلــغ نقــدي قــدره خمســة آالف ريــال مــن حســابي وكذلــك ســحب‬\n      ‫منهــا مبلــغ وقــدره تســعة عشــر ألــف ومائتــان وتســعون ريــ‪19290‬ـ ــاال‬\n      ‫بواســطة شــراءه مــن متجــر ‪ ...‬اجلــواالت وال أعلــم أحــد ًا غيــره قــد ســحبه‬\n      ‫مــن احلســاب هكــذا حلــف لــذا وملــا تقــدم كلــه فقــد ألزمــت املدعــى‬\n      ‫عليــه بــأن يدفــع للمدعــي املبلــغ املدعــى بــه وقــدره أربعــة وعشــرون ألــف‬\n      ‫ومائتــان وتســعون ريــ‪ 24290‬ــاال حــا ًال وبــه حكمــت وبعــرض احلكــم‬\n      ‫علــى املدعــي قنــع بــه وأمــا املدعــى عليــه فقــرر عــدم القناعــة باحلكــم‬\n      ‫وطلــب االســتئناف واســتعد بتقــدمي الئحــة اعتراضية علــى احلكم فأفهم‬\n      ‫بأنــه ســيتم طلبــه لكونــه ســجني يف تاريــخ ‪1434/07/11‬ه ـ لتزويــده‬\n      ‫صــورة مــن إعــام احلكــم لتقــدمي اعتراضــه عليــه خــال ثالثــن يومـ ًا مــن‬\n      ‫تاريــخ اســتالمه لــه وإذا لــم يتــم تقــدمي اعتراضــه خاللهــا فيســقط حقــه‬\n      ‫يف االعتــراض ويكتســب احلكــم القطعيــة ففهــم ذلــك وبــاهلل التوفيــق‬\n      ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                     ‫‪ 1434/07/02‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد جــرى املصادقــة علــى هــذا احلكــم الصــادر‬\n      ‫منــا يف هــذه القضيــة برقــم ‪ 34262302‬يف ‪1434/07/08‬ه ـ وذلــك‬\n      ‫مبوجــب قــرار أصحــاب الفضيلــة قضــاة الدائــرة احلقوقيــة األولــى‬\n      ‫رقــم‪ 34305142‬يف ‪1434/08/24‬ه ـ وللبيــان جــرى حتريــره وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد ‪ .‬حــرر يف ‪1434/09/20‬ه ـ ‪.‬‬\n\n\n\n\n‫‪107‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":103,"source_page_end":107,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8d51a3fae41cca5727aedc198239cfbac01b3d2eb90bae806e62c494814d301c","normalized_text_hash":"e9758c3a38f2fff40bde545b0c58299c503a53b4e6bda1ced654d9b22146eec6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p103-34262302"},{"id":"26cc6a61-2ed0-5d5d-98a1-48ec2b9aa06c","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة ذهب من سيارة -عجز عن إقامة البينة - استخالف يف أخذ اليمن النافيه للدعوى -صرف النظر عن","document_number":"343219","case_number":"32129181","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/5","year":"1434","subject":"رد مسروق -سرقة ذهب من سيارة -عجز عن إقامة البينة - استخالف يف أخذ اليمن النافيه للدعوى -صرف النظر عن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫تاريخه‪1434/1/5 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                      ‫الص ِّك‪343219 :‬‬\n                   ‫َر ْق ُم الدعوى‪32129181 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3456542‬تاريخه‪1434/3/7:‬هـ‬\n\n\n‫رد مســروق ‪ -‬ســرقة ذهــب مــن ســيارة ‪ -‬عجــز عــن إقامــة البينــة ‪-‬‬\n‫اســتخالف يف أخــذ اليمــن النافيــه للدعــوى ‪ -‬صــرف النظــر عــن‬\n                                                         ‫الد عــوى‪.‬‬\n\n\n\n\n‫مــا اســتند إليــه القاضــي مــن مبــادئ عامــة وقواعــد العدالــة الــواردة يف‬\n                                                            ‫تســبيب احلكــم‪.‬‬\n\n\n\n\n‫ادعــى املدعــي علــى املدعــى عليهــا املمثلــة بوكيلهــا احلاضــر بأنهــا‬\n‫قامــت بســرقة أربعــة أطقــم ذهــب مــن ســيارته‪ ،‬وطلــب إلزامهــا بإعــادة‬\n‫الذهــب املســروق إليــه ‪ -‬أنكــر وكيــل املدعــى عليهــا مــا جــاء يف دعــوى‬\n‫املدعــي جتــاه موكلتــه ‪ -‬املدعــي لــم يقــدم بينــة تثبــت دعــواه وطلــب ميــن‬\n‫املدعــى عليهــا علــى نفيهــا فذكــر وكيلهــا بأنهــا تقيــم خــارج البــاد ‪-‬‬\n‫قــررت احملكمــة اســتخالف اجلهــة املختصــة يف أخــذ ميــن املدعــى عليهــا‬\n‫فحلفــت طبــق مــا طلــب منهــا ‪ -‬قضــت احملكمــة بصــرف النظــر عــن‬\n‫دعــوى املدعــي جتــاه املدعــى عليهــا ‪ -‬عــارض املدعــي علــى احلكــم ‪-‬‬\n      ‫قــررت محكمــة االســتئناف باألكثريــة املصادقــة علــى احلكــم ‪.‬‬\n\n\n                                                                                     ‫‪108‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالريــاض برقــم ‪ 32129181‬وتاريــخ ‪1432/04/18‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 32344072‬وتاريــخ ‪ 1432/04/07‬ه ـ ففــي يــوم‬\n      ‫االثنــن املوافق‪1432/11/05‬ه ـ افتتحــت اجللســة الســاعة ‪09 : 43‬‬\n      ‫وفيهــا حضــر‪ ...‬اجلنســية مبوجــب اإلقامــة رقــم وحضــر حلضــوره ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم وكيــا عــن هنديــة اجلنســية‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بالريــاض برقــم‬\n      ‫‪ 19749‬يف ‪1432/3/19‬ه ـ جلــد ‪ 19345‬وادعــى األول بواســطة املترجــم‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم قائــا يف دعــواه لقــد‬\n      ‫ســرقت املدعــى عليهــا أربعــة أطقــم ذهــب قيمتهــا أكثــر مــن خمســن‬\n      ‫ألــف ريــال ســعودي وقــد ســرقتها مــن ســيارتي والذهــب املســروق عبــارة‬\n      ‫عــن أطقــم يتكــون كل طقــم مــن حلــق وسلســلة وســواره عيــار واحــد‬\n      ‫وعشــرين كمــا أخــذت اثباتــات بناتــي األربعــة وهــن‪ ..‬و‪....‬و‪ ...‬و‪...‬وقــد‬\n      ‫قامــت بنقــل كفالــة البنــات إليهــا دون الرجــوع إلــى موافقتــي أطلــب‬\n      ‫إلــزام املدعــى عليــه بإعــادة الذهــب املســروق الــذي ذكرتــه يف دعــواي‬\n      ‫وتســليمي بناتــي املذكــورات هــذه دعــواي وبعــرض دعــوى املدعــي علــى‬\n      ‫املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي يف دعــواه غيــر صحيــح‬\n      ‫جملــة وتفصيــا فلــم تســرق موكلتــي مــن املدعــي أي شــيئا مــن الذهــب‬\n      ‫املذكــور وليــس لــه يف ذمــة موكلتــي شــيئا مــن الذهــب املذكــور أمــا‬\n      ‫مــا يتعلــق بطلبــه تســليم بناتــه املذكــورات لــه فيوجــد قضيــة منظــورة‬\n\n‫‪109‬‬\n\f‫اآلن لــدى املكتــب القضائــي الســابع والعشــرين بخصــوص احلضانــة‬\n‫فقــط هكــذا أجــاب فســألت املدعــي هــل لديــه بينــة علــى صحــة دعــواه‬\n‫وأن املدعــى عليهــا أصالــة ســرقت منــه الذهــب املذكــور يف دعــواه‬\n‫فأجــاب قائــا مــا عنــدي بينــة إال أنــا رأيتهــا وهــي تســرق مــن الســيارة‬\n‫فأفهمتــه بــأن لــه ميــن املدعــى عليهــا علــى نفــي دعــواه فقــال أطلــب ميينهــا‬\n‫وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال إن موكلتــي تقيــم اآلن يف‬\n‫بلدهــا الهنــد فرفعــت اجللســة إلــى يــوم الســبت املوافــق ‪1432/11/10‬ه ـ‬\n‫الســاعة الثامنــة والربــع صباحــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1432/11/05‬ه ـ احلمــد هلل‬\n‫وحــده وبعــد ففــي يــوم الســبت املوافــق ‪1432/11/10‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 09 : 19‬وفيهــا حضــر املدعــي وحضــر حلضورهــا املدعــى عليــه‬\n‫وكالــة بالســجل املدنــي رقــم وقــرر املدعــى عليــه أن موكلتــه تقيــم يف‬\n‫واليــة ‪ ....‬يف الهنــد فأمــرت بالكتابــة إلــى محكمــة ‪ ...‬ألخذ ميني املدعى‬\n‫عليهــا أصالــة علــى نفــي دعــوى املدعــي وحتــى ورود اجلواب رفعت اجللســة‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n‫‪ .‬حــرر يف ‪1432/11/10‬ه ـ ويف يــوم االثنــن املوافــق‪ 1434/01/05‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 09 : 30‬وفيهــا حضــر الطرفــان وقــد وردنــا‬\n‫خطــاب وكيــل وزارة اخلارجيــة للشــؤون القنصليــة رقــم ‪33694/3/8‬‬\n‫وتاريــخ ‪1433/01/29‬ه ـ املرفــق بــه أن املدعــى عليهــا أصالــة حلفــت‬\n‫لــدى ســفارة اململكــة العربيــة الســعودية يف نيــو دلهــي قائلــة واهلل‬\n‫العظيــم الــذي ال إلــه إال هــو عالــم الغيــب والشــهادة أننــي لــم أســرق مــن‬\n‫ســيارة املدعــي أربعــة أطقــم ذهــب وليــس يف ذمتــي للمدعــي ممــا يدعيــه‬\n‫شــيء واهلل العظيــم فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن‬\n\n\n                                                                                         ‫‪110‬‬\n\f      ‫وكيــل املدعــى عليهــا أنكــر الدعــوى ولــم يقــم املدعــي بينــة علــى صحــة‬\n      ‫دعــواه وطلــب ميــن املدعــى عليهــا أصالــه وحلفــت طبــق مــا طلــب منهــا لذا‬\n      ‫فقــد حكمــت بعــدم اســتحقاق املدعــي ملــا يدعيــه جتــاه املدعــى عليهــا‬\n      ‫وصرفــت النظــر عــن دعــواه وبعــرض احلكــم علــى املدعــي قــرر عــدم‬\n      ‫قناعتــه بــه وطلــب االســتئناف فأجيــب لطلبــه وقــد اعطــي صــورة مــن‬\n      ‫صــك احلكــم يف حينــه لتقــدمي اعتراضــه عليــه خــال ثالثــن يومــا وإذا‬\n      ‫انتهــت املــدة ولــم يتقــدم خاللهــا باعتراضــه فيســقط حقــه يف االســتئناف‬\n      ‫ويكتســب احلكــم القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                  ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/01/05‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫برقــم ‪ 34291478‬يف ‪1434/3/23‬ه ـ واملقيــدة باحملكمــة برقــم‬\n      ‫‪ 34752822‬يف ‪1434/3/25‬ه ـ واملرفــق بهــا القــرار رقــم ‪ 3456542‬يف‬\n      ‫‪1434/3/7‬ه ـ واملــدون علــى ظهــر الصك املتضمــن باألكثرية املصادقة‬\n      ‫علــى احلكــم وحتــى ال يخفــى جــرى إحلاقــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/4/2‬ه ـ ‪.‬‬\n\n\n\n\n‫‪111‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":108,"source_page_end":111,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ef74ecce34629273fb2f2da066ebc3c6ff7c07ac9031f182439fd4e59c560f5e","normalized_text_hash":"33674c19ffefed240fcbd36cf64c6efe54fd7370c76d286b30f37acd2e3b1311","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p108-343219"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"b01eb5c5-75c9-5ec2-9d90-45292a6cf71a","document_type":"judgment","category":"judicial","subcategory":"general","title":"منع من السفر -مطالبة باملنع من السفر حلن الفصل يف قضية منظورة -قاضي األصل هو قاضي الفرع -ناظر الدعوى األصلية مختص بطلب املنع من السفر -مصادقة املدعى عليه على وجود دعوى منظورة ضده -االستعانة بأهل اخلبرة يف تقدير التأمن الازم للممنوع من السفر -إيداع التأمن يف بيت مال المحكمة - احلكم باملنع من السفر حتى انتهاء القضية املنظورة .","document_number":"34353441","case_number":"34474747","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بحائل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/6","year":"1434","subject":"منع من السفر -مطالبة باملنع من السفر حلن الفصل يف قضية منظورة -قاضي األصل هو قاضي الفرع -ناظر الدعوى األصلية مختص بطلب املنع من السفر -مصادقة املدعى عليه على وجود دعوى منظورة ضده -االستعانة بأهل اخلبرة يف تقدير التأمن الازم للممنوع من السفر -إيداع التأمن يف بيت مال المحكمة - احلكم باملنع من السفر حتى انتهاء القضية املنظورة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/11/6 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34353441 :‬‬\n                        ‫َر ْق ُم الدعوى‪34474747 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n               ‫‪ 34369155‬تاريخه‪1434/11/25:‬هـ‬\n\n\n     ‫منــع مــن الســفر‪ -‬مطالبــة باملنــع مــن الســفر حلــن الفصــل يف قضيــة‬\n     ‫منظــورة ‪ -‬قاضــي األصــل هــو قاضــي الفــرع ‪ -‬ناظــر الدعــوى األصليــة‬\n     ‫مختــص بطلــب املنــع مــن الســفر‪ -‬مصادقــة املدعــى عليــه علــى وجــود‬\n     ‫دعــوى منظــورة ضــده ‪ -‬االســتعانة بأهــل اخلبــرة يف تقديــر التأمــن‬\n     ‫الــازم للممنــوع مــن الســفر‪ -‬إيــداع التأمــن يف بيــت مــال احملكمــة ‪-‬‬\n                 ‫احلكــم باملنــع مــن الســفر حتــى انتهــاء القضيــة املنظــورة ‪.‬‬\n\n\n\n\n                ‫املادة ‪ 4/236‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي بأنــه تقــدم بدعــوى ضــد املدعــى عليــه يف مطالبــة ماليــة‬\n     ‫منظــورة لــدى ناظــر هــذه الدعــوى ويطلــب منــع املدعــى عليــه مــن الســفر‬\n     ‫حتــى انتهــاء القضيــة األصليــة هكــذا ادعــى ‪ -‬أجــاب املدعــى عليــه‬\n     ‫باملصادقــة علــى وجــود دعــوى ماليــة مازالــت منظــورة ويطلــب صــرف‬\n     ‫النظــر عــن الدعــوى ‪ -‬جــرت الكتابــة لهيئــة اخلبــراء لتقديــر التأمــن‬\n     ‫الــازم ملثــل ذلــك وفق ـ ًا للمــادة‪ 4/236‬مــن نظــام املرافعــات الشــرعية ‪-‬‬\n     ‫ورد قرارهــم بــأن مقــدار التأمــن خمســة آالف ريــال ‪ -‬قــدم املدعــي مبلــغ‬\n     ‫التأمــن مبوجــب الشــيك ألمــر رئيــس احملكمــة ‪ -‬وبنــاء علــى املــادة ‪236‬‬\n‫‪57‬‬\n\f‫مــن نظــام املرافعــات الشــرعية والئحتــه ‪ -‬احلكــم مبنــع املدعــى عليــه‬\n‫مــن الســفر حتــى انتهــاء القضيــة املنظــورة بينــه وبــن املدعــي ‪ -‬اعتــرض‬\n‫املدعــى عليــه بالئحــة ‪ -‬صــدق احلكــم مــن الدائــرة احلقوقيــة األولــى‬\n                                    ‫مبحكمــة االســتئناف مبنطقــة حائــل ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة العامــة‬\n‫بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بحائــل املســاعد برقــم ‪ 34474747‬وتاريــخ ‪ 1434/10/26‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 342422134‬وتاريــخ ‪ 1434/10/26‬ه ـ‬\n‫ففــي يــوم اخلميــس املوافــق‪ 1434/10/29‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪ 11 : 00‬وفيهــا حضــر ‪ ...... ......‬ســعودي اجلنســية مبوجــب الســجل‬\n‫ا عــن ‪ ......‬مبوجــب الوكالــة الصــادرة مــن‬           ‫املدنــي رقــم ‪ ......‬وكي ـ ً‬\n‫كتابــة العــدل الثانيــة بالدمــام رقــم ‪ 34627806‬وتاريــخ ‪1434/5/18‬ه ـ‬\n‫املخــول لــه فيهــا حــق املرافعــة واملدافعــة وســماع الدعــاوى والــرد‬\n‫عليهــا واإلنــكار وطلــب اليمــن ورده واالمتنــاع عنــه وإحضــار الشــهود‬\n‫والبينــات والطعــن فيهــا وطلــب املنــع مــن الســفر ورفعــه وقبــول االحــكام‬\n‫ونفيهــا واالعتــراض علــى األحــكام وطلــب االســتئناف ولــه حــق توكيــل‬\n‫غيــره فادعــى علــى احلاضــر معــه يف املجلــس الشــرعي ‪ ...... ......‬مصــري‬\n‫ا يف تقريــر دعــواه ضــده إنــه‬    ‫اجلنســية مبوجــب اإلقامــة رقــم ‪ ......‬قائ ـ ً‬\n‫يوجــد لــدى فضيلتكــم ملوكلــي دعــوى ضــد املدعــى عليــه مقيــدة برقــم‬\n‫‪ 1/4944‬يف ‪1431/7/22‬ه ـ بشــأن مطالبــة ماليــة ومــا زالــت قيــد النظــر‬\n‫لــذا أطلــب منــع املدعــى عليــه مــن الســفر حتــى انتهــاء القضيــة املذكــورة‬\n\n                                                                                         ‫‪58‬‬\n\f     ‫وتنفيذهــا هــذه دعــواي وبعرضهــا علــى املدعــى عليــه قــال مــا ذكــره‬\n     ‫املدعــي وكالــة صحيــح وأنــا مــن ســت ســنوات لــم أســافر وأطلــب صــرف‬\n     ‫النظــر عــن دعــوى املدعــي وكالــة ألنهــا كيديــة هكــذا أجــاب وعليــه‬\n     ‫قــررت الكتابــة لهيئــة اخلبــراء لتقديــر التأمــن الــازم ملثــل ذلــك حســب‬\n     ‫املــادة رقــم ‪ 4/236‬مــن نظــام املرافعــات ولوائحــه ورفعــت لذلــك اجللســة‬\n     ‫ويف جلســة أخــرى وفيهــا حضــر املدعــي وكالــة و املدعــى عليــه ‪ ،‬وقــد‬\n     ‫وردنــا كتــاب رئيــس هيئــة اخلبــراء باحملكمــة رقــم ‪ 342496266‬يف‬\n     ‫‪1434/11/6‬ه ـ مرفقـ ًا بــه قــرار الهيئــة املتضمــن تقديــر التأمــن الــازم‬\n     ‫ملنــع املدعــى عليــه مــن الســفر بخمســة آالف ريــال ‪ ،‬وبعرضــه علــى‬\n     ‫املدعــي قــال ‪ :‬المانــع لــدي مــن إيــداع التأمــن املذكــور ‪ ،‬وقــدم الشــيك‬\n     ‫املســحوب علــى مصــرف ‪ ......‬برقــم ‪ 275938‬وتاريــخ ‪1434/10/18‬ه ـ‬\n     ‫مببلــغ خمســة آالف ريــال ألمــر رئيــس محاكــم منطقــة حائــل فجــرى‬\n     ‫ـاء علــى‬\n            ‫ضمــه مللــف الدعــوى إليداعــه الحقـ ًا يف حســاب احملكمــة ‪ ،‬فبنـ ً‬\n     ‫ماتقــدم مــن الدعــوى واإلجابــة املتضمنــة مصادقــة املدعــى عليــه علــى‬\n     ‫وجــود دعــوى قائمــة ضــده وال زالــت قيــد النظــر ‪ ،‬وبنــاء علــى قــرار هيئــة‬\n     ‫اخلبــراء املشــار إليــه أعــاه وبنــاء علــى املــادة ‪ 236‬مــن نظــام املرافعــات‬\n     ‫ولوائحــه فقــد قــررت منــع الدعــى عليــه مــن الســفر حتــى انتهــاء القضيــة‬\n     ‫املنظــورة بينــه وبــن املدعــي املشــار إلــى رقمهــا ســلف ًا وبذلــك حكمــت ‪،‬‬\n     ‫وبعــرض احلكــم اعتــرض املدعــى عليــه ‪ ،‬وقــدم اســتدعائه املقيــد بهــذه‬\n     ‫احملكمــة برقــم ‪ 34/2534325‬بتاريــخ ‪1434/11/6‬ه ـ وطلــب رفعــه‬\n     ‫حملكمــة االســتئناف معتبــر ًا االســتدعاء الئحــة اعتراضيــة لــه وبــاهلل‬\n                                                 ‫التوفيــق حــرر يف ‪1434/11/6‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة‬\n\n\n‫‪59‬‬\n\f‫األولــى لتدقيــق القضايــا احلقوقيــة مبحكمــة االســتئناف مبنطقــة‬\n‫حائــل علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بحائــل املســاعد برقــم ‪342422134‬وتاريــخ ‪1434/11/18‬ه ـ واملقيــدة‬\n‫لدينــا بتاريــخ ‪1434/11/20‬ه ـ املرفــق بهــا الصــك رقــم ‪34353441‬يف‬\n‫‪1434/11/6‬ه ـ الصــادر مــن فضيلــة القاضــي‪ ....../‬اخلــاص بدعــوى ‪......‬‬\n‫وكالــة ضــد ‪ ......‬مصــري اجلنســية بشــأن دعــوى منــع مــن الســفر علــى‬\n‫الصفــة املوضحــة يف الصــك وقــد تضمــن الصــك حكــم فضيلتــه كمــا‬\n‫هــو مــدون ومفصــل فيــه وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة لــم يظهــر مــا يوجــب املالحظــة لــذا جــرت‬\n‫املصادقــة واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                         ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪60‬‬\n\f61\n\f62\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":57,"source_page_end":62,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2a9f7ccc443e7ea1831c7b02f827e00e1f689659d86e53fa5d9d35a163a49771","normalized_text_hash":"ebe0f17b1298e60b674481ad420948749512b1a44909d5eb608fadf8ac9192d2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p57-34353441"},{"id":"80d49d17-e42c-5fd3-956f-34921f5428c6","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة برد مسروق -سرقة مبالغ مالية من سيارة نقل األموال- تفريط يف حفظ املسروق -عجز عن إثبات الدفع -إدخال خصم جديد يف الدعوى -رد الدعوى عن اخلصم املدخل -ضمان األجير اخلاص -ثبوت الدعوى .","document_number":"33192872","case_number":"323066","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باخلبر املساعد احلمد هلل وحده","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/4/17","year":"1434","subject":"مطالبة برد مسروق -سرقة مبالغ مالية من سيارة نقل األموال- تفريط يف حفظ املسروق -عجز عن إثبات الدفع -إدخال خصم جديد يف الدعوى -رد الدعوى عن اخلصم املدخل -ضمان األجير اخلاص -ثبوت الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/4/17 :‬هـ‬\n                     ‫ُ‬                 ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪33192872 :‬‬\n                           ‫َر ْق ُم الدعوى‪323066:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3410902‬تاريخه‪1434/1/13:‬هـ‬\n\n\n     ‫مطالبــة بــرد مســروق ‪ -‬ســرقة مبالــغ ماليــة مــن ســيارة نقــل األمــوال‪-‬‬\n     ‫تفريــط يف حفــظ املســروق‪ -‬عجــز عــن إثبــات الدفــع ‪ -‬إدخــال خصــم‬\n     ‫جديــد يف الدعــوى ‪ -‬رد الدعــوى عــن اخلصــم املدخــل‪ -‬ضمــان األجيــر‬\n                                                 ‫اخلــاص‪ -‬ثبــوت الدعــوى ‪.‬‬\n\n\n\n\n     ‫‪ -1‬قــول النبــي صلــى اهلل عليــه وآلــه وســلم‪ ( :‬علــى اليــد مــا أخــذت حتــى‬\n                               ‫تؤديــه ) رواه أحمــد واألربعــة وصححــه احلاكم‪.‬‬\n     ‫‪ -2‬األجير اخلاص ال يضمن إال يف حال التعدي أو التفريط‪ .‬الروض‬\n                            ‫املربع للبهوتي مع حاشــية بن قاســم (ج‪ 5‬ص‪.)336‬‬\n                                    ‫‪ -3‬املادة (‪ )76‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n     ‫ادعــى وكيــل الشــركة املدعيــة بــأن املدعــى عليهمــا احلاضريــن اســتلما‬\n     ‫مــن موكلتــه َّإبــان عملهمــا لديهــا كمشــريف تغذيــة صرافــات آليــة‬\n     ‫مبالــغ ماليــة لكــي يقومــا بتغذيــة عــدد مــن الصرافــات اآلليــة بهــا إال‬\n     ‫أنهمــا ادعيــا أن تلــك املبالــغ ســرقت منهمــا‪ ،‬ولــذا فقــد طلــب إلزامهمــا‬\n     ‫بإعــادة املبالــغ املســروقة متضامنــن إلــى الشــركة موكلتــه ‪ -‬أقــر‬\n     ‫املدعــى عليهمــا باســتالم املبالــغ املاليــة محــل الدعــوى ودفــع كل واحــد‬\n\n‫‪63‬‬\n\f‫منهمــا بأنــه لــم يفــرط يف حفــظ األمــوال املســروقة ولذلــك فهــو غيــر‬\n‫مســتعد بتســليم املدعيــة أي شــيء مــن تلــك املبالــغ ‪ -‬املدعــى عليــه الثانــي‬\n‫دفــع أيض ـ ًا بــأن املدعــى عليــه األول وشــخص ثالــث كان معهمــا همــا‬\n‫مــن قامــا باالســتيالء علــى املبلــغ املدعــى بــه إال أنــه لــم يقــدم بينــة موصلــة‬\n‫علــى هــذا الدفــع ‪ -‬قــررت احملكمــة إدخــال الشــخص الثالــث املرافــق‬\n‫للمدعــى عليهمــا يف الدعــوى وعرضــت عليــه مــا اتهمــه بــه املدعــى عليــه‬\n‫الثانــي فأنكــر ذلــك وأدى اليمــن علــى نفــي تلــك الدعــوى ‪ -‬وملــا كان‬\n‫املدعــى عليهمــا أجيريــن خاصــن فيضمنــان بالتعــدي أو التفريــط‬\n‫واحلكــم الصــادر يف احلــق العــام يدينهمــا بالتفريــط ‪ -‬قضــت احملكمــة‬\n‫بإلــزام املدعــى عليهمــا بتســليم الشــركة املدعيــة املبلــغ املدعــى بــه‬\n‫متضامنــن فيتحمــل كل واحــد منهمــا نصــف املبلــغ وللمدعيــة مطالبــة‬\n‫أحدهمــا بكامــل املبلــغ احملكــوم بــه ولــه الرجــوع علــى صاحبــه بســداد‬\n‫مــا دفعــه للشــركة‪ ،‬وصرفــت النظــر عــن دعــوى املدعــى عليــه الثانــي‬\n‫ضــد املدخــل لعــدم ثبوتهــا‪ -‬عــارض املدعــى عليهمــا علــى احلكــم‪-‬‬\n                     ‫قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫لدي أنا ‪ ...‬رئيس احملكمة العامة باخلبر املساعد‬   ‫احلمد هلل وحده وبعد ّ‬\n‫ـاء علــى املعاملــة احملالــة لــي برقــم ‪ 323066‬وتأريــخ ‪1432/01/05‬ه ـ‬‫وبنـ ً‬\n‫املقيــدة باحملكمــة برقــم ‪ 328408‬وتاريــخ ‪1432/1/5‬ه ففــي يــوم‬\n‫االثنــن املوافق‪1432/04/23‬ه ـ حضــر ‪ ...‬ســعودي بالســجل املدنــي‬\n‫رقــم ‪ ...‬بالوكالــة عــن ‪ ...‬ســعودي بالســجل املدنــي رقــم ‪ ...‬أصالــة عــن‬\n‫نفســه ومبوجــب وكالتــه عــن ‪ ...‬وهمــا أصحــاب شــركة ‪ ....‬ملعــدات‬\n\n                                                                                             ‫‪64‬‬\n\f     ‫األمــن والســامة والتجــارة احملــدودة وذلــك كلــه مبوجــب الوكالــة‬\n     ‫الصــادرة مــن مســاعد رئيــس كتابــة عــدل اخلبــر الثانيــة برقــم ‪1187‬‬\n     ‫يف ‪1429/1/11‬ه ـ جلــد ‪ 1670‬وهــذه الوكالــة تخــول الوكيــل حــق‬\n                                              ‫املرافعــة وحضــر حلضــوره كل مــن‪:‬‬\n     ‫‪ / -1‬ســعودي بالســجل املدنــي رقــم ‪ / -2‬ســعودي بالســجل املدنــي رقــم‬\n     ‫بالوكالــة عــن ‪ /‬ســعودي بالســجل املدنــي رقــم وذلــك مبوجــب الوكالــة‬\n     ‫الصــادرة مــن كتابــة عــدل القطيف برقم ‪ 3278227‬يف ‪1432/4/22‬هـ‬\n     ‫وهــذه الوكالــة تخــول الوكيــل حــق املدافعــة ثــم ادعــى ‪ ....‬بقولــه‪ :‬إن‬\n     ‫كل‬‫لشــركة ‪ ....‬ملعــدات األمــن والســامة والتجــارة احملــدودة بذمــة ٍ‬\n     ‫مــن‪ :‬مبلغـ ًا قــدره مليــون وســبعة وســبعون ألفـ ًا وســتون ريــا ًال ( ‪1077060‬‬\n     ‫ريــال ) حيــث يتحمــل املدعــى عليهمــا كامــل هــذا املبلــغ متضامنــن‬\n     ‫وســبب ذلــك أن املدعــى عليهمــا يعمــان لــدى الشــركة املدعيــة‬\n     ‫ومســمى وظيفتهمــا مشــريف تغذيــة صرافــات آليــة للبنــك ‪ ....‬حيــث إن‬\n     ‫بــن الشــركة املدعيــة والبنــك ‪ ....‬عقــد ًا يف ذلــك وقــد اســتلم املدعــى‬\n     ‫عليهمــا املبلــغ املدعــى بــه علــى النحــو التالــي‪ -1 :‬مبلغـ ًا قــدره خمســمائة‬\n     ‫وخمســون ألــف ريــال مت اســتالمه مــن البنــك ‪ ....‬لتغذيــة الصــراف اآللــي‬\n                                                                          ‫مبحطــة ‪.....‬‬\n     ‫‪ -2‬مبلغ ـ ًا قــدره ثالثمائــة وواحــد وخمســون ألف ـ ًا وثمامنائــة ريــال مت‬\n     ‫اســتالمه كرجيــع مــن الصــراف اآللــي رقــم ( ‪ ) 3111‬بالثقبــة ‪ -3‬مبلغـ ًا‬\n     ‫قــدره مئــة وخمســة وســبعون ألفـ ًا ومئتــان وســتون ريــا ًال مت اســتالمه مــن‬\n     ‫جهــاز إيــداع مــن الصــراف اآللــي رقــم ( ‪ ) 311‬بالثقبــة وأثنــاء توقــف‬\n     ‫الســيارة التــي حتمــل جميــع هــذه املبالــغ عنــد مجمــع ‪ ....‬التجــاري حســب‬\n     ‫زعــم املدعــى عليهمــا ســرقت مــن الســيارة جميــع هــذه املبالــغ وكان‬\n\n\n‫‪65‬‬\n\f‫ذلــك بتاريــخ ‪2008/8/13‬م لــذا فإنــي أطلــب ســؤال املدعــى عليهمــا‬\n‫هذيــن احلاضريــن وإلــزام ‪ ......‬و‪ ......‬بإعــادة هــذه املبالــغ للشــركة‬\n‫موكلتــي علم ـ ًا أن البنــك ‪ ....‬قــد خصــم هــذه املبالــغ مــن اســتحقاقات‬\n‫الشــركة املدعيــة لديــه هكــذا ادعــى ‪ ،‬ويف جلســة أخــرى حضر املدعي‬\n‫وكالــة وحضــر حلضــوره املدعــى عليــه أصالــة ‪ /‬ولــم يحضـ ــر املدعـ ــى‬\n‫عليـ ــه ‪ /‬وال أي وكيــل عنــه ثــم طلبــت مــن املدعــى عليــه ‪ /‬اجلــواب علــى‬\n‫الدعــوى فقــال‪ :‬إننــي غيــر مســتعد بدفــع أي شــيء مــن املبلــغ املدعــى بــه‬\n‫ألننــي واملدعــى عليــه الثانــي ‪ /‬لــم نفــرط ولــم نهمــل يف عملنــا بــل نزلنــا‬\n‫ســوي ًا لتغذيــة صــراف مبجمــع الراشــد بعدمــا أغلقنــا الســيارة التــي‬\n‫يوجــد بداخلهــا مفتــاح الصنــدوق اخللفــي للســيارة واملوجــود بــه املبالــغ‬\n‫املاليــة ولــم تكــن ترافقنــا وقــت نزولنــا للصــراف أي دوريــة تابعــة‬\n‫للشــرطة حيــث لــم نطلــب ذلــك ولــم ترافقنــا أي ســيارة أمــن مدنيــة حيــث‬\n‫لــم تؤمــن لنــا الشــركة ذلــك وأثنــاء نزولنــا حصــل االعتــداء على الســيارة‬\n‫وســرقة املبالــغ املشــار إليهــا بالدعــوى مــن الســيارة علم ـ ًا أننــي أصــادق‬\n‫على است ــام املبال ــغ املشـ ــار إليهـ ــا بدع ــوى املدعي ويشاركني يف ذلك‬\n‫زميلــي املدعــى عليــه ‪ /‬ولســماع جــواب املدعــى عليــه اآلخــر فقــد رفعــت‬\n‫اجللســة ‪ ،‬ويف جلســة أخــرى حضــر ‪ /‬ســعودي بالســجل املدنــي رقــم‬\n‫بالوكالــة عــن ‪ /‬ســعودي بالســجل املدنــي رقــم أصالــة عــن نفســه‬\n‫ومبوجــب وكالتــه عــن ‪ /‬وهمــا أصحــاب شــركة ‪ ....‬ملعــدات األمــن‬\n‫والســامة والتجــارة احملــدودة وذلــك كلــه مبوجــب الوكالــة الصــادرة‬\n‫مــن مســاعد رئيــس كتابــة عــدل اخلبــر الثانيــة برقــم ‪ 1187‬يف‬\n‫‪1429/1/11‬ه ـ جلــد ‪ 1670‬وهــذه الوكالــة تخــول الوكيــل حــق‬\n‫املرافعــة وحضــر حلضــوره املدعــى عليــه ‪ /‬و املدعــى عليــه وكالــة ‪ /‬ثــم‬\n\n\n                                                                                       ‫‪66‬‬\n\f     ‫طلبــت مــن املدعــى عليــه وكالــة اجلــواب على الدعوى فقــال‪ :‬إن موكلي‬\n     ‫‪ ....‬غيــر مســتعد بدفــع أي شــيء مــن املبلــغ املدعــى بــه حيــث لــم يصــدر‬\n     ‫مــن موكلــي أي فعــل يوجــب ذلــك ومهمــة موكلــي مــع املدعــى عليــه‬\n     ‫اآلخــر ‪ /‬وشــخص آخــر حيــث أن مهمــة موكلــي تنحصــر يف فتــح اخلزنــة‬\n     ‫املوجــودة بالصرافــات وإغالقهــا وإعــادة اخلدمــة مــرة أخرهــا إليهــا‬\n     ‫وإصــاح الصرافــات إذا وجــد بهــا أي خلــل حيــث إنــه فنــي يف ذلــك علمـ ًا‬\n     ‫أن موكلــي وقــع عنــد البنــك باســتالم مبلــغ مــن البنــك قــدره ثالثــة‬\n     ‫ماليــن وســبعمائة ألــف ريــال هكــذا أجــاب ثــم قــدم لــي جواب ـ ًا خطي ـ ًا‬\n     ‫من ســبع صفحات ومرفق به تســع وعشــرون لفة مت إرفاق ذلك باملعاملة‬\n     ‫األساســية وبعــرض جــواب املدعــى عليهمــا علــى املدعــي وكالــة قــال‪:‬‬\n     ‫إننــي أطلــب مهلــة إلعــداد جــواب علــى ذلــك فأجيــب لطلبــه ‪ ،‬ويف جلســة‬\n     ‫أخــرى حضــر املدعــي وكالــة واملدعــى عليــه أصالــة واملدعــى عليــه‬\n     ‫وكالــة هــذا وقــد عرضــت علــى املدعــي وكالــة جــواب املدعــى عليهمــا‬\n     ‫وطلبــت منــه اجلــواب فقــدم لــي املدعــي وكالــة مذكــرة مــن أربــع‬\n     ‫صفحــات مرفــق بهــا ثــاث لفــات وقــد تضمنــت املذكــرة تأكيــد مــا‬\n     ‫ورد بالدعــوى ومت إرفاقهــا باملعاملــة األساســية ثــم طلـ ــبت مـ ــن املدع ــي‬\n     ‫وكال ــة البينــة علــى دعــواه فقــال‪ :‬إقــرار املدعــى عليهمــا باســتالم املبلــغ‬\n     ‫املدعــى بــه وإقرارهمـ ــا بفقـ ــده وهــذا يوجــب حتملهمــا هــذا املبلــغ بنــاء‬\n     ‫علــى إقــرار املدعــى عليهمــا أمــام الشــركة موكلتــي خطيـ ًا لتحملهمــا‬\n     ‫اختــاس أو ســرقة أو ضيــاع أي مبلــغ مــن املبالــغ املســلمة لهمــا حيــث‬\n     ‫جــاء بإقــرار كل واحــد منهمــا اخلطــي لــدى الشــركة املدعيــة مــا‬\n     ‫نصه(أقــر مبوافقتــي علــى حتمــل أي اختــاس أو ســرقة أو ضيــاع أي‬\n     ‫مبلــغ مــن املبالــغ املســلمة لــي وذلــك بســداد للشــركة أو البنــك مــن‬\n\n\n‫‪67‬‬\n\f‫حســابي اخلــاص دون اعتــراض يف مــدة ال تتجــاوز رقمــا (‪ 24‬ســاعه) وأن‬\n‫مســؤوليتي هــذه ال تنتهــي بتــرك العمــل لديهــا أو إقالتــي بــل تضــل ســارية‬\n‫املفعــول لــكل املهــام والعمليــات التــي كلفتنــي الشــركة بهــا أثنــاء‬\n‫عملــي لديهــا) انتهــى نــص احلاجــة مــن اإلقــرار كمــا قــدم لــي املدعــي‬\n‫وكالــة صــورة خطــاب صــادر مــن مســاعد مدير عام مجموعــة العمليات‬\n‫املركزيــة بالبنــك ‪ ....‬الوطنــي موجــه ملجموعــة ‪ ....‬برقــم ع م‪08/067/‬‬\n‫يف ‪2010/11/10‬م وقــد جــاء يف اخلطــاب مــا نصــه نعلمكــم أنــه حصلت‬\n‫عمليــة اختــاس مــن صرافاتنــا يف املنطقــة الشــرقية يف تاريــخ‬\n‫‪ 2008/8/13‬م والتــي بعهــدة كل مــن والســيد وبإجمالــي رقمــا‬\n‫‪ 1077060‬كتابــة مليــون وســبعة وســبعني ألفــا وســتني ريــا ًال حســب‬\n‫التالــي‪ /1:‬صــراف رقــم ‪ 3272‬مببلــغ ‪ 550.000‬ريــال ‪/2‬صــراف رقــم‬\n‫‪ 3111‬مببلــغ ‪ 351.800‬ريــال ‪ /3‬صــراف رقــم ‪ 311a‬مببلــغ‬\n‫‪175.260‬ريــال لــذا فأنــه وعلــى حســب االتفاقيــة املوقعــة بيننــا فإنــه قــد‬\n‫مت تغطيــة مبلــغ الفروقــات وخصمهــا مــن مســتحقاتكم الشــهرية‪ .‬انتهــى‬\n‫كمــا أنــه كان مــع املدعــى عليهمــا شــخص ثالــث متــدرب واملتعــن‬\n‫علــى الشــخص الثالــث بقــاءه بالســيارة أثنــاء نــزول املدعــى عليهمــا‬\n‫لتغذيــة الصرافــات إال أنــه نــزل مــن الســيارة وهــذا يعــد تفريط ـ ًا مــن‬\n‫املدعى عليهما علم ًا أن الشــخص الثالث ‪ /‬املتدرب ال يتحمل مســؤولية‬\n‫أي شــيء يتعلــق باملبالــغ املوجــودة يف الســيارة هكــذا أجــاب ولعــرض‬\n‫ذلــك علــى املدعــى عليهمــا فقــد رفعــت اجللســة ‪ ،‬ويف جلســة أخرى حضر‬\n‫املدعــي وكالــة واملدعــى عليهمــا أصالــة ووكالــة ثــم قــال املدعــى عليــه‬\n‫وكالــة‪ :‬إننــي أطلــب بــأن يضــاف إلــى جوابــي عــن موكلــي بــأن ضمــان‬\n‫املــال املدعــى بــه علــى مــن يتحمــل مســؤولية حيــازة املــال ومفتــاح اخلزنــة‬\n\n\n                                                                                       ‫‪68‬‬\n\f     ‫وهــو املدعــى عليــه هكــذا أضــاف وبعــرض اإلقــرار املــدون نصــه يف‬\n     ‫اجللســة املاضيــة علــى املدعــى عليهمــا أجــاب املدعــى عليــه بقولــه‪ :‬إن‬\n     ‫هــذا اإلقــرار صــادر منــي إال أن مــا ورد بالدعــوى غيــر صحيــح كمــا‬\n     ‫ذكــرت يف جوابــي وأن هــذا االختــاس تتحملــه الشــركة لتفريطهــا يف‬\n     ‫حمايــة املــال حيــث لــم توفــر الشــركة لنــا أي دوريــة حلراســة املــال وقــد‬\n     ‫تبــن للمحقــق يف القضيــة أنــه ميكــن نســخ مفاتيــح أخــرى للخزنــة‬\n     ‫والســيارة التــي أخــذ منهــا املــال قــد عمــل بهــا مجموعــة كبيــرة مــن‬\n     ‫املوظفــن كمــا أن الشــركة تســاهلت يف توفيــر قائــد للســيارة فقــد‬\n     ‫كان القائــد غائب ـ ًا وتولــى القيــادة ‪ ....‬الــذي هــو املشــرف األول وكان‬\n     ‫يقــود الســيارة التــي بداخلهــا مفتــاح اخلزنــة والتعليمــات املوجهــة إلــي مــن‬\n     ‫الشــركة أن أقــوم بتنفيــذ جميــع تعليمــات املشــرف األول لــذا كلــه‬\n     ‫فإنــي ال أحتمــل ضمــان ســرقة هــذا املبلــغ لعدم تســببي يف ذلك ولتســاهل‬\n     ‫الشــركة كمــا ذكــرت وممــا يؤكــد ذلــك تكــرر هــذه احلادثــة خمــس‬\n     ‫مــرات تقريب ـ ًا خــال ســنتني أو ثــاث ســنوات هكــذا أجــاب كمــا‬\n     ‫أجــاب املدعــى عليــه وكالــة بقولــه‪ :‬هــذا اإلقــرار قــد صــدر مــن موكلــي‬\n     ‫إال أنــه ال يوجــب حتمــل موكلــي للمبلــغ املدعــى بــه ألن املــال ليــس بيــده‬\n     ‫ومــا ذكــره املدعــى عليــه م ــن أن موكل ــي ‪ ....‬قـ ــام بقي ــادة الســيارة وقــد‬\n     ‫ـاء علــى‬\n            ‫مت ذلــك بطلــب ومــا ذكــره املدعــى عليــه مــن أنــه يتصــرف بنـ ً‬\n     ‫توجيــه موكلــي كونــه املشــرف األول فهــذا غيــر صحيــح فلــكل واحــد‬\n     ‫مســؤوليات يتحملهــا هكــذا أجــاب ‪ ،‬ثــم ســألت املدعــى عليــه وكالــة‬\n     ‫‪ /‬هــل اشــترك موكلــك يف اســتالم املبلــغ املدعــى بــه مــع املدعــى عليــه‬\n     ‫اآلخــر فقــال‪ :‬نعــم إال أن موكلــي يتهــم املدعــى عليــه يف االســتيالء علــى‬\n     ‫املبلــغ املدعــى بــه حيــث مت جمــع كامــل هــذا املبلــغ يف كيــس واحــد ومت‬\n\n\n‫‪69‬‬\n\f‫تصريفــه مــن الســيارة وال يعلــم موكلــي كيــف مت تصريــف أو اختفــاء‬\n‫هــذا املبلــغ ويؤكــد هــذا الــكالم وقائــع عــدة وبيانهــا علــى النحــو‬\n‫التالــي‪ -1 :‬أن املدعــى عليــه واملتــدرب ‪ ....‬أخــذا قــراءة الصرافــات التــي‬\n‫ســيقومون بتغذيتهــا أو يأخــذون منهــا الرجيــع أو إيداعــات الزبائــن أخــذا‬\n‫قــراءة تلــك الصرافــات عــن طريــق هاتــف الشــقة التــي يســكنها‬\n‫واملتــدرب وهــذا يخالــف العمــل املعتــاد حيــث إن املعتــاد أن يتــم قــراءة‬\n‫الصرافــات عــن طريــق البنــك بحضــور موكلــي ‪ -2‬اســتلم موكلــي‬\n‫واملدعــى عليــه األمــوال التــي ســيغذى بهــا الصرافــات وعددهــا ســت ثــم‬\n‫أنــزل األكيــاس مــن البنــك وقامــا بتخزينهــا بالســيارة بــدون حضــور‬\n‫موكلــي حيــث تأخــر لتوقيــع أوراق االســتالم لــدى وشــخص ثانــي اســمه‬\n‫‪ -3‬بعــد اســتالم مبلـ ٍـغ مالي ـ ًا مــن صــراف البنــك ‪ .....‬فــرع الثقبــة شــارع‬\n‫مكــة ومقــدار املبلــغ خمســمائة وســبعة وعشــرون ألف ـ ًا وســتون ريــا ًال‬\n‫خــرج كل مــن‪ :‬فجــأة مــن غرفــة الصــراف املكيفــة إلــى الشــارع وكان‬\n‫اجلــو حــار ًا جــد ًا ممــا أثــار الريبــة لــدى موكلــي وعندمــا ركــب الســيارة‬\n‫لــم يجــد بالســيارة وبعــد نصــف دقيقــة تقريب ـ ًا حضــر فســأله نــادر عــن‬\n‫ســبب التأخــر فقــال‪ :‬كنــت أرتــب األكيــاس حتــى يســهل تنزيلهــا عنــد‬\n‫كل جهــاز ‪ -4‬عنــد تغذيــة صرافــن مبجمــع الراشــد للبنــك ‪ ....‬األول‬\n‫رقمــه ‪ 5‬والثانــي ‪ 3‬اختفــى عــن موكلــي مــدة عشــرين دقيقــة حيــث‬\n‫كان موكلــي يقــوم بإصــاح عطــل فنــي بالصــراف رقــم ‪ 3‬وعندمــا‬\n‫ســئل عــن تغيبــه خــال هــذه الفتــرة أفــاد بأنــه كان يتجــول يف مطاعــم‬\n‫املجمــع ‪ -5‬أن الــذي قــام بإخبــار بالســرقة هــو املدعــى عليــه لــذا فــإن‬\n‫موكلــي ال يتحمــل أي تفريــط وأن الــذي تســبب يف اختفــاء هــذا املبلــغ‬\n‫هكــذا أجــاب وبعــرض ذلــك علــى ‪ /‬قــال‪ :‬مــا ذكــره املدعــى عليــه‬\n\n\n                                                                                       ‫‪70‬‬\n\f     ‫ا فأنــا لــم أتســبب ولــم أشــارك يف‬    ‫وكالــة غيــر صحيــح جملــة وتفصي ـ ً‬\n     ‫اختفــاء أي شــيء ممــا ورد بالدعــوى وأجيــب علــى مــا ذكــره املدعــى‬\n     ‫عليــه وكالــة بشــأن أخــذ قــراءة الصرافــات مــن الشــقة فهــذا صحيــح إال‬\n     ‫أنــه أمــر متكــرر وبعلــم وأمــر املدعــى عليــه وذلــك لكثــرة مــن يقــوم‬\n     ‫بقــراءة الصرافــات بالبنــك مــن موظفــي الشــركة كمــا أن القــراءة‬\n     ‫تكــون جلميــع الصرافــات بــدون حتديــد صــراف معــن والبنــك يوجهنــا‬\n     ‫للصرافــات املطلــوب تغذيتهــا أو الســحب منهــا بــدون أي علــم ســابق منــا‬\n     ‫ومــا ذكــره املدعــى عليــه وكالــة يف الفقــرة رقــم ‪ 2‬غيــر صحيــح جملــة‬\n     ‫ا فقــد اســتلمنا أنــا و‪ .....‬األكيــاس مــن البنــك وقمنــا بإنزالهــا‬   ‫وتفصي ـ ً‬\n     ‫باالشــتراك مــع ‪ /‬ثــم قمنــا بتنزيلهــا مــن الســيارة وممــا يكــذب مــا‬\n     ‫ذكــره املدعــى عليــه أن مفتــاح الســيارة كان مــع موكلــه ‪ ....‬ومــا‬\n     ‫ذكــره املدعــى عليــه يف الفقــرة رقــم ‪ 3‬غيــر صحيــح أيض ـ ًا فقــد كان‬\n     ‫خروجــي مــن الصــراف أنــا و‪ .....‬سوي ـ ًا ث ــم ركـ ــب السيـ ــارة لقيادتها وأنا‬\n     ‫قمــت بوضــع صنــدوق الرجيــع وكيــس بــه مبلــغ مالــي ومــا ذكــره‬\n     ‫املدعــى عليــه وكالــة يف الفقــرة رقــم ‪ 5‬فغيــر صحيــح والصحيــح أننــي‬\n     ‫فتحــت اخلزنــة واســتنكرت عــدم وجــود صنــدوق رجيــع اإليــداع فســألت‬\n     ‫‪ ....‬عــن ذلــك وحتقــق مــن ذلــك كمــا اســتنكر ‪ ....‬فقــدان عــدد مــن‬\n     ‫األكيــاس فتــم إبــاغ الشــركة عــن طريــق‪ /‬لــذا فإنــي أنكــر اتهــام‬\n     ‫ـاء علــى مــا‬\n                 ‫املدعــى عليــه لــي بأخــذ أي شــيء مــن املبلــغ املدعــى بــه وبنـ ً‬\n     ‫ـاء علــى مــا نصــت عليــه املــادة ‪ 76‬مــن نظــام‬   ‫ذكــره املدعــى عليــه وبنـ ً‬\n     ‫املرافعــات الشــرعية فقــد قــررت إدخــال املدعــى عليــه‪ /‬ويف جلســة‬\n     ‫أخــرى حضــر املدعــي وكالــة ‪ /‬ســعودي بالســجل املدنــي رقــم بالوكالة‬\n     ‫عــن ‪ /‬ســعودي بالســجل املدنــي رقــم بصفتــه شــريك يف شــركة ‪....‬‬\n\n\n‫‪71‬‬\n\f‫ملعــدات األمــن والســامة والتجــارة احملــدودة حســب الوكالــة املشــار‬\n‫إلــى مصدرهــا ورقمهــا وتاريخهــا يف اجللســة املاضيــة وحضــر حلضــوره‬\n‫املدعــى عليهمــا أصالــة و‪ /‬ســعودي بالســجل املدنــي رقــم كمــا حضــر‬\n‫املدخــل ‪ /‬ســعودي بالســجل املدنــي رقــم ثــم عرضــت علــى املدعــى عليــه‬\n‫أصالـ ــة جميــع اإلجابــات التــي أدلــى بهــا وكيلــه يف اجللســات املاضيــة‬\n‫جميعهــا فقــال‪ :‬إننــي أصــادق علــى كل مــا أجــاب بــه وكيلــي املذكــور‬\n‫هكــذا أجــاب ثــم عرضــت علــى املدخــل ‪ ....‬مــا ذكــره وكيــل املدعــى‬\n‫عليــه يف اجللســة املاضيــة فقــال‪ :‬مــا ذكــره وكيــل املدعــى عليــه غيــر‬\n‫صحيــح فأنــا لــم أســتولي علــى املبلــغ املدعــى بــه ولــم أشــارك يف إخفائــه‬\n‫ـدي أي علــم بذلــك وأنــا كنــت متدربـ ًا أعمــل مــع املدعــى عليهمــا‬  ‫وليــس لـ ّ‬\n‫واســتمر عملــي مــع الشــركة املدعيــة مــدة ال تزيــد عــن شــهر ومــا ذكــره‬\n‫وكيــل املدعــى عليــه مــن وقائــع اســتند علــى دعــواه فيهــا فــكل مــا جــاء‬\n‫يف هــذه الوقائــع غيــر صحيــح هكــذا أجــاب ثــم ســألت املدعــى عليــه ‪:...‬‬\n‫هــل لديــه زيــادة بينــة علــى مــا ذكــره وكيلــه مــن مشــاركة املدخــل ‪....‬‬\n‫مــع املدعــى عليــه يف إخفــاء املبلــغ املدعــى بــه واالســتيالء عليــه فقــال‪ :‬ال‬\n‫ثــم أفهمــت املدعــى عليــه نــادر النزغــة بــأن لــه ميــن املدخــل اآلتــي نصهــا‪:‬‬\n‫( واهلل الــذي ال إلــه إال هــو احلــي القيــوم بأننــي لــم أســتولي علــى املبلــغ‬\n‫املدعــى بــه مــن قبــل شــركة ‪ ....‬ملعــدات األمــن والســامة والتجــارة‬\n‫احملــدودة وقــدره مليــون وســبعة وســبعون ألفـ ًا وســتون ريــا ًال ولــم أشــارك‬\n‫ـدي أي علــم بذلــك واهلل العظيــم ) انتهــى‬   ‫يف إخفــاء هــذا املبلــغ وليــس لـ ّ‬\n‫نــص اليمــن ‪ ،‬وبعــرض هــذا اليمــن وهــذا النــص علــى املدعــى عليــه‬\n‫فقــال‪ :‬إننــي أطلــب مــن املدخــل أن يــؤدي هــذه اليمــن ثــم حلــف ‪ ....‬بنــص‬\n‫اليمــن املــدون بعاليــه ثــم جــرى منــي االطــاع علــى القــرار الشــرعي‬\n\n\n                                                                                         ‫‪72‬‬\n\f     ‫الصــادر مــن فضيلــة القاضــي باحملكمــة اجلزئيــة باخلبــر الشــيخ ‪ /‬برقــم‬\n     ‫‪ 4/74‬وتاريــخ ‪1430/3/17‬ه ـ وهــو يتضمــن إقامــة دعــوى مــن املدعــي‬\n     ‫العــام ضــد كل مــن‪ .... :‬و‪ ....‬التهامهمــا بخيانــة األمانــة واالســتيالء علــى‬\n     ‫مبلــغ قــدره مليــون وســبعون ألــف ريــال ســعودي تعــود للبنــك ‪ ....‬بعــد‬\n     ‫اســتالمها مــن البنــك لغــرض تغذيــة الصرافــات ومــا جــاء يف احلكــم مــا‬\n     ‫ـاء عليــه فــإن املدعــى عليهمــا يدانــان بالتفريــط لألســباب‬      ‫نصــه‪ ( :‬وبنـ ً‬\n     ‫املذكــورة آنف ـ ًا وتتوجــه عليهمــا التهمــة باالختــاس وقــررت تعزيرهمــا‬\n     ‫لقــاء ذلــك بجلــد كل واحــد منهمــا مائتــي جلــدة موزعــة علــى خمــس‬\n     ‫دفعــات كل دفعــة أربعــن جلــدة بــن كل دفعــة وأخــرى عشــرة أيــام‬\n     ‫وســجن كل واحــد منهمــا ســنة كاملــة مــن تأريــخ دخولــه الســجن‬\n     ‫وبذلــك حكمــت) وهــذا احلكــم قــد اكتســب القطعية بقــرار محكمة‬\n     ‫ـاء‬\n     ‫االســتئناف بالريــاض رقــم ‪/551‬ج‪/5‬أ وتأريــخ ‪1431/3/28‬ه ـ فبنـ ً‬\n     ‫علــى مــا تقــدم مــن الدعــوى وإجابــة املدعــى عليهمــا باســتالم املبلــغ‬\n     ‫املدعــى بــه وإنكارهمــا أخــذ أي شــيء منــه وأنهمــا لــم يفرطــا يف حفظــه‬\n     ‫ومبــا أن املدعــى عليــه ‪ ...‬اتهــم املدعــى عليــه ‪ ....‬باالســتيالء علــى املبلــغ‬\n     ‫املدعــى بــه وإخفائــه وقــد أنكــر املذكــوران ذلــك بعــد إدخــال ‪ ....‬يف‬\n     ‫هــذه الدعــوى ومــا قدمــه املدعــى عليــه ال يرتقــي إلثبــات هــذا الدفــع وقــد‬\n     ‫ـاء علــى‬\n             ‫أدى املدخــل اليمــن الشــرعية الالزمــة علــى نفــي هــذا الدفــع بنـ ً‬\n     ‫طلــب املدعــى عليــه ‪ ....‬ومبــا أن املدعــى عليهمــا يعتبــران أجــراء خاصــن‬\n     ‫واألجيــر اخلــاص ال يضمــن إال يف حــال التعــدي أو التفريــط تنظــر هــذه‬\n     ‫املســألة يف الــروض املربــع لإلمــام البهوتــي مــع حاشــية بــن قاســم رحمهــم‬\n     ‫اهلل ج‪ 5‬صــ‪ 336‬ومــا بعدهــا ومبــا أن املدعــى عليهمــا قــد أدينــا بالتفريــط‬\n     ‫مبوجــب القــرار الشــرعي املشــار إليــه بعاليــه ومبــا أن البنــك ‪ ....‬قــد‬\n\n\n‫‪73‬‬\n\f‫اســتوفى املبلــغ املدعــى بــه مــن الشــركة املدعيــة لــذا كلــه فقــد صرفــت‬\n‫ـدي أن بذمــة كل‬  ‫النظــر عــن الدعــوى ضــد املدخــل لعــدم ثبوتهــا وثبــت لـ ّ‬\n‫مــن‪ .... :‬لشــركة ‪ ....‬ملعــدات األمــن والســامة والتجــارة احملــدودة مبلغـ ًا‬\n‫قــدره مليــون وســبعة وســبعون ألفـ ًا وســتون ريــا ًال وألزمــت املدعــى عليهمــا‬\n‫بدفــع كامــل هــذا املبلــغ للشــركة املدعيــة متضامنــن فيــه وبذلــك‬\n‫كلــه حكمــت وبعــرض احلكــم علــى املدعــى عليهمــا واملدخــل قــرر‬\n‫املدخــل القناعــة بــه أمــا املدعــى عليهمــا فقــررا عــدم القناعــة وطلبــا رفعه‬\n‫حملكمــة االســتئناف بالئحــة اعتراضيــة فجــرى إفهامهمــا بتعليمــات‬\n‫االســتئناف حســبما دون بالضبــط ففهمــا ذلــك وعليــه جــرى التوقيــع‬\n‫حــرر يف ‪1433/4/14‬ه ـ وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                             ‫وسلم‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫باملنطقــة الشــرقية بخطــاب معالــي رئيســها رقــم ‪ 33/1112283‬وتأريــخ‬\n‫‪1433/7/2‬ه ـ وبرفقــه قــرار أصحــاب الفضيلــة قضــاة الدائــرة احلقوقيــة‬\n‫الثانيــة رقــم ‪ 33317225‬وتأريــخ ‪1433/6/28‬ه ـ والــذي جــاء فيــه مــا‬\n‫نصــه‪( :‬وبدراســة الصــك وصــورة ضبطــه وثــاث لوائــح اعتراضيــة‬\n‫وأوراق املعاملــة لوحــظ أن املدعــي بالوكالــة لــم يحــرر دعــواه بإيضــاح‬\n‫مــا علــى كل واحــد مــن املدعــى عليهمــا مــن املبلــغ املدعــى بــه كمــا‬\n‫أن فضيلــة القاضــي لــم يوضــح يف حكمــه مــا علــى كل واحــد مــن‬\n‫املدعــى عليهمــا مــن املبلــغ احملكــوم بــه وال بــد مــن ذلــك فعلــى فضيلــة‬\n‫القاضــي مالحظــة مــا ذكــر وإكمــال مــا يلــزم نحــوه بحضــور الطرفــن‬\n‫) انتهــى بنصــه ‪ ،‬عليــه فقــد مت حتديــد هــذا اليــوم األربعــاء املوافــق‬\n‫‪1433/11/3‬ه ـ الســاعة الثامنــة والنصــف موعــد ًا إلكمــال مــا ورد‬\n\n\n                                                                                       ‫‪74‬‬\n\f     ‫بقــرار أصحــاب الفضيلــة وحضــر يف هــذه اجللســة املدعــي وكالــة ‪/‬‬\n     ‫واملدعــى عليــه أصالــة ‪ /‬واملدعــى عليــه وكالــة ‪ /‬ثــم ســألت املدعــي‬\n     ‫وكالــة عمــا أشــار إليــه أصحــاب الفضيلــة بشــأن حتريــر الدعــوى‬\n     ‫فقــال‪ :‬إن الشــركة موكلتــي تطالــب كل واحــد مــن املدعــى عليهمــا‬\n     ‫بالتضامــن يف حتمــل املبلــغ املدعــى بــه وقــدره مليــون وســبعة وســبعون‬\n     ‫ألفـ ًا وســتون ريــا ًال كمــا ذكــر املدعــي وكالــة الســابق واملقصــد بذلــك‬\n     ‫أن يتحمــل كل واحــد مــن املدعــى عليهمــا نصــف املبلــغ املدعــى بــه‬\n     ‫ومقــدار النصــف خمســمائة وثمانيــة وثالثــون ألفـ ًا وخمســمائة وثالثــون‬\n     ‫ريــا ًال هكــذا أجــاب أمــا جوابــي علــى مــا ذكــره أصحــاب الفضيلــة‬\n     ‫مــن أننــي لــم أوضــح مــا علــى كل واحــد مــن املدعــى عليهمــا مــن املبلــغ‬\n     ‫احملكــوم بــه فأجيــب علــى ذلــك أننــي ذكــرت يف حكمــي مــا نصــه‪:‬‬\n     ‫( وألزمــت املدعــى عليهمــا بدفــع كامــل هــذا املبلــغ للشــركة املدعيــة‬\n     ‫متضامنــن ) أي أن كل واحــد منهمــا يتحمــل نصــف هــذا املبلــغ‬\n     ‫ومقــداره خمســمائة وثمانيــة وثالثــون ألف ـ ًا وخمســمائة وثالثــون ريــا ًال‬\n     ‫وللشــركة املدعيــة مطالبــة أحدهمــا بكامــل املبلــغ احملكــوم بــه ولــه‬\n     ‫الرجــوع علــى صاحبــه بســداد مــا دفعــه للشــركة ومســتندي يف ذلــك مــا‬\n     ‫ذكرتــه يف أســباب احلكــم مــن أن املدعــى عليهمــا أجــراء خاصــن وقــد‬\n     ‫ثبــت تفريطهمــا مبوجــب القــرار الشــرعي املــدون نــص احلاجــة منــه فيمــا‬\n     ‫مضــى ولقــول النبــي صلــى اهلل عليــه وآلــه وســلم‪ ( :‬علــى اليــد مــا أخــذت‬\n     ‫حتــى تؤديــه ) رواه أحمــد واألربعــة وصححــه احلاكــم لــذا فإنــي ال أزال‬\n     ‫علــى حكمــي الســابق كمــا ســيجري تصحيــح األخطــاء اإلمالئيــة‬\n     ‫التــي أشــار إليهــا أصحــاب الفضيلــة بصكــي الســابق وســيجري إحلــاق‬\n     ‫ذلــك بالصــك وســجله ثــم إعــادة املعاملــة حملكمــة االســتئناف باملنطقــة‬\n\n\n‫‪75‬‬\n\f‫الشــرقية لتدقيــق مــا مت إحلاقــه وأســأل اهلل تعالــى أن يجــزي أصحــاب‬\n‫الفضيلــة خيــر ًا علــى مــا بذلــوه مــن جهــد يف تدقيــق هــذه القضيــة وبــاهلل‬\n‫التوفيــق حــرر يف ‪1433/11/3‬ه ـ وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                               ‫وصحبــه وســلم ‪.‬‬\n\n\n‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 3410902‬وتاريــخ‬\n                                               ‫‪1434/1/13‬هــ‪.‬‬\n\n\n\n\n                                                                                      ‫‪76‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":63,"source_page_end":76,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d4ee9508264de3bbe16e42a023a172d78e215a17e99ee33dfe04c0c9fa96cb46","normalized_text_hash":"98dffcfa36f0ef5d8481c2aef6c976cd1da9a6e1cb6ebe3e92452997794c8696","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p63-33192872"},{"id":"645f6f02-6d8f-59b7-8779-e5cdd0bfc39e","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة مبلغ مالي عن طريق تزوير شيك -إقرار املدعى عليه بحيازته أدوات تزوير -العثور على صورة الشيك املدعى به املزور عند املدعى عليه -إثبات بالقرائن -إلزام املدعى عليه بدفع قيمة الشيك املدعى به .","document_number":"33324572","case_number":"3267874","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/2","year":"1434","subject":"رد مسروق -سرقة مبلغ مالي عن طريق تزوير شيك -إقرار املدعى عليه بحيازته أدوات تزوير -العثور على صورة الشيك املدعى به املزور عند املدعى عليه -إثبات بالقرائن -إلزام املدعى عليه بدفع قيمة الشيك املدعى به .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/7/2 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪33324572 :‬‬\n                          ‫َر ْق ُم الدعوى‪3267874:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34240282‬تاريخه‪1434/6/13:‬هـ‬\n\n\n     ‫رد مســروق ‪ -‬ســرقة مبلــغ مالــي عــن طريــق تزويــر شــيك ‪ -‬إقرار املدعى‬\n     ‫عليــه بحيازتــه أدوات تزويــر‪ -‬العثــور علــى صــورة الشــيك املدعــى بــه‬\n     ‫املــزور عنــد املدعــى عليــه‪ -‬إثبــات بالقرائــن ‪ -‬إلــزام املدعــى عليــه بدفــع‬\n                                                       ‫قيمــة الشــيك املدعــى بــه ‪.‬‬\n\n\n\n\n     ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                              ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n     ‫ادعــى وكيــل الشــركة املدعيــة بــأن املدعــى عليــه قــام بتزويــر شــيك‬\n     ‫باســم موكلتــه ثــم قــام بصرفــه مــن حســابها املصــريف لصالــح نفســه‬\n     ‫بــدون وجــه حــق ؛ وطلــب إلزامــه بســداد قيمــة الشــيك املذكــور ملوكلتــه‬\n     ‫‪ -‬أنكــر املدعــى عليــه الدعــوى ســوى مــا جــاء فيهــا مــن إدانتــه للحــق‬\n     ‫العــام بالتزويــر‪ -‬املدعيــة قدمــت قرائــن قويــة متعاضــدة جتــاه املدعــى‬\n     ‫عليــه ترقــى لدرجــة اإلثبــات وهــي إدانتــه بتزويــر الشــيك املذكــور‬\n     ‫للحــق العــام وثبــوت حصــول التزويــر علــى الشــيك ووجــود صــورة الشــيك‬\n     ‫مــع وجــود معمــل كامــل للتزويــر يف منزلــه وشــهادة الشــاهد‪ -‬قضــت‬\n     ‫احملكمــة بإلــزام املدعــى عليــه بتســليم املدعيــة قيمــة الشــيك املــزور‬\n\n‫‪77‬‬\n\f‫الــذي قــام بصرفــه لصالــح نفســه ‪ -‬قنعــت املدعيــة باحلكــم وعــارض‬\n‫عليــه املدعــى عليــه ‪ -‬قــررت محكمــة االســتئناف باألكثريــة املصادقــة‬\n                                                         ‫علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪ 3267874‬وتاريــخ ‪ 1432/03/05‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 32150559‬وتاريــخ ‪ 1432/02/20‬ه ـ ففــي يــوم‬\n‫الســبت املوافــق‪ 1433/01/22‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 41‬‬\n‫وفيهــا حضــر ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم بصفتــه‬\n‫ا عــن ‪ ...‬كنــدي اجلنســية مبوجــب رخصــة إقامــة رقــم بصفتــه‬          ‫وكي ـ ً‬\n‫مديــر شــركة ‪ ....‬ألنظمــة احلاســب اآللــي مبوجــب الســجل التجــاري رقــم‬\n‫مبوجــب الوكالــة الصــادرة مــن كاتــب العــدل املكلــف بالهيئــة العامــة‬\n‫لالســتثمار برقــم ‪ 573‬يف ‪1431/5/12‬ه ـ واملخــول لــه فيها بحق املرافعة‬\n‫واملدافعــة واملخاصمــة والصلــح والتنــازل وادعــى علــى احلاضــر معــه‬\n‫ا يف دعــواه‪ :‬إن‬   ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم قائ ـ ً‬\n‫املدعــى عليــه ســبق وأن زور علــى الشــركة موكلتــي الشــيك رقــم ‪......‬‬\n‫يف ‪2009/3/18‬م مســحوب علــى البنــك ‪ ...‬مببلــغ أربعمائــة وخمســة‬\n‫وثمانــن ألــف ريــال لصالــح ‪......‬إذ قــام بتزويــر توقيــع رئيــس الشــركة‬\n‫موكلتــي ورئيــس احملاســبة وقــام املذكــور بصــرف الشــيك بــدون وجــه‬\n‫حــق كمــا أن الشــيك املذكــور مــزور إذ نفــس الرقــم موجــود لــدى‬\n‫الشــركة لــم يتــم حتريــره حتــى تاريخــه وقــد أديــن املدعــى عليــه بديــوان‬\n\n                                                                                    ‫‪78‬‬\n\f     ‫املظالــم بتزويــر الشــيك املذكــور وحكــم عليــه يف احلــق العــام وإننــي‬\n     ‫أطلــب يف دعــواي هــذه ســؤال املدعــى عليــه وإلزامــه بســداد قيمة الشــيك‬\n     ‫املذكــور هــذه دعــواي وبســؤال املدعــى عليــه قــال‪ :‬مــا ذكــره املدعــي‬\n     ‫وكالــة مــن أننــي أدنــت مــن ديــوان املظالــم بتزويــر الشــيك املذكــور‬\n     ‫صحيــح وأمــا بقيــة مــا جــاء يف دعــوى املدعــي وكالــة فغيــر صحيــح فلــم‬\n     ‫أقــم بتزويــر الشــيك املذكــور وال توقيــع املذكوريــن عليــه وال عالقــة‬\n     ‫لــي بذلــك هــذا مــا لــدي وبعــرض ذلــك علــى املدعــي وكالــة قــال‪:‬‬\n     ‫الصحيــح مــا ذكــرت يف دعــواي وبســؤاله هــل لديــه بينــة قــال‪ :‬نعــم‬\n     ‫ومســتعد بإحضارهــا يف اجللســة القادمــة وبنــاء عليــه فقــد مت رفــع اجللســة‬\n     ‫ويف جلســة أخــرى حضــر وكيــل املدعــي املدونــة هويتــه ووكالته ســابقا‬\n     ‫وحضــر املدعــى عليــه املدونــة هويتــه ســابقا وأحضــر املدعــي وكالــة‬\n     ‫معــه للشــهادة وأدائهــا ‪ ...‬ســوري اجلنســية رخصــة إقامــة رقــم وطلــب‬\n     ‫ســماع مــا لديــه وبســؤاله عمــا لديــه قــال أشــهد هلل بــأن املدعــى عليــه‬\n     ‫كان لــي بــه عالقــة صداقــة ويف يــوم مــن األيــام ال أذكــره كان املدعــى‬\n     ‫عليــه يركــب معــي يف ســيارتي وكان الوقــت مســاء ولــم يكــن معنــا‬\n     ‫أحد وقال لي املدعى عليه أنه يرغب يف تزوير شيك إحدى الشركات‬\n     ‫وكان يقنعنــي أن أقــوم بجلــب صــور للشــيكات وهــو يقــوم بعمليــة‬\n     ‫التزويــر فســألته هــل ســبق أن قمــت بتزويــر شــيكات فقــال نعــم وأنــا‬\n     ‫دائمــا أعمــل ذلــك وضــرب لــي مثــا تزويــر شــيك علــى شــركة ‪ ...‬هــذا‬\n     ‫مــا لــدي مــن شــهادة وأشــهد هلل بهــا وبعــرض الشــاهد ومــا جــاء يف‬\n     ‫شــهادته علــى املدعــى عليــه قــال إن الشــاهد كان مدعــى عليــه معــي يف‬\n     ‫نفــس قضيــة التزويــر لــدى ديــوان املظالــم وكل مــا ذكــره غيــر صحيــح‬\n     ‫وأنــا أقــدح يف عدالــة الشــاهد فهــو يســب اهلل أمامــي كثيــرا وليــس لــدي‬\n\n\n‫‪79‬‬\n\f‫بينــة علــى قدحــي هــذا يف عدالتــه والشــاهد يعــرف وعصابتــه الذيــن‬\n‫قامــوا بتزويــر شــيك شــركة ‪ ....‬هــذا مــا لــدي وبعــرض ذلــك علــى‬\n‫الشــاهد قــال مــا ذكــره املدعــى عليــه غيــر صحيــح فأنــا رجــل مســلم‬\n‫وبســؤال املدعــي وكالــة هــل لديــه مزيــد بينــة قــال نعــم وقــد أرســلت‬\n‫لكــم األدلــة مــن شــعبة مكافحــة التزييــف والتزويــر هــذا وقــد وردنــا‬\n‫خطابهــم رقــم ‪/380/19‬ج ‪ 6‬يف ‪1433/2/9‬ه ـ وفــد أرفــق بــه الشــيك‬\n‫األساســي املســحوب علــى البنــك ‪ ....‬رقــم ‪ ......‬كمــا وجــدت أســاس‬\n‫الشــيك املدعــى بتزويــره رقــم ‪ ....‬املســحوب علــى البنــك ‪ ....‬بتاريــخ‬\n‫‪2009/3/18‬م املصــروف مببلــغ أربعمائــة وخمســة وثمانــن ألــف ريــال‬\n‫كمــا وجــدت بــن طياتهــا التقريــر الفنــي رقــم ‪ 32793‬الصــادر مــن إدارة‬\n‫الفحــوص الفنيــة للتزييــف والتزويــر املتضمــن أوال بفحــص الشــيك‬\n‫موضــوع الفحــص باســتخدام األجهــزة املكبــرة وجدنــا أنــه يحمــل‬\n‫العالمــات األمنيــة واخلصائــص الطباعيــة للشــيكات الصحيحــة‬\n‫وتعــرض للتزويــر باحملــو وإعــادة طباعــه للبيانــات احلاليــة عليــه وهــي‬\n‫الرقــم التسلســلي ورقــم احلســاب ورقــم الترميــز الطباعــي لدفتــر‬\n‫الشــيكات واســم الشــركة ثانيــا ملضاهــاة التواقيــع املنســوبة لــكل‬\n‫مــن املدعــو ‪ ......‬واملدعــو ‪ .....‬يلــزم حتقيــق اآلتــي‪ -1 :‬إرســال منــوذج‬\n‫التوقيــع لــدى البنــك ‪ ...‬لنفــس احلســاب املســحوب عليــه الشــيك موضــوع‬\n‫الفحــص ومنــاذج الشــيكات مماثلــة ســبق صرفهــا حتمــل تواقيــع‬\n‫املذكوريــن‪ -2 .‬تكليــف املذكوريــن مبراجعتنــا يف وقــت يتزامــن مــع‬\n‫إرســال أوراق القضيــة ‪.‬أ‪.‬ه ـ وبعرضهــا علــى املدعــى عليــه قــال إننــي لــم‬\n‫أقــم بالتزويــر هــذا مــا لــدي وبســؤال املدعــي وكالــة هــل لديــه زيــادة‬\n‫بينــة قــال نعــم ومســتعد بإحضارهــا يف اجللســة القادمــة وبنــاء عليــه فقــد‬\n\n\n                                                                                    ‫‪80‬‬\n\f     ‫جــرى رفــع اجللســة ويف جلســة أخــرى حضــر املدعــي وكالــة املدونــة‬\n     ‫هويتــه ووكالتــه ســابق ًا واملدعــى عليــه وقــد وردنــا خطــاب مديــر شــعبة‬\n     ‫إصالحيــة احلائــر برقــم ‪ 0044009/11‬تاريــخ ‪1433/3/13‬ه ـ واملرفــق‬\n     ‫بــه املعاملــة املتعلقــة بالتحقيــق يف دعــوى الشــركة املدعيــة واملدعــى‬\n     ‫عليــه وبتصفــح أوراق املعاملــة وجــد بــن طياتهــا علــى لفــة ‪ 52‬محضــر‬\n     ‫انتقــال وتفتيــش يف تاريــخ ‪1431/1/5‬ه ـ والــذي جــاء فيــه بنــاء العتــراف‬\n     ‫املوقــوف هويــة رقــم عــن وجــود ســبائك الذهــب ومبلــغ مالــي بشــقته وأنــه‬\n     ‫قــام بإخفائهــا بطريقــة فنيــة فقــد مت االنتقــال برفقــه بحضورنــا نحــن‬\n     ‫املوقعــن أدنــاه وبالوصــول إلــى شــقته والدخــول اجتــه إلــى املطبــخ وأفــاد‬\n     ‫بــأن الســبائك أخفاهــا بإحــدى الدواليــب بطريقــة فنيــة ممــا اســتلزم‬\n     ‫فتحهــا مبفــك خــاص وبفتــح بقيــة الدواليــب عثــر علــى مجموعــة أختــام‬\n     ‫إلدارات حكوميــة وأختــام ألشــخاص وصــور بطاقــات وصــور شــيكات‬\n     ‫ودفاتر شيكات وأوراق مطبوعات لشركة‪ ...‬وأوراق خالية ملطبوعات‬\n     ‫وزارة العــدل وبلــغ عــدد املضبوطــات خمســة وســتني وليــس مــن ضمنهــا‬\n     ‫مــا يــدل علــى الشــيك محــل الدعــوى كمــا وجدنــا اعترافــه بتاريــخ‬\n     ‫‪1431/1/7‬ه ـ املصــدق مــن هــذه احملكمــة ووجــد يتضمــن إقــراره‬\n     ‫بحيــازة مــا ضبــط معــه يف محضــر القبــض املذكــور وذكــر فيــه أنــه لــم‬\n     ‫يقــم باســتخدام األوراق الفارغــة وإمنــا الــذي قــام بتزويرهــا زميلــه‪ ...‬كما‬\n     ‫ذكــر يف اعترافــه أنــه يوجــد مــن ضمــن املضبوطات مجموعة شــيكات‬\n     ‫مببالــغ ماليــة محــررة ألشــخاص عددهــا خمســة عشــر شــيكا ومنــاذج‬\n     ‫لتواقيــع شــيكات مــزورة كمــا وجــدت علــى محضــر التحقيــق لفــة ‪101‬‬\n     ‫صحيفــة ‪ 18‬جــواب املدعــى عليــه علــى ســؤال احملقــق للمدعــى عليــه عــن‬\n     ‫الشــيك ‪ ......‬يف ‪2009/3/18‬م املنســوب لشــركة ‪ ...‬ألنظمــة احلاســب‬\n\n\n‫‪81‬‬\n\f‫اآللــي فأجــاب قائــا غيــر صحيــح ســلم لــي هــذا مــن قبــل ‪ ...‬وأمــا الشــيك‬\n‫اآلخــر لشــركة ‪ ...‬فأطعــن فيــه ألنــه ضبــط يف منزلــي وان هــذا الــكالم‬\n‫عــاري مــن الصحــة ألنــه لــم يســبق أن أتعامــل معهم وال أعلم عن نشــاطهم‬\n‫فهــي تلفيــق التهمــة ملــن لــه مصلحــة يف إلصــاق التهمــة بــي وبعــرض جميــع‬\n‫مــا تقــدم علــى املدعــى عليــه قــال إن الشــيك املدعــى بــه ال عالقــة لــي بــه‬\n‫ولــم يضبــط بحوزتــي هــذا مــا لــدي فجــرى ســؤال املدعــي هــل لديــه زيادة‬\n‫بينــة فقــال نعــم ومســتعد بإحضارهــا يف اجللســة القادمــة وبنــاء عليــه فقــد‬\n‫قــررت رفــع اجللســة ويف جلســة أخــرى حضــر املدعــي وكالــة واملدعــى‬\n‫عليــه ‪ ...‬وبســؤال املدعــي هــل لديــه زيــادة بينــة قــال نعــم أننــي راجعــت‬\n‫قســم التزييــف والتزويــر وأفادنــي الضابــط املســئول أنــه يوجــد لديهــم‬\n‫محضــر يثبــت قيــام املدعــى عليــه بتزويــر الشــيك محــل الدعــوى وأطلــب‬\n‫الكتابــة لهــم لبيــان ذلــك هــذا مــا لــدي وبنــاء عليــه فقــد قــررت الكتابــة‬\n‫إلــى قســم التزويــر والتزييــف باألدلــة اجلنائيــة لإلفــادة عمــا ذكــره‬\n‫املدعــي وكالــة وبــه رفعــت اجللســة ويف جلســة أخــرى حضــر املــدون‬\n‫هويتــه ووكالتــه ســابقا وحضــر حلضــوره ‪ ...‬واملــدون هويتــه ســابقا‬\n‫وباالطــاع علــى املعاملــة وجــد بــن طياتهــا علــى لفــة ‪ 66‬محضــر انتقــال‬\n‫وتفتيــش إحلاقــي بتاريــخ ‪1431/1/5‬ه ـ جــاء فيــه بنــاء العتــراف املوقــوف‬\n‫‪ 40‬ســنة بهويــة رقــم عــن وجــود ســبائك الذهــب ومبلــغ مالــي بشــقته وأنــه‬\n‫قــام بإخفائهــا بطريقــة فنيــه فقــد مت االنتقــال رفــق الســجني وبحضورنــا‬\n‫نحــن املوقعــن أدنــاه وبالوصــول إلــى شــقته الواقعــة بحــي ‪ ...‬شــمال ‪...‬‬\n‫بشــارع ‪ ...‬والدخول اجته الســجني ومت إرشــادنا إلى مطبخ الشــقة وأفاد‬\n‫بــأن الســبائك أخفاهــا بإحــدى الدواليــب الســفلية للمطبــخ بطريقــة فنيــه‬\n‫مــن مــا اســتلزم فتحهــا مبفــك خــاص وبفتــح الدواليــب عثــر علــى مــا دون‬\n\n\n                                                                                        ‫‪82‬‬\n\f     ‫مبحضــر االنتقــال والتفتيــش وعددهــا ‪ 56‬ضبطيــه كمــا عثــر علــى‬\n     ‫شــيك مببلــغ أربعمائــة وخمســة وثمانــون ألــف ريــال مجيــر باســم املدعــو‬\n     ‫علــى البنــك ‪ ...‬فــرع ‪ ...‬علمــا أن جميــع مــا ضبــط داخــل الشــقة عثــر عليهــا‬\n     ‫يف األدراج الســفلية ملطبــخ الشــقة وضعــت داخــل أوعيــة بالســتيكية‬\n     ‫مفتوحــة ومت إخفائهــا يف أســفل الديكــور للمطبــخ هــذا وقــد مت‬\n     ‫اســتدعاء املصــور اجلنائــي باألدلــة اجلنائيــة وتصويــر املوقــع وحفظــا‬\n     ‫للواقــع جــرى حتريــر هــذا احملضــر نقيــب توقيــع نقيــب رئيــس رقبــاء‬\n     ‫توقيــع نقيــب توقيــع رئيــس مكافحــة جرائــم األمــوال مقــدم توقيــع‬\n     ‫وبعرضــه علــى املدعــى عليــه قــال إن هــذا احملضــر غيــر صحيــح ولــم‬\n     ‫توجــد الصــورة يف منزلــي هــذا مــا لــدي كمــا وجدنــا يف ملفــات القضيــة‬\n     ‫تفريــغ امللــف املضغــوط للفــاش امليمــوري وقــد تضمــن عــدة منــاذج‬\n     ‫للكتابــة علــى شــيكات وســجالت وإيداعــات وهامــش خطــاب رســمي‬\n     ‫وشــعار شــركة ‪.....‬وختــوم وبعرضــه علــى املدعــى عليــه فقــال ال عالقــة‬\n     ‫لــي بذلــك وإن كانــت موجــودة فهــي ال تخصني وتخــص العامل البنغالي‬\n     ‫صاحــب الشــنطة التــي عثــرت عليهــا يف ســيارتي كمــا وجدنــا علــى‬\n     ‫لفــات املعاملــة الصــك الصــادر مــن هــذه احملكمــة برقــم ‪ ....‬يف‬\n     ‫‪1432/2/14‬ه ـ املتضمــن دعــوى شــركة ‪ ...‬ضــد املدعى عليه يف ســرقة‬\n     ‫مبلــغ انتهــت بالصلــح علــى تســليمه وقــال املدعــى عليــه ســبق وأن ركــب‬\n     ‫معــي شــخص بنغالــي اجلنســية ونســي شــنطته معــي وقمــت بفتحهــا‬\n     ‫ووجــدت بهــا احملــررات املــزورة وقمــت بإحــراق بعضهــا وإخفــاء البقيــة‬\n     ‫داخــل الشــنطة حتــت دالــوب املطبــخ قاصــدا إتالفهــا مســتقبال هــذا مــا‬\n     ‫لــدي وجــرى ســؤال املدعــي وكالــة عــن بينتــه التــي وعــد بإحضارهــا‬\n     ‫فقــال أطلــب إمهالــي وذلــك لوجودهــا لــدى شــعبة التزييــف والتزويــر هــذا‬\n\n\n‫‪83‬‬\n\f‫مــا لــدي وبنــاء عليــه فقــد مت رفــع اجللســة ويف جلســة أخــرى حضر املدعي‬\n‫وكالــة واملدعــى عليــه أصالــة وبســؤال املدعــي وكالــة عــن بينتــه التــي‬\n‫وعــد بإحضارهــا فقــال أن مكافحــة التزويــر وعدونــي بالــرد عليكــم‬\n‫فيمــا يخــص إقــراره بتزويــره الشــيك املدعــى بــه هــذا مــا لــدي هــذا‬\n‫وبالرجــوع إلــى املعاملــة وجــدت بــن طياتهــا احلكــم الصــادر مــن ديــوان‬\n‫املظالــم رقــم ‪/67‬د‪/‬ج‪ 2/‬لعــام ‪1431‬ه ـ واملدعــى فيهــا مــن قبــل هيئــة‬\n‫الرقابــة والتحقيــق ضــد املدعــى عليــه وآخريــن معــه أتهــم فيهــا هــو‬\n‫وشــخص آخــر اســمه بتزويــر محــرر عــريف هــو الشــيك رقــم ‪ ......‬يف‬\n‫‪2009/3/18‬م املنســوب لشــركة ‪ ...‬ألنظمــة احلاســب اآللــي وتقدميهمــا‬\n‫للشــيك مــزور محتجــن بصحتــه مــع علمهمــا بتزويــره ومت قبــض قيمــة‬\n‫الشــيك أجهــزة هواتــف واتهامــه والبقيــة بتزويــر شــيك آخــر وتقليــد‬\n‫أختــام حكوميــة وانتهــى احلكــم لــدى ديــوان املظالــم بإدانــة مبــا نســب‬\n‫إليــه مــن التزويــر واالســتعمال ومعاقبتــه علــى ذلك بســجنه ثالث ســنوات‬\n‫وتغرميــه عشــرة آالف ريــال وبعــرض ذلــك علــى املدعــى عليــه قــال إن هــذا‬\n‫احلكــم صــدر ضــدي واعترضــت عليــه ولــم ينــص يف احلكــم علــى‬\n‫الشــيك املــزور هــذا مــا لــدي هــذا وقــدم املدعــى عليــه جوابــا محــررا علــى‬\n‫صفحتــن تضمــن أقوالــه يف اجللســات الســابقة ونــص فيــه أنــه ال يوجــد‬\n‫اعتــراف منــه بوجــود صــورة الشــيك املزعــوم وبنــاء عليــه فقــد قــررت رفــع‬\n‫اجللســة للتأمــل ويف جلســة أخــرى حضــر املدعــي وكالــة واملدعــى عليــه‬\n‫وقــد جــرى منــا تأمــل مــا جــرى ضبطــه ســابقا ومبــا أن املدعــى عليــه قــد‬\n‫أديــن بتزويــر الشــيك املذكــور مــن قبــل ديــوان املظالــم بالقــرار املذكور‬\n‫كمــا أن الفرقــة القابضــة يف محضرهــا املذكــور قــد أثبتــت وجــود‬\n‫صــورة الشــيك املدعــى بقيمتــه يف منــزل املدعــى عليــه مــع وجــود معمــل‬\n\n\n                                                                                       ‫‪84‬‬\n\f     ‫كامــل للتزويــر كمــا أثبتــت األدلــة اجلنائيــة يف تقريرهــا املــدون ســابقا‬\n     ‫حصــول التزويــر علــى الشــيك يف بياناتــه ورقمــه وتاريخــه وقــد شــهد‬\n     ‫الشــاهد ‪ ...‬بإقــرار املدعــى عليــه أمامــه بتزويــر أحد شــيكات الشــركة‬\n     ‫املدعيــة كل هــذا يعــد قرائــن قويــة تعضــد مــا صــدر ضــد املدعــى عليــه‬\n     ‫مــن حكــم بإدانتــه بتزويــر الشــيك املذكــور مــن قبــل ديــوان املظالــم‬\n     ‫وفعلــه هــذا جنايــة يف حــق الشــركة املدعيــة يوجــب عليــه ضمــان قيمتــه‬\n     ‫لذلــك كلــه فقــد حكمــت علــى املدعــى عليــه بــأن يســلم للشــركة‬\n     ‫املدعيــة املبلــغ املدعــى بــه والــذي قــدره أربعمائــة وخمســة وثمانــون ألــف‬\n     ‫ريــال وبعــرض احلكــم علــى املدعــى عليــه قــرر عــدم القناعــة وطلــب رفــع‬\n     ‫معاملتــه إلــى محكمــة االســتئناف فأجبتــه إلــى طلبــه وأفهمتــه انــه‬\n     ‫ســوف يســلم صــورة مــن نســخة احلكــم يــوم االثنــن ‪1433/7/7‬ه ـ وان‬\n     ‫لــه مهلــة ثالثــن يومــا مــن تاريــخ اســتالم نســخة احلكــم لتقــدمي الئحتــه‬\n     ‫االعتراضيــة فــإذا مضــت املهلــة ولــم يتقــدم بالئحتــه االعتراضيــة ســقط‬\n     ‫حقــه يف االعتــراض وأصبــح احلكــم نافــذا وبــه ختمــت اجللســة ‪11.30‬‬\n     ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                  ‫وسلم ‪ .‬حرر يف ‪ 1433/07/01‬هـ‬\n     ‫احلمــد هلل وحــده وبعــد‪ :‬ففــي يــوم الثالثــاء املوافــق‪ 1434/01/20‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ 11 : 15‬وفيهــا حضــر‪ /‬املدعــي وكالــة‬\n     ‫واملدعــى عليــه ‪ ،‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف باخلطاب‬\n     ‫رقــم‪ )331538468(:‬يف ‪1433/11/20‬ه ـ ـ وبرفقهــا قــرار الدائــرة‬\n     ‫اجلزائيــة الثانيــة برقــم‪ )33444259(:‬يف ‪1433/11/2‬هـ ـ املتضمــن مــا‬\n     ‫نصــه‪« :‬قررنــا باإلجمــاع ‪ :‬أوال‪ /‬اســتند فضيلتــه يف حكمــه على التقرير‬\n     ‫الفنــي رقــم‪ )32793( :‬الصــادر مــن إدارة الفحــوص الفنيــة للتزييــف‬\n\n\n‫‪85‬‬\n\f‫والتزويــر‪ ،‬وهــذا محــل نظــر إذ لــم يكتمــل التقريــر ليعتمــد عليــه كمــا‬\n‫هــو موضــح يف الفقــرة الثانيــة منــه كمــا اســتند فضيلتــه علــى شــهادة‬\n‫وقــد ذكــر املدعــى عليــه أن الشــاهد معــه يف نفــس قضيــة التزويــر لــدى‬\n‫ديــوان املظالــم ولــم يناقــش فضيلتــه الطرفــن يف ذلــك‪ .‬ثانيــا‪ /‬ذكــر‬\n‫وكيــل املدعــى عليــه يف الئحتــه االعتراضيــة أن الشــركة قــد أقامــت‬\n‫دعــوى ضــد البنــك ‪ ...‬بلجنــة تســوية املنازعــات املصرفيــة إللزامــه بــرد‬\n‫مبلــغ الشــيك علــى أســاس خطــأ البنــك يف صــرف شــيك مــزور وذكــر‬\n‫أن موكلــه دفــع بهــذا الدفــع مبذكــرة افتتاحيــة يف أول الدعوى الطالع‬\n‫فضيلتــه ومناقشــة املدعــى عليــه يف ذلــك‪ .‬كمــا ذكــر يف الئحتــه أن‬\n‫الشــركة لــم تقــدم مــا يثبــت أن الشــيك مت صرفــه للمدعــو ‪ ...‬وخصــم‬\n‫مــن حســاب الشــركة‪ ،‬فعلــى فضيلتــه التحقــق مــن ذلــك ومناقشــة‬\n‫الطرفني فيه ال ســيما وقد أرفق أصل الشــيك بخطاب شــعبة مكافحة‬\n‫التزييــف والتزوير»ا‪.‬ه ـ ـ وبعــرض ذلــك علــى املدعــي وكالــة قــال‪ :‬أمــا‬\n‫التقريــر الفنــي فــا أعلــم عنــه‪ ،‬وأمــا الشــاهد فــكان معــه يف قضيــة‬\n‫التزويــر يف ديــوان املظالــم ولكــن ليــس يف موضــوع الشــيك اخلــاص‬\n‫مبوكلتــي وإمنــا يف موضــوع شــيك شــركة ‪ ...‬فقــط‪ ،‬وشــهادته تنصــب‬\n‫علــى أن املدعــى عليــه أبــرز لــه صــورة شــيك عائــد ملوكلتــي ألجــل تزويره‬\n‫وأمــا الدعــوى التــي ســبق وأن أقامتهــا موكلتــي علــى البنــك ‪ ...‬يف جلنــة‬\n‫تســوية املنازعــات املصرفيــة فصحيــح وقــد أوقفــت النظــر فيهــا اللجنــة‬\n‫املذكــورة ألجــل نظــر الدعــوى ضــد املــزور املدعــى عليــه فأقمنــا هــذه‬\n‫الدعــوى بعــد توقــف اللجنــة عــن نظرهــا‪ ،‬وأمــا يتعلــق بصــرف الشــيك‬\n‫لصالــح ‪ ...‬فقــد صــرف الشــيك املــزور لصالــح ‪ ...‬وخصــم مــن حســاب‬\n‫موكلتــي وأســتعد بإحضــار مــا يثبــت ذلــك‪ .‬وقــد أرفقنــا أصــل الشــيك‬\n\n\n                                                                                   ‫‪86‬‬\n\f     ‫املدعــى بتزويــره يف أصــل املعاملــة بعدمــا مت صــرف قيمتــه باالعتمــاد‬\n     ‫علــى الشــيك املــزور مــن قبــل املدعــى عليــه‪ ،‬هــذا مــا لــدي وبعــرض ذلــك‬\n     ‫علــى املدعــى عليــه‪ ،‬قــال‪ :‬أمــا التقريــر الفنــي فــا أعلــم هــل أعتمــد أم ال‪.‬‬\n     ‫وأمــا الشــاهد فهــو متهــم معــي يف الشــيك العائــد للشــركة املدعيــة‬\n     ‫وشــهادته محــل تهمــة وليــس لــي عالقــة بذلــك‪ ،‬والدعــوى املقامــة مــن‬\n     ‫الشــركة املدعيــة ضــد البنــك ال زالــت حتــت النظــر فيمــا أعلــم‪،‬‬\n     ‫والشــركة املدعيــة لــم تقــدم بينــة علــى صــرف الشــيك املذكــور أو أنــه‬\n     ‫خصــم مــن حســاب الشــركة‪ ،‬وأطلــب إمهالــي إلحضــار جــواب مفصــل‬\n     ‫يف ذلــك‪ ،‬هــذا مــا لــدي‪ .‬وبنــاء عليــه فقــد قــررت الكتابــة إلــى جلنــة‬\n     ‫تســوية املنازعــات املصرفيــة لإلفــادة عــن القضيــة املنظــورة لديهــم‬\n     ‫وإحضــار املدعــي وكالــة بينتــه التــي ذكــر‪ .‬وبــه رفعــت اجللســة ‪ ،‬ويف‬\n     ‫جلســة اخــرى حضــر املدعــي وكالــة‪ ،...... /‬كمــا حضــر املدعــى عليــه‬\n     ‫أصالــة‪ /‬املدونــة هويتــه ســابقا‪ ،‬وقــال املدعــى عليــه‪ :‬إن جوابــي علــى مــا‬\n     ‫ذكــره املدعــي وكالــة يف اجللســة قبــل املاضيــة هــو‪ :‬أن الشــركة‬\n     ‫املدعيــة أقامــت دعواهــا ضــد البنــك الرتكابــه خطــأ يف صــرف املبلــغ‬\n     ‫بنــاء علــى شــيك يذكــرون أنــه مــزور‪ ،‬وهــو قــد أفــاد أن أصــل الشــيك‬\n     ‫موجــود عندهــم والقضيــة منظــورة لــدى اللجنــة‪ ،‬ولــم يتــم الفصــل يف‬\n     ‫حينــه حتــى تاريخــه‪ .‬والشــاهد ‪ ...‬متهــم يف نفــس القضيــة بالتزويــر‪،‬‬\n     ‫وهــذا يقــدح يف شــهادته ألنــه صاحــب مصلحــة‪ ،‬هــذا مــا لــدي‪ .‬هــذا وقــد‬\n     ‫أحضــر املدعــي وكالــة معــه‪ :‬مينــي اجلنســية مبوجــب رخصــة اإلقامــة‬\n     ‫رقــم‪ ).....( :‬وطلــب ســماع مــا لديــه‪ ،‬وبســؤاله عمــا لديــه‪ ،‬قــال‪ :‬إننــي مــن‬\n     ‫مواليــد عــام ‪1971‬م وأعمــل مســئول مشــتريات‪ ،‬وأســكن يف مدينــة ‪،...‬‬\n     ‫وأشــهد هلل وبصفتــي مديــر املشــتريات يف مؤسســة ‪ ...‬للتجــارة لصاحبهــا‬\n\n\n‫‪87‬‬\n\f‫اتصــل بــي شــخص ســعودي وطلــب شــراء جــواالت ‪ ..‬باجلملــة‪ ،‬فتــم‬\n‫التفــاوض بيننــا علــى تلبيــة رغبتــه بشــراء كميــة مــن اجلــواالت مــن نــوع‬\n‫‪ ....‬فتــم االتفــاق علــى بيــع الكميــة وطلبنــا منــه إحضــار شــيك باســم‬\n‫املؤسســة وأفهمتــه بأنــه لــن يســلم لــه املبيــع إال بعــد صــرف الشــيك مــن‬\n‫البنــك‪ ،‬فقــال‪ :‬ال يوجــد لــدي حســاب يف البنــك ‪ ...‬وال يف ‪ ...‬وأخبرتــه أن‬\n‫الشــيك ســيحتاج إلــى مقاصــة‪ ،‬وهــذا ســيتأخر‪ ،‬وقلــت لــه اجعــل الشــيك‬\n‫باســمي‪ ،‬حتــى أمتكــن مــن صرفــه؛ لكــون املذكــور مســتعجل يف‬\n‫اســتالم الكميــة فكتــب الشــيك باســمي‪ ،‬وقمــت بصرفــه مــن البنــك‬\n‫‪ ،...‬ثــم أودعتــه يف حســاب املؤسســة‪ ،‬وكان املبلــغ أربعمائــة وخمســة‬\n‫وثمانــن ألــف ريــال‪ ،‬ثــم أبــرز الشــاهد ســند إيــداع نقــد بتاريــخ‬\n‫‪2009/3/18‬م باملبلــغ املذكــور تضمــن إيداع املبلغ يف حســاب املؤسســة‬\n‫املذكــورة‪ ،‬وقــال أنــا لــم أشــاهد املشــتري‪ ،‬هــذا مــا لــدي‪ .‬هــذا وقــد‬\n‫وردنــا خطــاب نائــب محافــظ مؤسســة النقــد رقــم‪ ).......( .:‬يف‬\n‫‪1434/2/24‬هـ ـ املتضمــن‪ « :‬نــود إفــادة فضيلتكــم بــأن املؤسســة قامت‬\n‫مبخاطبــة جلنــة تســوية املنازعــات املصرفيــة بشــأن املوضــوع أعــاه‪،‬‬\n‫والــذي مبوجبــه تلقــت خطــاب ســعادة األمــن العــام للجنــة تســوية‬\n‫املنازعــات املصرفيــة اجلوابــي املتضمــن بــأن شــركة (‪ )...‬اقامــت دعــوى‬\n‫ضــد البنــك ‪ ...‬قيــدت بســجالت اللجنــة برقــم‪ )1431/275( :‬مرفــق‬\n‫صــورة منهــا تطالــب فيهــا مببلــغ مقــداره ‪ 485000‬ريــال قيمــة شــيك‬\n‫تدعــي بأنــه لــم يصــدر مــن الشــركة‪ ،‬ونظــرت الدعــوى بجلســة يــوم‬\n‫االثنــن ‪1432/4/16‬ه ـ ـ وقــد قــررت اللجنــة الكتابــة ملؤسســة النقــد‬\n‫العربــي الســعودي لتزويدهــا مبــا مت حــول هــذا النــزاع‪ ،‬وموافاتهــا بأصل‬\n‫الشــيك محــل الدعــوى أو مخاطبــة شــرطة الريــاض لإلفــادة عمــا إذا مت‬\n\n\n                                                                                    ‫‪88‬‬\n\f     ‫إجــراء املضاهــاة علــى الشــيك موضــوع النــزاع‪ ،‬ومــن ثم تزويدها بنســخة‬\n     ‫مــن التقريــر الفنــي بواقعــة التزويــر‪ .‬والــذي مبوجبــه تلقــت األمانــة العامــة‬\n     ‫للجنــة خطــاب املؤسســة املتضمــن بــأن املؤسســة قامــت بتزويــد إمــارة‬\n     ‫منطقــة الريــاض بأصــل الشــيك رفــق خطابهــا رقــم‪3448( :‬م ظ ‪/‬أ ق)‬\n     ‫وتاريــخ ‪1430/9/5‬هـ ـ بنــاء علــى طلبهــم وأن أصل الشــيك ال يزال بحوزة‬\n     ‫اإلمــارة ‪ ،‬كمــا تضمــن خطــاب ســعادة األمــن العــام للجنــة تســوية‬\n     ‫املنازعــات املصرفيــة املشــار إليــه أعــاه‪ ،‬بــأن هــذه الدعــوى ال تــزال‬\n     ‫موقوفــة إلــى حــن ورود إمــا أصــل الشــيك محــل الدعــوى‪ ،‬أو التقريــر‬\n     ‫الفنــي املعـ ّـد بواقعــة التزوير»ا‪.‬ه ـ ـ ـ وبســؤال املدعــي وكالــة عــن مــا يثبــت‬\n     ‫صــرف الشــيك‪ ،‬فقــال‪ :‬أطلــب إمهالــي إلحضــاره‪ ،‬وبــه رفعــت اجللســة‪،‬‬\n     ‫ويف جلســة اخــرى حضــر املدعــى عليــه اصالــه املدونــة هويتــه ســابقا ولــم‬\n     ‫يحضــر مــن ميثــل الشــركة املدعيــة وقــال املدعــى عليــه اننــي اطلــب عــدم‬\n     ‫شــطب القضيــة واالســتمرار يف نظرهــا وقــدم ورقــه جــاء فيهــا أود ان‬\n     ‫ابــن لفضيلتكــم التالــي ‪ :‬اوال‪ :‬بخصــوص امللحوظــة األولــى مــن‬\n     ‫محكمــة االســتئناف بشــان الدعــوى املرفوعــة مــن الشــركة املدعيــة‬\n     ‫ضــد البنــك ‪ ...‬امــام جلنــه تســوية املنازعــات املصرفيــة فقــد ثبــت‬\n     ‫لفضيلتكــم مبخاطبــة اللجنــة املذكــورة ان الدعــوى ال تــزال متداولــة‬\n     ‫لديهــا وهــو مــا يوكــد صحــة مــا دفعــت بــه مــن ان املدعيــة قــد ســلكت‬\n     ‫طريقــن للمطالبــة بــذات املوضــوع ‪،‬ثانيــا‪ :‬بخصــوص امللحوظــة الثانيــة‬\n     ‫مــن محكمــة االســتئناف وهــي بشــان اعتمــاد شــهادة الشــاهد ‪......./‬‬\n     ‫كقرينــة علــى احلكــم علــى ‪ ،‬فأننــي مصمــم علــى القــدح يف شــهادة‬\n     ‫هــذا الشــاهد وذلــك ألنــه كان متهمــا معــي يف قضيــة التزويــر وهــو‬\n     ‫صاحــب مصلحــة يف الدعــوى كونــه مــن املمكــن ان يتخــوف مــن‬\n\n\n‫‪89‬‬\n\f‫اختصــام املدعيــة لــه ‪ ،‬ثالثــا‪ /‬وبعــد تــداول القضيــة للمــرة الثانيــة‬\n‫باجللســات لــم تقــدم املدعيــة البينــة الصحيحــة علــى ثبــوت جنايتــي يف‬\n‫حقهــا ‪ ،‬بنــاء عليــه فأننــي اطلــب فضيلتكــم احلكــم بصــرف النظــر عــن‬\n‫الدعــوى ‪ ،‬حيــث اننــي قضيــت مــدة العقوبــة املقضــي بهــا علــي منــذ‬\n‫تاريــخ ‪1430/12/29‬ه ـ وال يعطــل اإلفــراج عنــي ســوى هــذه القضيــة‬\n‫التــي ال ذنــب لــي فيهــا أه ـ ‪ ،‬وبنــاء عليــه فقــد قــررت رفــع اجللســة ‪ ،‬ويف‬\n‫جلســة أخــرى حضــر املدعــي وكالــة‪ ، /‬كمــا حضــر املدعــى عليــه‬\n‫أصالة‪ ، /‬وأبرز املدعي وكالة كشــف حســاب صادر من ‪ ...‬للحســاب‬\n‫رقــم‪ )......(:‬اخلــاص بــ‪...‬املترجــم مــن مكتــب ‪ ...‬للترجمــة املتضمــن أنــه‬\n‫بتاريــخ ‪2009/3/18‬م مت ســحب شــيك رقــم‪ )......(:‬مببلــغ أربعمائــة‬\n‫وخمســة وثمانــن ألــف ريــال هــذا وقــد جــرى منــي االطــاع علــى التقريــر‬\n‫الفنــي املرفــق باملعاملــة والصــادر مــن إدارة الفحــوص الفنيــة للتزييــف‬\n‫والتزويــر والــذي تضمــن يف نتيجتــه أوال بفحــص الشــيك موضــوع‬\n‫الفحــص باســتخدام األجهــزة املكبــرة وجدنــا أنــه يحمــل العالمــات‬\n‫األمنيــة واخلصائــص الطباعيــة للشــيكات الصحيحــة وتعــرض للتزويــر‬\n‫باحملــو وإعــادة طباعــة للبيانــات احلاليــة عليــه وهــي الرقــم التسلســلي‬\n‫ورقــم احلســاب ورقــم الترميــز الطباعــي لدفتــر الشــيكات واســم‬\n‫الشــركة(…‪ ).‬ثانيــا ملضاهــاة التواقيــع املنســوبة لــكل مــن املدعــو‬\n‫واملدعــو يلــزم حتقيــق اآلتــي‪ /1 :‬إرســال منــوذج التوقيــع لــدى البنــك ‪...‬‬\n‫لنفس احلســاب املســحوب عليه الشــيك موضع الفحص ومناذج شــيكات‬\n‫مماثلــة ســبق صرفهــا حتمــل التواقيــع املذكوريــن ‪/2‬تكليــف‬\n‫للمذكوريــن مبراجعتنــا يف وقــت يتزامــن مــع إرســال أوراق القضيــة‬\n‫الفاحــص رقيــب‪ ./‬اخلبيــر رائــد‪ . /‬مديــر شــعبة اخلطــوط والتواقيــع مقدم‪.‬‬\n\n\n                                                                                      ‫‪90‬‬\n\f     ‫مديــر إدارة الفحــوص الفنيــة للتزييــف والتزويــر عقيــد ‪ ،‬وبنــاء عليــه‬\n     ‫فقــد جــرى رفــع اجللســة ‪ ،‬ويف جلســة أخــرى حضــر املدعــي وكالــة‪/‬‬\n     ‫كمــا حضــر املدعــى عليــه‪ ، /‬وبنــاء علــى مــا ســبق فإننــي أجيــب علــى‬\n     ‫مــا الحظــه أصحــاب الفضيلــة بأننــي اعتمــدت يف مــا حكمــت بــه علــى‬\n     ‫احلكــم الســابق مــن ديــوان املظالــم املثبــت إلدانــة املدعــى عليــه بتزويــر‬\n     ‫الشــيك املذكــور‪ ،‬وقــد اعتضــد ذلــك لــدي بقرائــن هــي أن املدعــى‬\n     ‫عليــه قــد أقــر يف إقــراره املصــدق شــرعا بحيازتــه ألدوات التزويــر‬\n     ‫واملطبوعــات واألختــام املــزورة‪ ،‬وقيامــه بإخفائهــا يف منزلــه‪ ،‬وكــذا مــا‬\n     ‫جــاء يف محضــر االنتقــال والتفتيــش أنهــم عثــروا بداللــة املدعــى عليــه يف‬\n     ‫مــكان مخفــي يف منزلــه علــى أدوات التزويــر واملطبوعــات واألختــام‬\n     ‫املــزورة كمــا عثــروا علــى صــورة الشــيك املدعــى بــه املــزور‪ ،‬وكــذا‬\n     ‫محضــر تفريــغ الفــاش امليمــوري والــذي احتــوى علــى منــاذج التزويــر‬\n     ‫وهــذا يــدل علــى امتهانــه للتزويــر ومترســه فيــه ال ســيما مــع وجــود صورتــه‬\n     ‫لديــه وقــد قــدم املدعــي وكالــة مــا يثبــت صــرف الشــيك املذكــور وأقــر‬\n     ‫بذلــك احلاضــر أمــا مــا ذكــره أصحــاب الفضيلــة مــن أن أصــل الشــيك‬\n     ‫موجــود فصحيــح‪ ،‬إذ الدعــوى بتزويــره ولــو صــرف أصــل الشــيك ملــا‬\n     ‫اعتبــر هــذا تزويــرا وأمــا مــا يتعلــق بالدعــوى املقامــة لــدى جلنــة تســوية‬\n     ‫املنازعــات املصرفيــة‪ ،‬فالــذي يظهــر لــي أنهــا ال تؤثر على هــذه الدعوى‪،‬‬\n     ‫وهــي دعــوى مســتقلة و الدعــوى يف املطالبــة بقيمــة الشــيك إمنــا تتوجــه‬\n     ‫علــى املتســبب بصــرف قيمتــه وبهــذا لــم يظهــر لــي مــا يؤثــر علــى مــا‬\n     ‫حكمــت بــه‪ ،‬وقــررت بعــث املعاملــة إلــى محكمــة االســتئناف‪ ،‬وبــه‬\n     ‫ختمــت اجللســة الســاعة ‪ 10 : 00‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                    ‫محمد وعلى آله وصحبه وسلم ‪ .‬حرر يف ‪ 1434/05/07‬هـ‬\n\n\n‫‪91‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق‪ 1434/07/02‬ه ـ‬\n‫افتتحت اجللســة الســاعة ‪ 09 : 45‬وقد عادت املعاملة إلينا من محكمة‬\n‫االســتئناف برقــم ‪ 341213075‬وتاريــخ ‪1434/6/21‬ه ـ وبرفقهــا القرار‬\n‫الصــادر مــن الدائــرة الثانيــة لتمييــز القضايــا اجلزائيــة رقــم ‪34240282‬‬\n‫وتاريــخ ‪1434/6/13‬ه ـ املتضمــن‪ :‬وباالطــاع علــى مــا أجاب بــه فضيلته‬\n‫وأحلقــه بالصــك وصــورة ضبطــه بنــاء علــى قرارنــا رقــم ‪33444259‬‬\n‫وتاريــخ ‪1433/11/2‬ه ـ تقــرر لألكثريــة املصادقــة علــى احلكــم بعــد‬\n‫اإلجــراء األخيــر ‪ ،‬وجــرى التهميــش عليــه مبوجبــه وبــه ختمــت اجللســة‬\n‫الســاعة ‪ 09 : 50‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                             ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/2‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                 ‫‪92‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":77,"source_page_end":92,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5b6b05b8936bc08552e1413fa71ae0d976473f6e3a9892b4f2989b08a6cedcc7","normalized_text_hash":"3a30d2e746e3c97fb9a5b161dc1fdf14402fbdd60a8be3e5bad3866b36f33f1e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p77-33324572"},{"id":"7d8bf8a4-db28-53f9-a5c5-49277034c4ae","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة مبالغ مالية عن طريق النصب واالحتيال - اإلقرار حجه على املقر -ورود املبالغ يف حساب املدعى عليه -تصرف اإلنسان محمول على الصحة و النفاذ -احلكم بإلزام املدعى عليها تسليم املبلغ املدعى به.","document_number":"34265447","case_number":"3451857","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/11","year":"1434","subject":"رد مسروق -سرقة مبالغ مالية عن طريق النصب واالحتيال - اإلقرار حجه على املقر -ورود املبالغ يف حساب املدعى عليه -تصرف اإلنسان محمول على الصحة و النفاذ -احلكم بإلزام املدعى عليها تسليم املبلغ املدعى به.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/7/11 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34265447 :‬‬\n                          ‫َر ْق ُم الدعوى‪3451857:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34358464‬تاريخه‪1434/11/12:‬هـ‬\n\n\n     ‫رد مســروق‪ -‬ســرقة مبالــغ ماليــة عــن طريــق النصــب واالحتيــال ‪-‬‬\n     ‫اإلقــرار حجــه علــى املقــر ‪ -‬ورود املبالــغ يف حســاب املدعى عليه ‪ -‬تصرف‬\n     ‫اإلنســان محمــول علــى الصحــة و النفــاذ ‪ -‬احلكــم بإلــزام املدعــى عليهــا‬\n                                                         ‫تســليم املبلــغ املدعــى بــه‪.‬‬\n\n\n\n\n                               ‫‪ -1‬اإلقرار حجة على املقر واملرء مؤاخذ بإقراره‪.‬‬\n                         ‫‪ -2‬األصل يف التصرفات حملها على الصحة والنفاذ ‪.‬‬\n\n\n\n\n     ‫ادعــى وكيــل املدعيــة بــأن املدعــى عليهــا عاونــت ابنهــا علــى مــا قــام‬\n     ‫بــه مــن نصــب واحتيــال جتــاه موكلتــه؛ وذلــك بــأن مكنــت ابنهــا مــن‬\n     ‫اســتقبال مبالــغ ماليــة حولتهــا املدعيــة بنــاء علــى طلبــه إلــى احلســاب‬\n     ‫املصــريف اخلــاص بوالدتــه املدعــى عليهــا بعــد أن أوهــم املدعيــة برغبتــه‬\n     ‫يف الــزواج منهــا ثــم غــادر اململكــة نهائي ـ ًا إلــى بــاده دون أن يفــي‬\n     ‫بوعــده‪ ،‬ولــذا فقــد طلــب إلزامهــا بإعــادة املبالــغ التــي حولتهــا موكلتــه‬\n     ‫علــى حســابها‪ -‬أقــر وكيــل املدعــى عليهــا بدخــول املبالــغ املدعــى بهــا‬\n     ‫إلــى حســاب موكلتــه ودفــع بــأن احلســاب كان حتــت يــد ابنهــا وأنــه‬\n     ‫املســتخدم الوحيــد لــه آنــذاك وهــو املســتفيد مــن تلــك املبالــغ وال عالقــة‬\n\n‫‪93‬‬\n\f‫للمدعــى عليهــا بذلــك‪ ،‬وأضــاف بــأن املدعــى عليهــا كبيــرة يف الســن‬\n‫وال جتيــد القــراءة والكتابــة‪ -‬وكيــل املدعــى عليهــا أقــر بدخــول‬\n‫املبالــغ املذكــورة يف الدعــوى إلــى حســاب موكلتــه ومــا دفــع بــه ال‬\n‫يخلــي مســؤوليتها مــن إعــادة مــا دخــل بحســابها إلــى املدعيــة‪ -‬قضــت‬\n‫احملكمــة حضوريـ ًا بإلــزام املدعــى عليهــا بتســليم املدعيــة أصالــة املبلــغ‬\n‫املدعــى بــه‪ -‬قنــع وكيــل املدعيــة باحلكــم وعارضــت عليــه املدعــى‬\n             ‫عليهــا‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد‪ :‬فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 3451857‬وتاريــخ‬\n‫‪1434/02/02‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34165043‬وتاريــخ‬\n‫‪1434/01/19‬ه ـ حضــر املدعــي وكالــة ســعودي بالســجل رقــم بصفتــه‬\n‫وكيــا عــن الفركــز بالوكالــة الصــادرة مــن كتابــة عــدل الريــاض‬\n‫الثانيــة برقــم ‪ 61031‬يف ‪1432/8/15‬ه ـ جلــد ‪ 19759‬وحضــر حلضــوره‬\n‫املدعــى عليــه وكالــة ســعودي بالســجل رقــم بصفتــه وكيــا عــن ‪...‬‬\n‫بالوكالــة الصــادرة مــن كتابــة عــدل شــمال جــدة الثانيــة برقــم‬\n‫‪ 33451058‬يف ‪1433/12/19‬ه ـ وألن الدعــوى غيــر محــررة لذا أفهمت‬\n‫املدعــي وكالــة بتحريــر دعــواه ففهــم ذلــك وعليــه جــرى تأجيــل اجللســة‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n‫‪ .‬حــرر يف ‪1434/03/14‬ه ـ ثــم يف جلســة أخــرى حضــر املدعــي وكالــة‬\n‫املدونــة هويتــه ووكالتــه ســابقا وحضــر حلضــوره املدعــى عليــه وكالــة‬\n\n                                                                                    ‫‪94‬‬\n\f     ‫ســعودي بالســجل رقــم بصفتــه وكيــا عــن بالوكالــة الصــادرة مــن‬\n     ‫كتابة العدل الثانية بشــمال جدة برقم ‪ 34479385‬يف ‪1434/4/17‬هـ‬\n     ‫بصفتــه وكيــل ‪ ...‬بالوكالــة رقــم ‪ 33451058‬وتاريــخ ‪1433/12/19‬ه ـ‬\n     ‫الصــادرة مــن كتابــة العــدل الثانيــة بشــمال جــدة وبســؤال املدعــي‬\n     ‫وكالــة عــن حتريــر دعــواه أفــاد قائــا ‪ :‬بعــد قيــام ابــن املدعــى عليهــا‪/‬‬\n     ‫‪.......‬ســعودي اجلنســية وبعــد تعرفــه علــى موكلتــي مــن موقــع ‪...‬‬\n     ‫اإللكترونــي قــام بالنصــب واالحتيــال علــى موكلتــي واســتغاللها‬\n     ‫واســتدراجها بنيــة الــزواج منهــا كمــا ادعــى وقــد تأملــت فيــه حســن‬\n     ‫النيــة وطلبــت منــه موكلتــي التعــرف علــى أهلــه وقــال لهــا إن والــدي قــد‬\n     ‫تــويف منــذ فتــرة قريبــه وأنــا اآلن أعولهــم جميعــا ونحــن مــن أســرة ثريــة‬\n     ‫وقــد توقفــت ثــروات والــدي وأنــا اآلن يف ضائقــة ماليــه كبيــره وســوف‬\n     ‫أعرفــك علــى أمــي وعلــى أختــي ولكــن أنــا محتــاج ملبلــغ مــن املــال اقضي‬\n     ‫احتيــاج أهلــي واطلــب منــك املســاعدة ومبجــرد انتهــاء أمــي مــن العــدة‬\n     ‫ســوف نقــوم بزيارتكــم وطلــب يــدك مــن اهلــك وقامــت موكلتــي بتلبيــة‬\n     ‫متطلباتــه وبعــد عــدة شــهور مــن االتصــاالت لــم يعــد يــرد علــى اتصــاالت‬\n     ‫موكلتــي واكتشــفت بعــد أن توصلــت ألرقــام أمــه ‪ ...‬عــن طريــق‬\n     ‫حســاباتها البنكيــة التــي أودعــت عليهــا املبالــغ اكتشــفت أنهــا وقعــت‬\n     ‫يف فــخ النصــب واالحتيــال مــن هــذا الرجــل الــذي تالعــب مبشــاعرها‬\n     ‫ومالهــا وســحب منهــا مبالــغ ماليــه تقــدر بـ ـ ‪160‬الــف ريــال مت إيداعها من‬\n     ‫حســاب موكلتــي حســابها اجلــاري ببنــك ‪ .....‬رقــم (‪ )....‬علــى حســابني‬\n     ‫مختلفــن للمدعــى عليهــا وهــي حســاب رقــم‪ .....‬ببنــك (‪ )....‬حيــث وصــل‬\n     ‫املبلــغ احملــول علــى هــذا احلســاب (‪ 93000‬ثالثــة وتســعون ألفــا ) يف‬\n     ‫(‪14‬اربعــة عشــر عمليــة مصرفيــه مــن تاريــخ ‪ 2010/10/05‬إلــى تاريــخ‬\n\n\n‫‪95‬‬\n\f‫آخــر عمليــه ‪ )2011/02/22‬وإيــداع مــن حســاب موكلتــي مبصــرف ‪...‬‬\n‫رقــم‪ .......‬علــى حســاب املدعــى عليهــا بنفــس البنــك حســاب مبصــرف‬\n‫‪ ......‬رقــم (‪ ).....‬مببلــغ (‪ 36000‬ســتة وثالثــون ألــف ريــال ) يف (‪ 7‬ســبع‬\n‫عمليــات مصرفيــه مــن تاريــخ ‪ 2011/10/29‬إلــى تاريــخ ‪2011/03/30‬‬\n‫ميــادي أي مــن تاريــخ ‪ 1431/10/20‬إلــى ‪ 1431/4/25‬هجريــة)‪ .‬ومت‬\n‫إيــداع املبالــغ بتواريــخ ميالديــة وكان إيــداع املبالــغ مــن شــهر ذو القعــدة‬\n‫مــن عــام ‪1431‬ه ـ وكل إيــداع موضــح تاريخ إيداعه مبوجب كشــوفات‬\n‫احلســابني وهــي مفصلــه كاملــة بكشــوفات مرفقــه صورهــا بهــذه‬\n‫الدعــوى وحيــث مــا قــام بــه مبعاونــه واضحــة مــن صاحبــة احلســابات‬\n‫املغربيــة اجلنســية مبوجــب اإلقامــة والســجل رقــم (‪ ).....‬تكــون طــرف‬\n‫أول وخصمهــا إمــام القضــاء حيــث مت االتصــال عليهــا مــن قبــل موكلتي‬\n‫ولــم حتذرهــا أو تنصحهــا بالبعــد عــن ابنهــا خصوصــا وأنهــا تعلــم إن‬\n‫ابنهــا يتالعــب بأعــراض النــاس وســحبهم واســتنزافهم ماديــا فضيلــة‬\n‫القاضــي يعلــم فضيلتكــم إن مــن شــارك يف جــرم ســواء باملســاعدة او‬\n‫بتســهيل أي وســيله للنصــب علــى النــاس فهــو شــريك ذلــك املجــرم بجرمه‬\n‫لــذا أطلــب إلــزام املدعــى عليهــا بدفــع مبلــغ وقــدره مائــة وثالثــون ألــف‬\n‫ريــال هــذه دعــواي وبعرضهــا علــى املدعــى عليــه وكالــة قــال أطلــب‬\n‫املهلــة للــرد يف اجللســة القادمــة هكــذا قــال وعليــه جــرى تأجيــل اجللســة‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n‫‪ .‬حــرر يف ‪1434/04/20‬ه ـ ثــم يف جلســة أخــرى حضــر املدعــي وكالــة‬\n‫املدونــة هويتــه ووكالتــه ســابقا وحضــر حلضــوره املدعــى عليــه وكالــة‬\n‫املدونــة هويتــه ووكالتــه ســابقا واملخولــة له حق اإلقرار وبســؤال املدعى‬\n‫عليــه وكالــة عمــا اســتمهل مــن أجلــه قــدم مذكــرة جوابيــة هــذا نصهــا‬\n\n\n                                                                                      ‫‪96‬‬\n\f     ‫‪ :‬بــأن مــا ذكرتــه املدعيــة يف دعواهــا غيــر صحيــح فاملدعــى عليهــا ليــس‬\n     ‫لديهــا أبــن يدعــى ‪ ...‬وهــذا االســم هــو أبــن زوجهــا مــن زوجــة أخــرى وإمنــا‬\n     ‫قــد تكــون املدعيــة تقصــد الســيد ‪ .......... /‬وهــو أبــن املدعــى عليهــا مــن‬\n     ‫زوج ســابق ‪ ،‬فــإن كانــت تقصــد هــذا فهــو مــن كان يســتخدم حســاب‬\n     ‫والدتــه البنكــي ونذكــر هنــا بــأن هــذا الشــخص قــد ارتبــط بعالقــة مــع‬\n     ‫املدعيــة كمــا ذكــرت يف دعواهــا وال نعــرف كيــف كانــت وال علــى‬\n     ‫أي أســاس بنيــت وإلــى أي حــد وصلــت بينهمــا فلــم نعلــم عــن هــذه العالقة‬\n     ‫إال بعــد ســفره ومغادرتــه اململكــة ‪.‬كمــا أن املذكــور ليــس ســعودي‬\n     ‫اجلنســية وإمنــا هــو مغربــي اجلنســية كان هنــا بوظيفــة عامــل وقــد حــدث‬\n     ‫بينــه وبــن كفيلــه خــاف أســتمر لفتــرة وكانــت والدتــه ( املدعــى‬\n     ‫عليهــا ) خــارج اململكــة وعــادت بتاريــخ ‪1431/10/23‬ه ـ أي قبــل بدايــة‬\n     ‫التحويــات حلســابها بثالثــة أيــام فقــط كمــا يتضــح مــن خــال تواريــخ‬\n     ‫التحويــات ( مرفــق ‪ ) 1‬وحــال وصولهــا جلــأ إليهــا ابنهــا وأخبرهــا أنــه قــد‬\n     ‫ا جديــد ًا وأنــه يقــوم اآلن بتنفيــذ أعمــال اجلبــس والديكــور‬     ‫وجــد عم ـ ً‬\n     ‫وهــو بحاجــة ماســة الســتخدام حســابها البنكــي إلمتــام هــذه األعمــال‬\n     ‫مــع عمالئــه وأخبرهــا بــأن التعامــات والتحويــات مببالــغ كبيــرة وال‬\n     ‫يســتطيع أن يســحب ســوى خمســة أالف ريــال يف اليــوم بحســب نظــام‬\n     ‫بطاقــات الصــراف وهــي ال تكفــي ويحتــاج ألكثــر مــن حســاب حلــن‬\n     ‫انتهــاء خالفــه مــع كفيلــه حتــى يتســنى لــه بعــد ذلــك فتح حســاب باســمه‬\n     ‫‪.‬وهنــا غلبــت عاطفــة األم وفرحتهــا بعمــل ابنهــا وانتهــاء مشــاكله‬\n     ‫وحتســن وضعــه فاســتجابت لطلبــه وقدمــت لــه بطاقــات الصــراف‬\n     ‫اخلاصــة بهــا مــع العلــم بــأن املدعــى عليهــا كبيــرة يف العمــر وغيــر متعلمــة‬\n     ‫وجتهــل مغبــة مــا أقدمــت عليــه وعاطفتهــا كأم غلبــت عليهــا يف حينهــا‬\n\n\n‫‪97‬‬\n\f‫ولــم تفكــر يف أي أمــر أخــر ‪.‬وبعــد فتــرة مــن الزمــن مت القبــض علــى‬\n‫الســيد ‪......... /‬ألن كفيلــه كان قــد أبلــغ الســلطات املختصــة بتغيــب‬\n‫مكفولــه وســافر إلــى بــاده مملكــة املغــرب ‪.‬وبعــد ســفره بعشــرة أيــام‬\n‫اتصلــت املدعيــة مبوكلتــي وســألتها عــن ابنهــا وأنــه لــم يعــد يــرد علــى‬\n‫اتصاالتهــا فأخبرتهــا موكلتــي بأنــه ســافر وســألتها مــن أنــت ومــا‬\n‫عالقتــك بابنــي فقالــت لهــا أنــا ‪...‬وكنــت علــى عالقــة بابنــك وأنهمــا‬\n‫كانــا ســيتزوجان فتعجبــت موكلتــي ممــا ســمعت منهــا وأخبرتهــا بأنــه‬\n‫متــزوج ولديــه أبنــاء فقالــت املدعيــة نعــم إنهــا تعــرف ذلــك وليــس كمــا‬\n‫ذكــرت املدعيــة يف دعواهــا بأنهــا اتصلــت باملدعــى عليهــا ولــم حتذرهــا‬\n‫واســتمرت تتصــل مبوكلتــي وتبعــث لهــا بالرســائل العامــة العاديــة عبــر‬\n‫اجلــوال ولــم تتحــدث معهــا وال تبلغهــا عــن هــذه املبالــغ ولــم تذكرهــا أو‬\n‫حتــى تعــرض بذكرهــا مطلقــا ‪.‬ولكــن كانــت تتصــل يف أوقــات‬\n‫متأخــرة بالليــل وتبعــث بالرســائل أيض ـ ًا يف أوقــات متأخــرة جــد ًا‬\n‫وموكلتــي امــرأة كبيــرة يف الســن ال تســهر كثيــر ًا وال جتيــد القــراءة‬\n‫والكتابــة فأخبرتهــا بذلــك بــكل لطــف وقالــت لهــا ممكــن ان‬\n‫تتواصلــي مــع بناتــي فهــم يف مثــل عمــرك تقريب ـ ًا وانتهــت اتصاالتهــا‬\n‫مبوكلتــي مــن تلــك اللحظــة ولــم تعــرف عنهــا شــيء مــن حينهــا إال أن‬\n‫موكلتــي أصبحــت تتعــرض ملضايقــات عبــر اجلــوال وإزعاجــات وال‬\n‫تعــرف مصدرهــا فغيــرت رقــم جوالهــا تفادي ـ ًا ملــا يحــدث معهــا مــن‬\n‫إزعاجــات ‪.‬وهنــا نتســاءل ملــاذا تقــوم املدعيــة بتحويــل كل هــذه األمــوال‬\n‫لشــخص ال تعــرف حتــى اســمه وتدعــي اآلن إنهمــا كانــا متفقــان علــى‬\n‫الــزواج وملــاذا لــم حتــاول االتصــال بأمــه خــال تواجــده هنــا وعالقتهــا‬\n‫معــه كمــا ادعــت خصوصــا أنهــا ذكــرت يف دعواهــا أنــه قــد وعدهــا‬\n\n\n                                                                                    ‫‪98‬‬\n\f     ‫بــأن يقومــون بزيارتهــم هــو وأمــه بعــد انتهــاء عــدة أمــه كمــا جــاء يف‬\n     ‫صحيفــة الدعــوى بينمــا التحويــات اســتمرت قرابــة الســتة أشــهر فــأي‬\n     ‫عــدة هــذه التــي تســتمر لســتة أشــهر ومبراجعــة بســيطة لتواريــخ تلــك‬\n     ‫التحويــات التــي قامــت بهــا املدعيــة ( مرفــق ‪ ) 1‬جنــد أن التحويــات‬\n     ‫كانــت متتاليــة ومتواليــة إلــى درجــة أن بعضهــا كانــت يف نفــس اليــوم‬\n     ‫وهــذا يرجــح كالم الســيد ‪ /‬بــأن اســتخدامه للحســابات للعمــل وليــس‬\n     ‫كمــا ادعــت املدعيــة بأنهــا عالقــة بقصــد الــزواج ولكــن هــل جــرى‬\n     ‫العــرف بــأن تدفــع العــروس لعريســها املــال قبــل زواجهمــا ‪.‬ممــا هو واضح‬    ‫ُ‬\n     ‫يــا فضيلــة القاضــي بــأن املدعيــة ال تخــرج عــن أحــد أمريــن إمــا أن‬\n     ‫عالقتهــا كانــت مــع الســيد ‪ /‬عالقــة جتاريــة وهــو األرجــح أو أنهــا‬\n     ‫صادقــة فيمــا ادعــت بــه مــن أنهــا عالقــة بقصــد الــزواج ‪ ،‬واألمــر يف‬\n     ‫كال احلالتــن ال يعنــي موكلتــي فليــس هنــاك صفــة تعاقديــة بينهــا وبــن‬\n     ‫املدعيــة واملدعيــة مفرطــة واملفــرط أولــى باخلســارة ‪.‬لــكل مــا تقــدم يــا‬\n     ‫فضيلــة الشــيخ فأننــي اطلــب رد الدعــوى وصــرف النظــر عنهــا وأن صــح‬\n     ‫مــا ادعــت بــه املدعيــة يف دعواهــا فعليهــا إقامــة الدعــوى علــى الســيد ‪/‬‬\n     ‫وليــس علــى والدتــه ‪ ،‬وقــد ذكــرت هــي ذلــك يف دعواهــا صراحة فقالت‬\n     ‫( أنهــا وقعــت يف فــخ النصــب واالحتيــال مــن هــذا الرجــل الــذي تالعــب‬\n     ‫مبشــاعرها ) ‪ ...‬وهــذا إقــرار منهــا مبــن نصــب عليهــا فعليهــا مقاضاتــه‬\n     ‫هــو بعينــه ‪.‬وختامـ ًا يــا فضيلــة الشــيخ فــأن موكلتــي بالرغــم مــن كل مــا‬\n     ‫ذكرنــا مســتعدة للمثــول أمــام فضيلتكــم وأداء اليمــن الشــرعي علــى‬\n     ‫أنــه ليــس لهــا أي عالقــة باملدعيــة ولــم تعلــم عنهــا وعــن عالقتهــا بابنها إال‬\n     ‫بعــد ســفره مــن خــال املدعيــة نفســها وأنهــا لــم تســتلم أو تســتفد مــن أي‬\n     ‫شــيء مــن تلــك املبالــغ وبســؤال وكيــل املدعــى عليهــا هــل دخلــت املبالــغ‬\n\n\n‫‪99‬‬\n\f‫يف حســاب املدعــى عليهــا أجــاب قائــا ‪ :‬نعــم لقــد دخلــت املبالــغ التــي‬\n‫ذكرهــا وكيــل املدعيــة يف حســاب موكلتــي وقــد ذكــرت يف‬\n‫مذكرتــي ســبب دخولهــا ومــن تصــرف فيهــا هكــذا أجــاب وبســؤال‬\n‫وكيــل املدعيــة عــن املبلــغ الــذي يطالــب بــه حتديــدا حيــث ورد يف دعــواه‬\n‫أن موكلتــه حولــت ثالثــة وتســعون ألــف ريــال علــى دفعــات ثــم حولــت‬\n‫ثالثــة وســتون ألــف ريــال علــى دفعــات واملجمــوع مائــة وتســعة وعشــرون‬\n‫ألــف ريــال وليــس كمــا ذكــر يف دعــواه بــأن مــا تطالــب بــه موكلتــه‬\n‫مبلــغ وقــدره مائــة وثالثــون ألــف ريــال أجــاب قائــا ‪ :‬أطلــب املهلــة للرجوع‬\n‫ملوكلتــي لتحديــد املبلــغ بالتفصيــل هكــذا أجــاب وعليــه جــرى تأجيــل‬\n‫اجللســة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n‫وســلم ‪ .‬حــرر يف ‪ 1434/05/26‬ه ـ ثــم يف جلســة أخــرى حضــر املدعــي‬\n‫وكالــة خميــس واملدونــة هويتــه ووكالتــه ســابقا ولــم حتضــر املدعــى‬\n‫عليهــا وال وكيــا عنهــا رغــم تبلــغ وكيلهــا باملوعــد يف اجللســة املاضيــة‬\n‫وبنــاء علــى الفقــرة األولــى مــن املــادة اخلامســة واخلمســن مــن نظــام‬\n‫املرافعات الشــرعية قررت الســير يف الدعوى حضوريا وبســؤال املدعي‬\n‫وكالــة عمــا اســتمهل مــن أجلــه أجــاب قائــا ‪ :‬أوال ‪ /‬مــا مت إيداعــه مــن‬\n‫حســاب املدعيــة حلســاب املدعــى عليهــا ببنــك ‪ ...‬هــو مبلــغ (‪)108000‬‬\n‫مائــة وثمانيــة آالف ريــال كمــا هــو املوضــح بالكشــفني املرفقــة مــن‬\n‫نفــس البنــك يف أربعــة عشــر عمليــه مصرفيــة مفصلــة ثاني ـ ًا ‪ /‬مــا مت‬\n‫إيداعــه مــن حســاب املدعيــة حلســاب املدعــى عليهــا بالبنــك ‪ ...‬هــو‬\n‫(‪ )33000‬ثالثــة وثالثــون ألــف ريــال حســب مــا هــو مبــن يف كشــف‬\n‫احلســاب املرفــق والتــي متــت بســبع عمليــات مصرفيــه ثالث ـ ًا ‪ /‬مجمــوع‬\n‫املبالــغ احملولــة مــن املدعيــة علــى حســاب املدعــى عليهــا هــو(‪)141000‬‬\n\n\n                                                                                      ‫‪100‬‬\n\f      ‫مائــة وواحــد وأربعــون ألــف ريــال وهــو املبلــغ املطالــب بــه مــن املدعــى‬\n      ‫عليهــا مبوجــب كشــوفات احلســاب املرفقــة ومــا أقــروه بردهــم علــى هــذه‬\n      ‫الدعــوى باجلــدول املرفــق بالــرد وباالطــاع علــى املذكــرة التــي قدمهــا‬\n      ‫وكيــل املدعــى عليهــا وجدتهــا تتضمــن إقــرارا باملبالــغ التــي ذكرهــا‬\n      ‫املدعــي وكالــة كمــا جــرى االطــاع علــى كشــوفات احلســابات‬\n      ‫فوجدتهــا كمــا ذكــر املدعــي وكالــة فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واإلجابــة ومبــا أن وكيــل املدعــى عليهــا والتــي تخولــه وكالتــه عنهــا‬\n      ‫حــق اإلقــرار أقــر بدخــول املبالــغ املذكــورة يف الدعــوى ومجموعهــا مبلــغ‬\n      ‫وقــدره مائــة وواحــد وأربعــون ألــف ريــال يف حســاب املدعــى عليهــا ومبــا‬\n      ‫أن وكيــل املدعــى عليهــا دفــع بــأن موكلتــه كبيــرة يف الســن وغيــر‬\n      ‫متعلمــة وجتهــل مغبــة مــا أقدمــت عليــه وهــذا الدفــع ال يرفــع املســؤولية‬\n      ‫عــن املدعــى عليهــا ومبــا أن وكيــل املدعــى عليهــا دفــع بأنــه ليــس هنــاك‬\n      ‫صفــة تعاقديــة ملوكلتــه بينهــا وبــن املدعيــة وهــذا ال يخلــي مســؤوليتها‬\n      ‫مــن إعــادة مــا دخــل بحســابها ومبــا أن اإلقــرار حجــة علــى املقــر ومبــا أن‬\n      ‫املــرء مؤاخــذ بإقــراره ومبــا األصــل أن مــا يصــدر من اإلنســان من تصرف‬\n      ‫أنــه محمــول علــى الصحــة والنفــوذ وأنــه غيــر محجــور عليــه وال ســفيه‬\n      ‫وجلميــع مــا تقــدم فقــد حكمــت علــى املدعــى عليهــا حضوريــا بــأن تدفــع‬\n      ‫للمدعيــة مبلغــا وقــدره مائــة وواحــد وأربعــون ألــف ريــال حالــة بــدون‬\n      ‫مماطلــة وال تأخيــر وبعرضــه علــى املدعــي وكالــة قــرر القناعــة وألن‬\n      ‫املدعــى عليهــا لــم حتضــر قــررت إرســال نســخة مــن احلكــم للمدعــى‬\n      ‫عليهــا لالعتــراض عليهــا خــال ثالثــن يومــا مــن تاريــخ اســتالمها‬\n      ‫للحكــم وأنهــا إذا لــم تقــدم اعتراضــا بعــد تبلغهــا باحلكــم فيعــد احلكم‬\n      ‫مكتســبا للقطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n\n\n‫‪101‬‬\n\f                       ‫وعلى آله وصحبه وسلم ‪ .‬حرر يف ‪1434/07/11‬هـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬نحــن‬\n‫رئيــس وقضــاة الدائــرة اجلزائيــة الرابعة يف محكمة االســتئناف مبنطقة‬\n‫مكــة املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى محكمــة‬\n‫االســتئناف واملقيــدة برقــم ‪ 342858277‬وتاريــخ ‪1434/12/23‬هـ ـ‬\n‫املتعلقــة بطلــب االلتمــاس املقــدم مــن ‪ ......... /‬وكالــة إعــادة النظــر‬\n‫يف احلكــم الصــادر مــن فضيلــة الشــيخ ‪ ........... /‬القاضــي باحملكمــة‬\n‫العامــة بجــدة رقــم ‪ 34265447‬وتاريــخ ‪1434/7/10‬هـ ـ واملصــدق مــن‬\n‫محكمــة االســتئناف مبكــة املكرمــة بالقــرار رقــم ‪34358464‬‬\n‫وتاريــخ ‪1434/11/12‬ه ـ ـ وبدارســة املعاملــة تقــرر باألكثريــة إحالتهــا‬\n‫حلاكمهــا حيــث إن القضيــة جزائيــة لقبــول دعــوى االلتمــاس مــن عدمــة‬\n‫واهلل املوفــق‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34358464‬وتاريــخ‬\n                                              ‫‪1434/11/12‬هـ‪.‬‬\n\n\n\n\n                                                                                   ‫‪102‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":93,"source_page_end":102,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e8f4a9bb0125bd4f03e20e92fbb37a519cf0095ab7f73f6e83f97daf8d3e151a","normalized_text_hash":"78a8c60be708a85c6a1288d37abe3db77db25b3c2989c1d71e537a4cf1e5857e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p93-34265447"},{"id":"16fcde72-bdaf-5981-a90b-67cb31151173","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -نشل محفظة من اجليب -استعمال بطاقة فيزا - إثبات بالقرائن مع مين املدعي -احلكم بإلزام املدعى عليه بدفع املبلغ املدعى به.","document_number":"34262302","case_number":"3478135","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/8","year":"1434","subject":"رد مسروق -نشل محفظة من اجليب -استعمال بطاقة فيزا - إثبات بالقرائن مع مين املدعي -احلكم بإلزام املدعى عليه بدفع املبلغ املدعى به.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/7/8 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34262302 :‬‬\n                           ‫َر ْق ُم الدعوى‪3478135:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34305142‬تاريخه‪1434/8/24:‬هـ‬\n\n\n      ‫رد مســروق ‪ -‬نشــل محفظــة مــن اجليــب ‪ -‬اســتعمال بطاقــة فيــزا ‪-‬‬\n      ‫إثبــات بالقرائــن مــع ميــن املدعــي ‪ -‬احلكــم بإلــزام املدعــى عليــه بدفــع‬\n                                                                  ‫املبلــغ املدعــى بــه‪.‬‬\n\n\n\n\n      ‫‪ -1‬قــول ابــن فرحــون رحمــه اهلل يف التبصــرة (ص ‪« :)98‬فيمــن دخــل‬\n      ‫عليــه الســراق فســرقوا متاعــه وانتهبــوا مالــه وارادوا قتلــه فنازعهــم‬\n      ‫وحاربهــم ثــم ادعــى انــه عرفهــم أو لــم يعرفهــم هــو مصــدق عليهــم اذا‬\n      ‫كانــوا معروفــن بالســرقة مســتحلني لهــا او تــرى يكلــف البينــة قــال‬\n      ‫هــو مصــدق وقــد نزلــت قبــل هــذه باملدينــة يف زمــن عمــر بــن اخلطــاب‬\n                          ‫رضــي اهلل عنــه فغرمهــم عمــر ولــم يكلفــه البينــة» ‪.‬‬\n                                    ‫‪ -2‬اليمني تشرع يف جانب أقوى املتداعيني ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي علــى احلاضــر معــه أنــه قــام بنشــل محفظتــه مــن جيبــه‬\n      ‫واســتخرج منهــا بطاقــة االئتمــان اخلاصــة بــه واســتعملها بســحب مبلــغ‬\n      ‫نقــدي وبشــراء أجهــزة جــوال عــن طريقهــا‪ ،‬ولــذا فقــد طلــب إلزامــه‬\n      ‫بإعــادة املبالــغ التــي خصمــت منهــا إليــه ‪ -‬أنكــر املدعــى عليــه نشــل‬\n      ‫احملفظــة وأقــر باســتعمال البطاقــة يف شــراء أجهــزة جــوال بقيمــة أقــل‬\n\n‫‪103‬‬\n\f‫ممــا جــاء يف الدعــوى بعــد حصولــه عليهــا بطريــق مشــروع ‪ -‬قــدم املدعي‬\n‫كشــف حســاب بنكــي يبــن مجمــوع املبالــغ املســحوبة ‪ -‬املدعــي لــم‬\n‫يقــدم بينــة موصلــة تثبــت دعــواه إال أن جانبــه يتقــوى بالقرائــن املذكــورة‬\n‫يف أســباب احلكــم فتشــرع بحقــه اليمــن املكملــة‪ -‬قضــت احملكمــة‬\n‫بنــاء علــى القرائــن وميــن املدعــي املكملــة بإلــزام املدعــى عليــه بإعــادة‬\n‫جميــع املبالــغ التــي خصمــت مــن بطاقــة االئتمــان ‪ -‬قنــع املدعــي باحلكــم‬\n‫وعــارض املدعــى عليــه ‪ -‬قــررت محكمــة االســتئناف املصادقــة علــى‬\n                                                                      ‫احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالدمــام برقــم ‪ 3478135‬وتاريــخ ‪ 1434/02/17‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34393322‬وتاريــخ ‪ 1434/02/17‬ه ـ حضــر‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وادعــى علــى الســجني‬\n‫ا إن هــذا‬ ‫احلاضــر معــه ســعودي اجلنســية مبوجــب ســجله املدنــي رقــم قائـ ً‬\n‫احلاضــر معــي وأشــار إلــى املدعــى عليــه قــام بتاريــخ ‪1432/12/21‬ه ـ‬\n‫بنشــل محفظتــي حيــث كنــت يومهــا يف ســوق احلــراج بالدمــام وكان‬\n‫مــن ضمــن احملفظــة بطاقــة فيــزا عائــدة لــي ورقمهــا والتابعــة ملصــرف ‪...‬‬\n‫وســحب منهــا مبلــغ نقــدي قــدره خمســة آالف ريــال وكذلك ســحب منها‬\n‫مبلــغ وقــدره تســعة عشــر ألــف ومائتــان وتســعون ريـ‪ 19290‬ــاال بواســطة‬\n‫شــراءه مــن متجــر ‪ ...‬بالدمــام جــواالت عددهــا خمســة مــن نــوع ‪ ...‬لــذا‬\n‫فأطلــب احلكــم عليــه بدفــع املبلــغ املســتحق لــي يف ذمتــه والبالــغ قــدره‬\n\n                                                                                     ‫‪104‬‬\n\f      ‫أربعــة وعشــرون ألــف ومائتــان وتســعون ريــ‪ 24290‬ــاال حــا ًال هــذه دعــواي‬\n      ‫وبســؤال املدعــى عليــه عــن الدعــوى أجــاب بقولــه‪ :‬مــا ذكــره املدعــي‬\n      ‫يف دعــواه مــن قيامــي بنشــل محفظتــه فهــذا غيــر صحيــح وأنكــره متــام‬\n      ‫اإلنــكار وأمــا مــا ذكــره مــن أننــي قــد اســتخدمت بطاقتــه املذكــورة‬\n      ‫يف شــراء اجلــواالت املوصوفــة مــن ‪ ...‬بالتاريــخ املذكــور فهــذا صحيــح‬\n      ‫وأنــا لــم أكــن أعلــم بأنهــا عائــدة لــه وذلــك أننــي أطلــب زميلــي مبلــغ‬\n      ‫مالــي وقــدره خمســة آالف ريــال فســلم لــي البطاقــة وكنــت أعتقــد أنهــا‬\n      ‫لــه فقمــت بشــراء أربعــة جــواالت تقريبــا وال تتجــاوز قيمتهــا اخلمســة‬\n      ‫آالف ريــال ولــم أقــم بســحب أي مبلــغ آخــر ســوى مــا ذكــرت ولــذا فأنــا‬\n      ‫غيــر مســتعد بســداد املبلــغ املدعــى بــه هــذه إجابتــي ثــم أبــرز لــي املدعــي‬\n      ‫نســخة مــن كشــف حســاب بنكــي فوجدتــه يتضمــن شــراء جــواالت‬\n      ‫بلــغ قيمتهــا تســعة عشــر ألــف ومائتــان وتســعون ريــ‪19290‬ـ ــال مــن‬\n      ‫املتجــر املذكــور ومبلــغ خمســة آالف ريــال ومجمــوع املبلــغ املســحوب‬\n      ‫أربعــة وعشــرون ألفــا ومائتــان وتســعون ريــ‪ 24290‬ــاال ثــم أضــاف املدعــي‬\n      ‫بقولــه‪ :‬وأمــا املبلــغ املســحوب نقــدا فليــس لــدي بينــة عليــه إال أن ســحب‬\n      ‫املبلــغ مت يف نفــس اليــوم الــذي مت فيــه شــراء اجلــواالت واملدعــى عليــه قــد‬\n      ‫أقــر بأنــه اســتخدام البطاقــة ممــا يــدل علــى أنــه هــو مــن قــام بســحبه‬\n      ‫لكــون البطاقــة يف حوزتــه هكــذا أجــاب وعنــد وصــول القضيــة لهــذا‬\n      ‫احلــد جــرى رفــع اجللســة النتهــاء وقتهــا ويف جلســة أخــرى افتتحــت‬\n      ‫اجللســة بحضــور الطرفــن املرصــودة بياناتهــم آنفــا وقــد جــرى منــي تأمــل‬\n      ‫القضيــة ودراســتها فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث‬\n      ‫أنكــر املدعــى عليــه قيامــه بنشــل محفظــة املدعــي وأقــر باســتخدامه‬\n      ‫لبطاقــة الفيــزا العائــدة للمدعــي وشــرائه بواســطتها اجلــواالت املوصوفــة‬\n\n\n‫‪105‬‬\n\f‫مــن معــرض ‪ ...‬وحيــث ظهــر لــي قــوة جانــب املدعــي يف هــذه الدعــوى‬\n‫لألمــور التاليــة أوالً‪ :‬إلقــرار املدعــى عليــه باســتخدام بطاقــة املدعــي يف‬\n‫شــراء اجلــواالت األربعــة املوصوفــة مــن املعــرض املذكــور وقــد تبــن بــأن‬\n‫عددهــا أربعــة جــواالت وقيمتهــا طبــق مــا ذكــره املدعــي يف دعــواه بنــاء‬\n‫علــى كشــف احلســاب البنكــي ثاني ـاً‪ :‬أن املبلــغ النقــدي البالــغ قــدره‬\n‫خمســة آالف ريــال قــد ســحب يف نفــس تاريــخ اليــوم الــذي مت فيــه شــراء‬\n‫اجلــواالت األربعــة مــن املعــرض املذكــور بواســطة البطاقــة التــي أقــر‬\n‫املدعــي باســتخدامها يف الشــراء ثالث ـاً‪ :‬مــا ذكــره ابــن فرحــون رحمــه‬\n‫اهلل يف كتابــه التبصــرة يف البــاب اخلامــس والســتني يف القضــاء باللــوث‬\n‫يف األمــوال صفحــة رقــم ‪ 98‬مــن قولــه ‪ »:‬فيمــن دخــل عليــه الســراق‬\n‫فســرقوا متاعــه وانتهبــوا مالــه وأرادوا قتلــه فنازعهــم وحاربهــم ثــم ادعــى‬\n‫أنــه عرفهــم أو لــم يعرفهــم أهــو مصــدق عليهــم إذا كانــوا معروفــن‬\n‫بالســرقة مســتحلني لهــا أو تــرى أن يكلــف البينــة قــال‪ :‬هــو مصــدق‬\n‫وقــد نزلــت مثــل هــذه باملدينــة يف زمــن عمــر بــن اخلطــاب رضــي اهلل عنــه‬\n‫فغرمهــم عمــر ولــم يكلفــه البينــة « ومبــا أن اليمــن تشــرع يف جانــب‬\n‫أقــوى املتداعيــن كمــا ذكــر ذلــك احملققــون مــن أهــل العلــم كابــن‬\n‫تيميــة وابــن القيــم رحمهمــا اهلل لــذا فقــد جــرى ســؤال املدعــي هــل يحلف‬\n‫اليمــن علــى أن املدعــى عليــه هــو مــن قــام بنشــل محفظتــه وكان مــن‬\n‫ضمنهــا بطاقــة فيــزا وأنــه ســحب منهــا مبلــغ نقــدي قــدره خمســة آالف‬\n‫ريــال مــن حســابه وكذلــك ســحب منهــا مبلــغ وقــدره تســعة عشــر ألــف‬\n‫ومائتــان وتســعون ريــ‪19290‬ـ ــاال بواســطة شــراءه مــن متجــر ‪ ...‬اجلــواالت‬\n‫وال يعلــم أحــد ًا غيــره قــد ســحبه مــن احلســاب فأجــاب بقولــه نعــم مســتعد‬\n‫بتأديتهــا بعــد أن جــرى تخويفــه مــن عاقبــة اليمــن الكاذبــة ثــم أذنــت لــه‬\n\n\n                                                                                     ‫‪106‬‬\n\f      ‫ا واهلل العظيــم أن املدعــى عليــه هــو مــن قــام بنشــل‬  ‫باحللــف فحلــف قائـ ً‬\n      ‫محفظتــي وكان مــن ضمنهــا بطاقــة الفيــزا العائــدة لــي وأنــه ســحب‬\n      ‫منهــا مبلــغ نقــدي قــدره خمســة آالف ريــال مــن حســابي وكذلــك ســحب‬\n      ‫منهــا مبلــغ وقــدره تســعة عشــر ألــف ومائتــان وتســعون ريــ‪19290‬ـ ــاال‬\n      ‫بواســطة شــراءه مــن متجــر ‪ ...‬اجلــواالت وال أعلــم أحــد ًا غيــره قــد ســحبه‬\n      ‫مــن احلســاب هكــذا حلــف لــذا وملــا تقــدم كلــه فقــد ألزمــت املدعــى‬\n      ‫عليــه بــأن يدفــع للمدعــي املبلــغ املدعــى بــه وقــدره أربعــة وعشــرون ألــف‬\n      ‫ومائتــان وتســعون ريــ‪ 24290‬ــاال حــا ًال وبــه حكمــت وبعــرض احلكــم‬\n      ‫علــى املدعــي قنــع بــه وأمــا املدعــى عليــه فقــرر عــدم القناعــة باحلكــم‬\n      ‫وطلــب االســتئناف واســتعد بتقــدمي الئحــة اعتراضية علــى احلكم فأفهم‬\n      ‫بأنــه ســيتم طلبــه لكونــه ســجني يف تاريــخ ‪1434/07/11‬ه ـ لتزويــده‬\n      ‫صــورة مــن إعــام احلكــم لتقــدمي اعتراضــه عليــه خــال ثالثــن يومـ ًا مــن‬\n      ‫تاريــخ اســتالمه لــه وإذا لــم يتــم تقــدمي اعتراضــه خاللهــا فيســقط حقــه‬\n      ‫يف االعتــراض ويكتســب احلكــم القطعيــة ففهــم ذلــك وبــاهلل التوفيــق‬\n      ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                     ‫‪ 1434/07/02‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد جــرى املصادقــة علــى هــذا احلكــم الصــادر‬\n      ‫منــا يف هــذه القضيــة برقــم ‪ 34262302‬يف ‪1434/07/08‬ه ـ وذلــك‬\n      ‫مبوجــب قــرار أصحــاب الفضيلــة قضــاة الدائــرة احلقوقيــة األولــى‬\n      ‫رقــم‪ 34305142‬يف ‪1434/08/24‬ه ـ وللبيــان جــرى حتريــره وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد ‪ .‬حــرر يف ‪1434/09/20‬ه ـ ‪.‬‬\n\n\n\n\n‫‪107‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":103,"source_page_end":107,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8d51a3fae41cca5727aedc198239cfbac01b3d2eb90bae806e62c494814d301c","normalized_text_hash":"e9758c3a38f2fff40bde545b0c58299c503a53b4e6bda1ced654d9b22146eec6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p103-34262302"},{"id":"26cc6a61-2ed0-5d5d-98a1-48ec2b9aa06c","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة ذهب من سيارة -عجز عن إقامة البينة - استخالف يف أخذ اليمن النافيه للدعوى -صرف النظر عن","document_number":"343219","case_number":"32129181","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/5","year":"1434","subject":"رد مسروق -سرقة ذهب من سيارة -عجز عن إقامة البينة - استخالف يف أخذ اليمن النافيه للدعوى -صرف النظر عن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫تاريخه‪1434/1/5 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                      ‫الص ِّك‪343219 :‬‬\n                   ‫َر ْق ُم الدعوى‪32129181 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3456542‬تاريخه‪1434/3/7:‬هـ‬\n\n\n‫رد مســروق ‪ -‬ســرقة ذهــب مــن ســيارة ‪ -‬عجــز عــن إقامــة البينــة ‪-‬‬\n‫اســتخالف يف أخــذ اليمــن النافيــه للدعــوى ‪ -‬صــرف النظــر عــن‬\n                                                         ‫الد عــوى‪.‬‬\n\n\n\n\n‫مــا اســتند إليــه القاضــي مــن مبــادئ عامــة وقواعــد العدالــة الــواردة يف‬\n                                                            ‫تســبيب احلكــم‪.‬‬\n\n\n\n\n‫ادعــى املدعــي علــى املدعــى عليهــا املمثلــة بوكيلهــا احلاضــر بأنهــا‬\n‫قامــت بســرقة أربعــة أطقــم ذهــب مــن ســيارته‪ ،‬وطلــب إلزامهــا بإعــادة‬\n‫الذهــب املســروق إليــه ‪ -‬أنكــر وكيــل املدعــى عليهــا مــا جــاء يف دعــوى‬\n‫املدعــي جتــاه موكلتــه ‪ -‬املدعــي لــم يقــدم بينــة تثبــت دعــواه وطلــب ميــن‬\n‫املدعــى عليهــا علــى نفيهــا فذكــر وكيلهــا بأنهــا تقيــم خــارج البــاد ‪-‬‬\n‫قــررت احملكمــة اســتخالف اجلهــة املختصــة يف أخــذ ميــن املدعــى عليهــا‬\n‫فحلفــت طبــق مــا طلــب منهــا ‪ -‬قضــت احملكمــة بصــرف النظــر عــن‬\n‫دعــوى املدعــي جتــاه املدعــى عليهــا ‪ -‬عــارض املدعــي علــى احلكــم ‪-‬‬\n      ‫قــررت محكمــة االســتئناف باألكثريــة املصادقــة علــى احلكــم ‪.‬‬\n\n\n                                                                                     ‫‪108‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالريــاض برقــم ‪ 32129181‬وتاريــخ ‪1432/04/18‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 32344072‬وتاريــخ ‪ 1432/04/07‬ه ـ ففــي يــوم‬\n      ‫االثنــن املوافق‪1432/11/05‬ه ـ افتتحــت اجللســة الســاعة ‪09 : 43‬‬\n      ‫وفيهــا حضــر‪ ...‬اجلنســية مبوجــب اإلقامــة رقــم وحضــر حلضــوره ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم وكيــا عــن هنديــة اجلنســية‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بالريــاض برقــم‬\n      ‫‪ 19749‬يف ‪1432/3/19‬ه ـ جلــد ‪ 19345‬وادعــى األول بواســطة املترجــم‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم قائــا يف دعــواه لقــد‬\n      ‫ســرقت املدعــى عليهــا أربعــة أطقــم ذهــب قيمتهــا أكثــر مــن خمســن‬\n      ‫ألــف ريــال ســعودي وقــد ســرقتها مــن ســيارتي والذهــب املســروق عبــارة‬\n      ‫عــن أطقــم يتكــون كل طقــم مــن حلــق وسلســلة وســواره عيــار واحــد‬\n      ‫وعشــرين كمــا أخــذت اثباتــات بناتــي األربعــة وهــن‪ ..‬و‪....‬و‪ ...‬و‪...‬وقــد‬\n      ‫قامــت بنقــل كفالــة البنــات إليهــا دون الرجــوع إلــى موافقتــي أطلــب‬\n      ‫إلــزام املدعــى عليــه بإعــادة الذهــب املســروق الــذي ذكرتــه يف دعــواي‬\n      ‫وتســليمي بناتــي املذكــورات هــذه دعــواي وبعــرض دعــوى املدعــي علــى‬\n      ‫املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي يف دعــواه غيــر صحيــح‬\n      ‫جملــة وتفصيــا فلــم تســرق موكلتــي مــن املدعــي أي شــيئا مــن الذهــب‬\n      ‫املذكــور وليــس لــه يف ذمــة موكلتــي شــيئا مــن الذهــب املذكــور أمــا‬\n      ‫مــا يتعلــق بطلبــه تســليم بناتــه املذكــورات لــه فيوجــد قضيــة منظــورة‬\n\n‫‪109‬‬\n\f‫اآلن لــدى املكتــب القضائــي الســابع والعشــرين بخصــوص احلضانــة‬\n‫فقــط هكــذا أجــاب فســألت املدعــي هــل لديــه بينــة علــى صحــة دعــواه‬\n‫وأن املدعــى عليهــا أصالــة ســرقت منــه الذهــب املذكــور يف دعــواه‬\n‫فأجــاب قائــا مــا عنــدي بينــة إال أنــا رأيتهــا وهــي تســرق مــن الســيارة‬\n‫فأفهمتــه بــأن لــه ميــن املدعــى عليهــا علــى نفــي دعــواه فقــال أطلــب ميينهــا‬\n‫وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال إن موكلتــي تقيــم اآلن يف‬\n‫بلدهــا الهنــد فرفعــت اجللســة إلــى يــوم الســبت املوافــق ‪1432/11/10‬ه ـ‬\n‫الســاعة الثامنــة والربــع صباحــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1432/11/05‬ه ـ احلمــد هلل‬\n‫وحــده وبعــد ففــي يــوم الســبت املوافــق ‪1432/11/10‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 09 : 19‬وفيهــا حضــر املدعــي وحضــر حلضورهــا املدعــى عليــه‬\n‫وكالــة بالســجل املدنــي رقــم وقــرر املدعــى عليــه أن موكلتــه تقيــم يف‬\n‫واليــة ‪ ....‬يف الهنــد فأمــرت بالكتابــة إلــى محكمــة ‪ ...‬ألخذ ميني املدعى‬\n‫عليهــا أصالــة علــى نفــي دعــوى املدعــي وحتــى ورود اجلواب رفعت اجللســة‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n‫‪ .‬حــرر يف ‪1432/11/10‬ه ـ ويف يــوم االثنــن املوافــق‪ 1434/01/05‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 09 : 30‬وفيهــا حضــر الطرفــان وقــد وردنــا‬\n‫خطــاب وكيــل وزارة اخلارجيــة للشــؤون القنصليــة رقــم ‪33694/3/8‬‬\n‫وتاريــخ ‪1433/01/29‬ه ـ املرفــق بــه أن املدعــى عليهــا أصالــة حلفــت‬\n‫لــدى ســفارة اململكــة العربيــة الســعودية يف نيــو دلهــي قائلــة واهلل‬\n‫العظيــم الــذي ال إلــه إال هــو عالــم الغيــب والشــهادة أننــي لــم أســرق مــن‬\n‫ســيارة املدعــي أربعــة أطقــم ذهــب وليــس يف ذمتــي للمدعــي ممــا يدعيــه‬\n‫شــيء واهلل العظيــم فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن‬\n\n\n                                                                                         ‫‪110‬‬\n\f      ‫وكيــل املدعــى عليهــا أنكــر الدعــوى ولــم يقــم املدعــي بينــة علــى صحــة‬\n      ‫دعــواه وطلــب ميــن املدعــى عليهــا أصالــه وحلفــت طبــق مــا طلــب منهــا لذا‬\n      ‫فقــد حكمــت بعــدم اســتحقاق املدعــي ملــا يدعيــه جتــاه املدعــى عليهــا‬\n      ‫وصرفــت النظــر عــن دعــواه وبعــرض احلكــم علــى املدعــي قــرر عــدم‬\n      ‫قناعتــه بــه وطلــب االســتئناف فأجيــب لطلبــه وقــد اعطــي صــورة مــن‬\n      ‫صــك احلكــم يف حينــه لتقــدمي اعتراضــه عليــه خــال ثالثــن يومــا وإذا‬\n      ‫انتهــت املــدة ولــم يتقــدم خاللهــا باعتراضــه فيســقط حقــه يف االســتئناف‬\n      ‫ويكتســب احلكــم القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                  ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/01/05‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫برقــم ‪ 34291478‬يف ‪1434/3/23‬ه ـ واملقيــدة باحملكمــة برقــم‬\n      ‫‪ 34752822‬يف ‪1434/3/25‬ه ـ واملرفــق بهــا القــرار رقــم ‪ 3456542‬يف‬\n      ‫‪1434/3/7‬ه ـ واملــدون علــى ظهــر الصك املتضمــن باألكثرية املصادقة‬\n      ‫علــى احلكــم وحتــى ال يخفــى جــرى إحلاقــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/4/2‬ه ـ ‪.‬‬\n\n\n\n\n‫‪111‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":108,"source_page_end":111,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ef74ecce34629273fb2f2da066ebc3c6ff7c07ac9031f182439fd4e59c560f5e","normalized_text_hash":"33674c19ffefed240fcbd36cf64c6efe54fd7370c76d286b30f37acd2e3b1311","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p108-343219"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
